/* ÇEVİRİ pt · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pt","olay",{
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Concluída em Gülek a retirada do exército egípcio da Anatólia", "a53ac2a3"], "d": ["Depois do ordenamento de Kütahya, as forças egípcias evacuaram a Anatólia; por volta de meados de junho, todo o exército passou a Çukurova pela Garganta de Gülek. A costa de İçil (Mersin, Silifke) regressa à administração otomana; a muhassıllık de Adana e a Síria permanecem com o Egito.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Tratado de Hünkâr İskelesi", "da741d5c"], "d": ["Assinou-se com a Rússia uma aliança de defesa mútua de oito anos. Segundo a cláusula secreta, os otomanos fechariam os estreitos aos navios de guerra se a Rússia fosse atacada. Foi uma das decisões mais discutidas da diplomacia otomana e tornou a Inglaterra ativa na questão egípcia.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Revolta de Nablus, na Palestina, contra a administração egípcia", "4fe43e27"], "d": ["O serviço militar obrigatório, a recolha de armas e os novos impostos deram origem a uma vasta revolta na Palestina. A revolta foi duramente reprimida; o apoio da administração egípcia junto da população local desfez-se rapidamente.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fim da administração egípcia de Maraş (aproximado)", "bb46ca42"], "d": ["Contando a frase do TDV sobre a duração de 'quase dezanove meses' a partir da ocupação de 1833, a administração egípcia termina por volta do verão de 1834. O facto de Mustafa Bey, dos Küçükalioğulları, não ter podido resistir em 1834 ao exército egípcio e se ter retirado para o lado de Maraş mostra também que Maraş era então um refúgio fora do controlo egípcio.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Revolta do Jabal al-Druze", "12e74626"], "d": ["A resistência surgida na região drusa durou dois anos. O descontentamento acumulado na Síria esvaziaria a retaguarda do exército egípcio quando, em 1840, as armadas aliadas desembarcaram na costa.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali anunciou a intenção de independência", "48633bbd"], "d": ["O governador declarou aos cônsules das grandes potências que pensava proclamar a independência do Egito e da Síria. A Inglaterra opôs-se categoricamente: o nascimento no Mediterrâneo de um Estado forte e próximo da França ameaçaria o caminho da Índia.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["O exército otomano atravessou o Eufrates", "9af1ea69"], "d": ["Mahmud II conduziu o seu exército à fronteira da Síria para recuperar o que perdera em Kütahya. O oficial prussiano Moltke, presente no exército como conselheiro, objetou à escolha da posição e à ofensiva precoce; as suas objeções não foram ouvidas.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Batalha de Nizip — o exército otomano desfez-se", "156b3cdf"], "d": ["O exército otomano, mal posicionado, foi desbaratado em poucas horas. O sultão morreu antes de a notícia da derrota chegar a Istambul; em poucos dias o Estado perderia o seu exército, o seu soberano e, em seguida, a sua armada.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Morte de Mahmud II", "07eccfff"], "d": ["O sultão, que durante o seu reinado de trinta e um anos aboliu os janízaros e restabeleceu a administração central, morreu sem ter podido vencer o seu maior adversário. A sua doença não tinha sido diagnosticada com acerto. A sua morte foi ocultada até 30 de junho, até que se tomaram medidas militares na cidade, por receio de que a mentalidade janízara entrasse em movimento.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Subida ao trono de Abdulmecid e funeral de Mahmud II", "d0f3d2cc"], "d": ["Com a morte do pai, Abdulmecid, de dezasseis anos, subiu ao trono. No mesmo dia, o corpo de Mahmud II foi levado para o Palácio de Topkapı; a desordem temida não ocorreu, e amplas massas populares, muçulmanas e não muçulmanas, juntaram-se ao cortejo fúnebre.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Entrega da armada a Alexandria", "a53e6103"], "d": ["O kapudan paxá Ahmed Fevzi Paşa, suspeitando que o grão-vizir Koca Hüsrev Paşa iria entregar a armada à Rússia, levou a frota a Alexandria e entregou-a a Mehmed Ali. O Estado otomano ficou, no mesmo mês, sem exército, sem sultão e sem armada.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota comum das grandes potências", "2a3b8316"], "d": ["Cinco potências entregaram uma nota à Sublime Porta, pedindo que não fizesse sozinha um acordo na questão egípcia. Uma questão interna tornou-se assim oficialmente uma \"questão europeia\"; o Estado otomano perdeu de facto a faculdade de decidir sobre a sua própria província.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Tratado de Londres: quatro potências ao lado dos otomanos", "a517f775"], "d": ["O tratado, assinado com a exclusão da França, deu um ultimato a Mehmed Ali: se aceitasse em dez dias, o governo hereditário do Egito e Acre a título vitalício; se aceitasse em vinte dias, apenas o Egito; se recusasse, nada. O governador recusou.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardeamento de Beirute e desembarque aliado", "0905ce92"], "d": ["A armada anglo-austríaca bombardeou Beirute; distribuíram-se armas à população que se levantava contra a administração egípcia nas montanhas do Líbano. O controlo de İbrâhim Paşa na Síria ruiu entre a revolta interna e a intervenção externa.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirute e as cidades costeiras perdidas", "09bdaf23"], "d": ["Após os combates na direção de Baalbek, as forças egípcias retiraram-se da costa. No mapa, a costa do Líbano sai do tom vassalo e regressa à administração otomana direta.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Acre caiu em duas horas", "5aec21f0"], "d": ["No bombardeamento da frota aliada, o paiol da fortaleza explodiu e Acre rendeu-se em poucas horas. A fortaleza que İbrâhim Paşa só conseguira tomar em seis meses, oito anos antes, mostrou a superioridade da artilharia naval.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Convenção de Alexandria", "85cb47b0"], "d": ["Mehmed Ali aceitou renunciar à Síria, a Adana, a Creta e ao Hejaz, restituir a armada otomana e reconhecer a soberania do sultão; em contrapartida, ficou assegurado o governo hereditário do Egito.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["O exército egípcio evacuou a Síria e Çukurova", "719a28dc"], "d": ["A ocupação de nove anos terminou; o exército de İbrâhim Paşa regressou ao Egito pelo Sinai. No mapa, a vasta faixa que se estende de Alepo a Gaza e de Adana a Creta passa de novo à administração otomana direta. Outros povoamentos perdidos na mesma data: Urfa, Maraş, Tarsus, Antakya, Kandiye (Girit), Hama, Şam, Kudüs, Yafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firmão: governo do Egito deixado hereditário à família de Kavala", "87b89ff8"], "d": ["O firmão do sultão reconheceu o governo como transmissível de pai para filho dentro da dinastia; em contrapartida, o efetivo do exército foi reduzido a dezoito mil, o imposto foi ligado a Istambul e foram abolidos os poderes de cunhar moeda e de concluir tratados. O Egito permaneceu como província, mas era já país de uma dinastia distinta. A administração do Hejaz e dos Haremeyn regressou à Sublime Porta. Outros lugares que regressam do estrato vassalo ao estrato direto na mesma data: Mekke, Medine, Cidde, Yenbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Convenção de Londres sobre os Estreitos", "0e95a1ea"], "d": ["A convenção que substituiu Hünkâr İskelesi estabeleceu que, em tempo de paz, os estreitos estavam fechados a todos os navios de guerra. O privilégio que a Rússia obtivera sozinha converteu-se assim em garantia comum da Europa; a questão dos estreitos adquiriu um estatuto internacional.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Paşa tornou-se de facto governador do Egito", "9e14f5d9"], "d": ["No lugar de Mehmed Ali, que envelhecia e perdia as faculdades mentais, foi posto no governo o seu filho İbrâhim Paşa. Contudo, poucos meses depois, em novembro de 1848, morreu antes do pai.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Morte de Mehmed Ali Paşa de Kavala", "871310e0"], "d": ["O governador que nasceu em Kavala e fundou no Egito uma dinastia, que levou por duas vezes o império à beira do abismo, morreu aos oitenta anos. A dinastia que fundou reinou no Egito até 1953; o Estado, por seu lado, vendo que só pudera fechar a ferida aberta por ele com a intervenção europeia, avançou pelo caminho do Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış foi vencido e morreu em Ayn Salm; Antioquia saiu dos Seljúcidas da Anatólia", "0412dfa1"], "d": ["Süleyman b. Kutalmış, que em 1084 tomara Antioquia a Bizâncio, morreu na batalha de Ayn Salm que travou com Tutuş, soberano seljúcida da Síria; a cidade passou ao controlo do Grande Sultão Seljúcida Melikşah, e Yağısıyan foi nomeado governador.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikşah morreu; Antioquia, com Yağısıyan, ficou ligada a Tutuş, seljúcida da Síria", "c61da1b4"], "d": ["Com a morte do Grande Sultão Seljúcida Melikşah, o Estado dividiu-se entre os herdeiros; o governador de Antioquia, Yağısıyan, ficou ligado a Tutuş, senhor da Síria.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Niceia rendeu-se aos Cruzados; o centro seljúcida recuou para Konya, Bizâncio começou a retomar a Anatólia ocidental", "8a4e90fa"], "d": ["Depois do cerco de Niceia pelos Cruzados, a cidade rendeu-se a Bizâncio a 19 de junho de 1097; o sultão seljúcida Kılıcarslan I recuou o seu centro para o interior, para Konya, e Bizâncio retomou lugares como Éfeso, na costa da Anatólia ocidental.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıcarslan II tomou a Bizâncio Dorileu (Eskişehir) e Kütahya", "3ddee6c2"], "d": ["Depois de Miriocéfalo (1176), as fortalezas bizantinas de Dorileu e Kütahya, no interior da Anatólia, passaram em 576/1180 — nos últimos anos de Manuel ou depois da sua morte — para as mãos de Kılıcarslan II.", "4358e7d4"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Morte de Ertuğrul Gazi e passagem de Osman Bey ao beylik — herança de Söğüt e Domaniç", "395fb9fa"], "d": ["Segundo o TDV, Ertuğrul Gazi morreu no ano 680 (1281-82); o artigo regista que são dadas também as datas de 1288 e 1289. Osman Bey recebeu de seu pai não uma cidade conquistada, mas duas concessões que o sultão seljúcida fizera a Ertuğrul ao instalá-lo na linha mais avançada da região de fronteira: o yurtluk (quartel de inverno) em Söğüt e o yaylak (pastagem de verão) em Domaniç. Ou seja, o beylik começou não com uma herança de conquista, mas com duas concessões de pastagem; no mapa, estes dois lugares são mostrados como 'herança' e não como 'conquista'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vésperas Sicilianas — a dinastia angevina perdeu a ilha da Sicília", "547db635"], "d": ["A revolta que irrompeu em Palermo, na segunda-feira de Páscoa, à hora das vésperas, contra a administração de Carlos I de Anjou, arrancou a ilha da Sicília à dinastia angevina. O Reino da Sicília dividiu-se em dois: a ilha voltou-se para Aragão, ao passo que a dinastia angevina se manteve no reino continental com centro em Nápoles. Os domínios externos da dinastia no Adriático e no Mediterrâneo permaneceram ligados a este reino: Corfu, que tinham desde 1267, e Durrës, que mantinham desde os anos 1270, continuaram como parte do Reino de Nápoles; as fortalezas de Vlorë, Kanina e Himara, na costa albanesa, permaneceram também no reino com centro em Nápoles (o comandante de Vlorë, John of Taxis, resistiu aos bizantinos durante todo o ano de 1282; Durrës, Vlorë e Kanina passaram muito provavelmente a Bizâncio no início de 1285). Malta, por seu lado, só passou às mãos dos aragoneses em 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Incursão a Kulacahisar — primeira operação militar de Osman Bey", "79b00b14"], "d": ["Artigo Osman I do TDV: 'Saqueou e incendiou o pequeno Kulaca Hisarı, perto de İnegöl (684/1285).' É a primeira ação militar de Osman Bey datável nas fontes. Não se apoderou de nenhum povoamento duradouro, a fortaleza foi saqueada e queimada; trata-se assim, mais do que de uma conquista, de uma incursão clássica de fronteira. É considerada o ponto de partida da atividade militar do beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Conquista de Karacahisar — primeira aquisição de cidade e domínio de Eskişehir", "178ae619"], "d": ["Artigo Osman I do TDV: Osman Bey, no ano 687 (1288), 'conquistou Karacahisar e tornou-se senhor de Eskişehir'. É a primeira verdadeira aquisição de cidade do beylik e, segundo a tradição, com este êxito Osman Bey foi elevado, na fronteira, a bey de sanjaco; conta-se que a primeira hutba de sexta-feira em seu nome foi lida em Karacahisar e que aqui foi nomeado o primeiro cádi. O artigo Eskişehir do TDV indica que a tradição otomana dá a data de 1291, mas observa que a sua exatidão é duvidosa.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Queda de Acre aos mamelucos — liquidação dos cruzados da costa síria: Sídon e Beirute", "3ca7a464"], "d": ["Acre, durante muito tempo centro do Reino Cruzado de Jerusalém, foi conquistada pelo sultão mameluco al-Malik al-Ashraf Khalil, e o domínio dos cruzados na Palestina chegou ao fim. Os cavaleiros templários, que se retiraram de Acre, refugiaram-se em Sídon; quando o exército mameluco se aproximou, abandonaram a fortaleza marítima e fugiram para Chipre, e a cidade passou no mesmo verão aos mamelucos. Beirute, que estava nas mãos dos cruzados desde 1197, foi também tomada em 1291 pelo governador de Damasco, Sencer eş-Şücâî. Assim, a presença cruzada de dois séculos foi apagada da costa da Síria-Palestina.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Conquista de Bilecik e Yarhisar por ataque noturno", "f461b0af"], "d": ["Artigo Bilecik do TDV: 'Embora os outros tekfurs da região, entre os quais o tekfur de Bilecik, tivessem preparado um atentado contra Osman Gazi, ao ter-se conhecimento da conspiração as forças otomanas conquistaram Yarhisar e Bilecik com um ataque súbito (1299).' As duas fortalezas foram tomadas numa só operação, no mesmo ataque noturno. Esta data é o ponto de viragem considerado o ano da fundação do Estado otomano. Outros lugares incorporados na mesma data: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Batalha de Koyunhisar (Bapheus) — primeira grande vitória sobre o exército bizantino", "584a9512"], "d": ["Artigo Osman I do TDV: Osman Bey combateu o exército bizantino em Bapheus (Koyunhisar) em 27 de julho de 1302 e derrotou-o. Esta vitória é o ponto de viragem que fez de Osman Bey, de bey de fronteira regional, fundador de dinastia. Depois da batalha, a planície de Bursa entrou sob controlo otomano e começou o bloqueio de İznik.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Vitória de Dimbos e, em seguida, tomada de Kite e Ulubat", "e168ab64"], "d": ["Artigo Osman I do TDV: no ano 702 (1303), a aliança formada pelos tekfurs de Bursa, Kestel, Kite e Adranos foi desbaratada no desfiladeiro de Dimbos; o inimigo foi repelido combatendo até ao estreito, e o tekfur de Kestel morreu no campo de batalha. Logo após a vitória, foram tomadas as fortalezas de Kite e de Ulubat, cortando-se a ligação terrestre de Bursa e apertando-se o seu bloqueio. O jovem Orhan participou também nesta batalha.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Campanha do Sakarya: tomada de Leblebicihisar, Lefke, Mekece e Geyve", "a51ba4d3"], "d": ["O artigo Osman I do TDV dá a ordem da campanha do Sakarya de 704 (1304): 'Quando chegou a Leblebüci Hisarı, o tekfur submeteu-se... Chegou a Lefke... Alcançou Mekece... Foi a Geyve e tomou a fortaleza que encontrou vazia.' Lefke é a porta do vale do Sakarya que se abre para Bilecik. Esta única campanha, pondo sob controlo otomano a cadeia de fortalezas ao longo do vale, fechou o flanco oriental da bacia de İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Quios passou ao controlo da família genovesa Zaccaria", "9eebe4de"], "d": ["Perante a ameaça dos Aydınoğulları, o imperador bizantino pediu ajuda ao genovês Benedetto Zaccaria; a ilha passou ao seu controlo (vassalagem bizantina nominal). O domínio de Zaccaria durou até 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos entrou na propriedade dos genoveses (Zaccaria) de Quios", "0e6f51e3"], "d": ["A família genovesa Zaccaria, que passara a controlar Quios, juntou à sua propriedade também Samos, quase despovoada (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Conquista das fortalezas do desfiladeiro de Geyve: Karaçepüş, Karatigin e Absu", "76907c78"], "d": ["Artigo Orhan do TDV: Orhan, na campanha do Sakarya de 705 (1305), 'conquistou as fortalezas de Karaçepüş (Katoikia), Karatigin diante de İznik e Absu (Hypsu: no desfiladeiro de Geyve)'. Estas três fortalezas, fechando a passagem entre o vale do Sakarya e a bacia de İznik, cortaram completamente o socorro terrestre de İznik. Em Karaçepüş e Absu, no desfiladeiro de Geyve, foi instalado Gazi Abdurrahman; a cidade só poderia agora ser derrubada pela fome.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Campanha de Adranos (Orhaneli) — última campanha de Osman Bey", "4811546c"], "d": ["O artigo Orhan do TDV regista a campanha da Fortaleza de Adranos, no outono de 1323, como a última campanha de Osman Bey. O tekfur de Adranos era membro da aliança de tekfurs formada vinte anos antes em Dimbos contra os otomanos; esta campanha significava o ajuste dessa conta. O dia exato da conquista da fortaleza não é conhecido; a operação foi prosseguida por Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Morte de Osman Gazi e passagem de Orhan Bey ao beylik", "021487cd"], "d": ["Osman Gazi, que deu nome ao beylik, morreu no ano 724 (1324), segundo atestam os vakfiyes de Asporça Hatun e de Mekece. Orhan, seu filho, que desde 1305 estava à frente do exército nas campanhas, com a morte do pai sentou-se à frente do beylik sem que houvesse qualquer luta pelo trono. A transmissão sem abalos do estandarte pela geração fundadora mostra que a dinastia passou com serenidade a sua primeira grande prova no caminho que vai do beylik de fronteira ao Estado.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Quios foi tomada a Zaccaria e ligada a Bizâncio", "f6741b26"], "d": ["O imperador Andrónico III afastou Zaccaria da ilha e ligou-a a Bizâncio, sob o governo de Benedetto III. A ilha seria ocupada em 1346 pelo genovês Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos voltou de Zaccaria a Bizâncio (cadeia de Quios)", "08034974"], "d": ["Com a queda do senhorio de Zaccaria (a ligação de Quios a Bizâncio em 1329), terminou também a propriedade genovesa em Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Batalha de Pelekanon (Maltepe) e tomada de todo o Kocaeli", "389e7bd4"], "d": ["Artigo Orhan do TDV: no primeiro dia da batalha, Orhan Gazi enviou uma força de trezentos homens para atrair o exército bizantino; no segundo dia, com a descida à planície das unidades sob o comando de Pazarlu, a batalha alargou-se e, ferido o imperador por uma flecha, o pânico instalou-se no exército bizantino. O resultado é decisivo: 'Orhan tomou todo o Kocaeli; depois da vitória, os de İznik não tinham já qualquer esperança.' As vilas costeiras, de Hereke a Üsküdar, entraram sob domínio otomano, e Gebze foi feita centro da região. Foi o último exército imperial bizantino que veio salvar Constantinopla.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Fundação em İznik da primeira madraça otomana", "c85fb625"], "d": ["Orhan Bey, logo depois de tomar İznik, nomeou ali cádi Çandarlı Kara Halil, converteu uma basílica em mesquita e, mandando construir a seu lado um imaret e uma madraça, iniciou as obras da cidade. Segundo o artigo Dâvûd-i Kayserî do TDV, a construção da madraça foi concluída em 1336 e Orhan Gazi trouxe Dâvûd-i Kayserî para a cátedra, com 30 akçes por dia. Esta madraça é o primeiro passo institucional da vida do saber otomana; o beylik acrescentou assim à força da conquista uma tradição de saber. A transformação de uma capital bizantina, tomada pela conquista, em centro do saber islâmico foi o primeiro sinal concreto da pretensão otomana de ser um Estado estabelecido.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Sujeição de Bizâncio a tributo — cerco de İzmit e tratado", "0c1ec8d3"], "d": ["Artigo Orhan do TDV: Orhan sitiou İzmit no verão de 733 (1333) com um grande exército e máquinas de arremesso, e o imperador consentiu num tratado. Em troca de ele desistir do cerco, Bizâncio aceitou pagar a Orhan 12.000 moedas de ouro (hyperpers) por ano; 'assim, aos olhos do emir otomano, Bizâncio ficou na condição de país tributário'. Em contrapartida, Orhan seria amigo do imperador e não atacaria as cidades sujeitas a Bizâncio. A sujeição do Império Romano do Oriente a imposto por um beylik de fronteira era a proclamação de quanto o equilíbrio de forças se invertera.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotrácia passou dos venezianos para a família genovesa Gattilusio", "c499ed5f"], "d": ["A família genovesa Gattilusio expulsou da ilha os venezianos, que a detinham desde 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Anexação do Beylik de Karesi: Balıkesir, Bergama, Biga, Edremit e Erdek", "c7cb0511"], "d": ["O artigo Orhan do TDV (İnalcık) situa a anexação em 735 (1334-35): com a morte de Demirhan Bey, os gazis de Karesi e Hacı İlbey convidaram Dursun Bey ao trono e pediram auxílio a Orhan. Orhan marchou primeiro sobre Balıkesir; quando Dursun Bey, que ia às conversações de paz, morreu atingido por uma flecha disparada da fortaleza de Bergama, o beylik foi inteiramente incorporado no território otomano. Na mesma operação, Kirmasti e Mihaliç submeteram-se, Gölyazı foi tomada e Ulubat, antes deixada sob salvo-conduto, foi definitivamente ocupada. Orhan, nomeando Süleyman Paşa para o sanjaco de Karesi e fazendo de Biga o centro de fronteira, ganhou assim os quadros marítimos da passagem para a Rumélia. Nota: o artigo Karesioğulları do TDV dá para o mesmo acontecimento a data de 746 (1345); a enciclopédia contradiz-se a si mesma. Outros lugares incorporados na mesma data: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos entrou na propriedade da Maona de Quios", "01628b2f"], "d": ["Com a tomada de Quios por Simone Vignosi, de Génova, e a entrega da administração à companhia Maona, Samos entrou também na propriedade dos genoveses de Quios (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Primeira capitulação de Orhan Gazi com os genoveses", "e64cb196"], "d": ["Orhan Gazi, que se entendera com os genoveses durante a guerra veneziano-genovesa, enviou depois da batalha do Bósforo de fevereiro de 1352 1000 arqueiros para a defesa de Pera e forneceu 60.000 moedas de ouro para o transporte de soldados; em troca, concedeu aos genoveses a primeira capitulação. O texto completo do tratado não chegou até nós. É o primeiro acordo oficial que os otomanos concluíram com uma potência naval europeia e seria renovado trinta e cinco anos depois, em 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Tomada de Galípoli — cabeça de ponte duradoura na Rumélia", "ba51a160"], "d": ["Galípoli, cuja vizinhança os otomanos tinham conhecido entre 1349 e 1352 na qualidade de aliados de Cantacuzeno, foi tomada por eles em 1354; o grande terramoto que arrasou as muralhas da cidade proporcionara a oportunidade. A estreita cabeça de ponte de Çimpe transformou-se assim numa verdadeira base na margem europeia do Bósforo e a porta que se abre para a Trácia ficou inteiramente entreaberta. Galípoli perder-se-ia em 1366 com a cruzada de Saboia, mas entraria definitivamente no domínio otomano com a segunda conquista de 1376. Outros lugares incorporados na mesma data: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Morte de Süleyman Paşa, conquistador da Rumélia", "2dc98228"], "d": ["Süleyman Paşa, filho mais velho de Orhan Bey e arquiteto das conquistas da Rumélia, morreu, ao cair do cavalo durante uma caça, no outono de 1357, a mais aceite das datas dadas nas fontes como 758 (1357), 759 e 760 (1359). A morte do príncipe, que estabelecera a presença otomana duradoura na Rumélia com as suas passagens de 1352-1354, deixou a ordem de sucessão ao seu irmão Murad. O mausoléu de Süleyman Paşa, sepultado em Bolayır, permaneceu como o mais antigo monumento dinástico otomano na Europa.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Lei do Pençik — lançada a base do Corpo dos Janízaros", "e5877c2d"], "d": ["Depois das conquistas da Rumélia, por recomendação de Karamanlı Kara Rüstem, dos ulemás, foi posto em vigor o sistema do pençik, que previa a reserva para o Estado de um quinto dos prisioneiros de guerra ou do seu equivalente em dinheiro. Com a criação junto de famílias turcas dos que eram escolhidos entre estes prisioneiros e o seu recrutamento, formou-se o núcleo de uma força de infantaria permanente, diretamente ligada ao sultão — o Corpo dos Janízaros. A transformação de um beylik de fronteira, assente na cavalaria tribal, num Estado com exército central começou com esta ordenação.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Descida à Trácia ocidental: conquista de Gümülcine", "9ef69221"], "d": ["As forças de fronteira, que se voltaram para oeste do Maritsa depois da tomada de Edirne, sob o comando de Gazi Evrenos Bey, apoderaram-se de Gümülcine, centro da Trácia ocidental. A cidade tornou-se o quartel avançado para onde Evrenos Bey levaria as suas incursões à Macedónia. Assim, a parte da Trácia que se estende até à costa do Egeu entrou sob controlo otomano e abriu-se o caminho de Salónica.", "0206d2bb"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["A oeste de Filibe: incorporação de Tatarpazarcığı e İhtiman", "1664d0e1"], "d": ["Depois da tomada de Filibe em 1372, Tatarpazarcığı, na extremidade superior do vale do Maritsa, e İhtiman, que guardava a passagem que se abre para Sófia, foram ligadas à administração otomana. Esta linha, que estava nas mãos dos beys locais vassalizados depois da batalha de Çirmen, passou a administração direta, tornando ininterrupta a rota Filibe-Sófia. Este avanço é a preparação do caminho que, doze anos depois, conduziria à conquista de Sófia.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Revolta de Savcı Bey — rebelião conjunta do príncipe e do herdeiro bizantino", "75198c33"], "d": ["Savcı Bey, filho de Murad I, e André Paleólogo, filho do imperador bizantino João V, revoltaram-se, no início de maio de 1373, simultaneamente em Bursa e em Constantinopla contra os seus pais. Esta aliança, que unia os herdeiros das duas dinastias, foi rapidamente reprimida; Savcı Bey, capturado, foi cegado e executado. A data de 787 (1385) que a tradição otomana dá para a revolta é errada; o acontecimento cai logo depois dos anos em que Bizâncio entrou na vassalagem otomana e mostra quão entrelaçados estavam os dois palácios.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Vales do Struma e do Mesta: incorporação de Köstendil, Petriç, Nevrokop e Drama", "8c0980c4"], "d": ["Os vales do Struma e do Mesta, nas mãos dos beys locais sérvios e búlgaros que começaram a pagar tributo aos otomanos depois da vitória de Çirmen, foram postos sob administração otomana direta pelo avanço dos beys de fronteira. Com a incorporação de Köstendil, Petriç, Nevrokop e Drama, abriu-se a metade oriental da Macedónia e Salónica e Serez entraram no círculo de cerco. No mapa, o alargamento da Rumélia para sudoeste é o resultado desta operação.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Tamerlão tomou Herat: fim da dinastia Kert e passagem do Coração a Timúrida", "15f6019e"], "d": ["O Coração encontrava-se em 1380 fragmentado pela luta entre os Serbedârîs, os Kerts e os Muzafférids. Depois de enviar à região o seu filho Mîrân Şah, Tamerlão marchou ele próprio sobre Herat e, após um cerco de algum tempo, recebeu a cidade do melik kert Gıyâseddin Pîr Ali. A revolta surgida depois da sua partida foi reprimida com sangue por Mîrân Şah e pôs-se fim à dinastia Kert, que reinava em Herat desde 1255. Todo o Coração, de Meshed a Nishapur, entrou nesta data na administração timúrida.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Fim do Beylik de Eretna e fundação do Estado de Kadı Burhâneddin", "60dcaf57"], "d": ["Os Eretnaoğulları, nascidos em 1335 do governo ilcânida e que governaram durante quarenta e seis anos a Anatólia central com centro em Sivas e Kayseri, dissolveram-se com as disputas internas do palácio. Kadı Burhâneddin, que se tornou vizir em maio de 1378, depois de eliminar os rivais Kılıcarslan e Hacı Şadgeldi, proclamou o seu sultanato no outono de 1381, pôs fim ao beylik e fundou o Estado que ficou conhecido pelo seu nome. Assim, o vizinho oriental dos otomanos mudou de mãos; a linha Sivas-Kayseri permaneceria dezassete anos nas mãos de Kadı Burhâneddin.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Avanço para o interior da Macedónia: conquista de Manastır e Ohri", "63bb7838"], "d": ["Manastır, na Via Egnatia, e Ohri, à beira do lago, entraram na administração otomana durante as incursões na direção da Albânia. Ambas eram pontos-chave da estrada que se estende até ao Adriático; Ohri era ainda o mais antigo centro de arcebispado ortodoxo dos Balcãs. O TDV regista que não há informação segura sobre a data de conquista de Ohri, sendo avançadas as datas de 787 (1385) e de 797 (1395), depois da morte de Marko Kraljević; aqui adotou-se 1385. Manastır seria, nos séculos seguintes, um dos mais importantes centros militares da Rumélia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Batalha de Savra — abertura das portas da Albânia", "dda6671b"], "d": ["A pedido de auxílio do bey albanês Karlo Topia, pressionado pela dinastia Balšić, as forças otomanas desbarataram na planície de Savra o exército de Balša II; Balša perdeu a vida no campo de batalha. Esta batalha, em que se entrou a convite de um bey local, deu aos otomanos a primeira influência duradoura nos territórios albaneses, que se estendem até às costas do Adriático. Esta política, que aproveitava a desavença dos beys da região, seria o método invariável das conquistas balcânicas ao longo do século seguinte.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["A 'campanha de três anos' de Tamerlão: tomada do Azerbaijão e do Irão setentrional", "2a98ec51"], "d": ["Tamerlão, que durante as campanhas do Coração vira de perto o estado disperso do Irão, marchou para ocidente em 788 (1386). Na operação de 1386-1388, chamada 'campanha de três anos', passou por Mazandaran, Luristão e Geórgia ao Azerbaijão e chegou a Karabakh; Tabriz, Ardabil, Urmia e Nakhchivan entraram na administração timúrida. A sua tomada do Irão setentrional e do Azerbaijão foi também o início de uma longa disputa com a Horda Dourada, como outrora entre o ulus de Djötchi e os Ilcãs.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Batalha de Frenkyazısı e cerco de Konya — primeira campanha de Karaman", "af4e5d77"], "d": ["Contra o Karamanoğlu Alâeddin Ali Bey, que, apesar de ser seu genro, estava incomodado com a expansão otomana na Anatólia ocidental, Murad I partiu pessoalmente em campanha; na batalha travada no lugar chamado Frenk Yazısı, o exército otomano, treinado e experiente, derrotou as forças karamânidas. Em seguida foi sitiada a Fortaleza de Konya, mas, com o perdão a Alâeddin Bey, o beylik não foi inteiramente abolido. Esta campanha é o primeiro ato do longo ajuste de contas entre os otomanos e Karaman, que duraria um século e só terminaria com a anexação definitiva de 1468.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Fundação do Estaleiro de Galípoli — nascimento da armada otomana", "47546241"], "d": ["O primeiro estaleiro organizado do Estado otomano foi fundado em 1390 por Yıldırım Bayezid em Galípoli, no lugar do estaleiro herdado de Bizâncio. Os otomanos, herdando a tradição marítima dos beyliks da Anatólia ocidental, tornaram-se assim, pela primeira vez, uma potência naval que construía os seus próprios navios. O estaleiro, situado no ponto-chave do estreito dos Dardanelos, serviu durante século e meio de base principal da armada otomana, desde o cerco de Constantinopla até às campanhas do Egeu.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Tomada de Varna na costa do mar Negro", "a84b2abf"], "d": ["No decurso da compressão dos territórios do czarado búlgaro entre o Danúbio e o mar Negro, Varna, o maior porto da costa, passou à administração otomana. A tomada do porto abriu o caminho do avanço na direção da Dobruja e deu aos otomanos o primeiro grande embarcadouro na costa ocidental do mar Negro. Varna seria cinquenta e três anos depois o cenário da vitória de 1444, em que o exército cruzado seria aniquilado.", "421a978f"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fim da dinastia Muzafférid: derrota de Şah Mansûr diante de Shiraz", "5fd14eb8"], "d": ["Şah Mansûr, último soberano poderoso dos Muzafférids, que reinavam desde 1318 em Yazd, Fars, Isfahan e Kerman, aliou-se aos seus parentes e agiu contra Tamerlão. Na batalha junto a Shiraz, tendo um dos seus emires passado para o lado oposto, perdeu a maior parte das suas forças e foi derrotado e morto. Tamerlão mandou também matar todos os membros da dinastia, e o domínio muzafférid terminou; Fars e Kerman foram incorporados na administração timúrida.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Incorporação de Amásia no território otomano", "fe2860cf"], "d": ["O emir de Amásia, sitiado durante a operação de Yıldırım Bayezid na Anatólia central, entregou a cidade aos otomanos e Bayezid entrou nela em 1393. O sultão deixou a sua administração ao filho Mehmed Çelebi; Amásia, como sanjaco de príncipe, tornou-se daí em diante um dos mais importantes centros de formação da dinastia otomana. Esta escolha seria decisiva no futuro Fetret Devri, e Çelebi Mehmed conduziria a luta pela reunificação do Estado precisamente a partir desta base de Amásia.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Tamerlão tomou Bagdade — os Jalayiridas fugiram para a Anatólia", "4d5602b3"], "d": ["Tamerlão, após um longo cerco, apoderou-se de Bagdade; o senhor da cidade, o sultão jalayirida Ahmed, fugiu para ocidente e refugiou-se primeiro junto dos mamelucos e depois na corte otomana. A expansão de Tamerlão para ocidente entrou assim pela primeira vez em contacto direto com a esfera de influência otomana. O primeiro elo da inimizade entre os dois soberanos começa aqui.", "2fac674f"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["A região de Nevşehir e Ürgüp passou dos Karamanoğulları para os otomanos", "06ff59e8"], "d": ["Nas campanhas de Bajazeto I contra os Karamanoğulları, a região de Nevşehir (Muşkara) e Ürgüp passou em 800/1398 para a administração otomana; em 1402, depois da Batalha de Ancara, Timur devolveu a região aos Karamanoğulları.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Queda do Estado de Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, feito prisioneiro pelo soberano ak koyunlu Karayülük Osman Bey, ofereceu-se para ser libertado em troca da rendição de Sivas, mas a população da cidade resistiu e o sultão foi executado diante das muralhas. Embora os notáveis de Sivas tivessem posto à frente o seu filho Alâeddin Ali Çelebi, pediram, perante a pressão ak koyunlu, auxílio a Yıldırım Bayezid; as forças otomanas sob o comando de Süleyman Çelebi derrotaram Karayülük e dominaram a cidade. Assim, o Estado de Kadı Burhâneddin desapareceu da história e Sivas, Tokat, Niksar e Kayseri foram incorporadas no território otomano. Outros lugares incorporados na mesma data: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Ruptura de Tamerlão: recusada a entrega dos fugitivos", "33790bc8"], "d": ["Por pressão de Tamerlão, o sultão jalayirida Ahmed e o líder dos Kara Koyunlu, Kara Yûsuf, refugiaram-se em território otomano; Tamerlão pediu a entrega destes dois fugitivos e Yıldırım Bayezid recusou. Em consequência, começaram a trocar-se entre os dois soberanos cartas com graves insultos recíprocos. O terreno ideológico da guerra foi estabelecido com esta correspondência, sem que um só soldado se tivesse ainda movido.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Dârüşşifâ de Yıldırım em Bursa — primeiro hospital otomano", "5f0dc59a"], "d": ["Yıldırım Bayezid, nos anos em que mandava construir em Bursa a magnífica Grande Mesquita, dotou a cidade também de um dârüşşifa; este foi o elo dedicado à medicina do vasto programa de obras de beneficência composto por imaret, madraça, han e ponte. Este edifício, o primeiro hospital fundado pelo Estado, desempenhando também a função de escola de medicina que formava médicos, definiu o modelo das instituições de saúde otomanas. A obra, concluída apenas dois anos antes do desastre de Ancara, é um dos últimos elos da conceção de Yıldırım de transformar Bursa numa capital imperial.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Tamerlão arrasou Sivas", "f4d79de6"], "d": ["Tamerlão, que marchou sobre Sivas guiado pelo Ak Koyunlu Karayülük Osman Bey e pelo emir de Erzincan Mutahharten, sitiou a cidade durante dezoito dias e, depois de a receber em rendição com a promessa de que não se derramaria o sangue de ninguém, fez um grande massacre; mandou encher as valas com os defensores e cobri-los vivos. As obras importantes da cidade, a começar pelas muralhas, foram destruídas e Sivas colapsou demograficamente. É o primeiro grande golpe que Tamerlão desferiu no território otomano, dois anos antes da batalha de Ancara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid recuperou Erzincan e Kemah", "7047ca08"], "d": ["Yıldırım Bayezid, aproveitando a ida de Tamerlão em campanha à Síria, tomou Erzincan e Kemah ao emir de Erzincan Mutahharten, vassalo de Tamerlão. Apesar de não ter interferido na destruição de Sivas, este gesto significava um desafio direto à esfera de influência de Tamerlão na Anatólia oriental. A relação entre os dois soberanos tornou-se daí em diante irreparável.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimato de Tamerlão enviado de Tabriz — quatro condições", "3e1ac50e"], "d": ["Tamerlão, por um enviado de Tabriz, comunicou quatro condições: restituição de Kemah a Mutahharten, devolução aos seus donos dos territórios tomados aos beys da Anatólia, envio de um príncipe otomano como refém e aceitação do külah e do cinto como sinais de vassalagem, e entrega de Kara Yûsuf. Bayezid não aceitou nenhuma delas; apesar da insistência dos estadistas e da mediação de Mutahharten, as negociações falharam. Tamerlão estava decidido a encerrar definitivamente a questão da Anatólia antes de partir em campanha para a China.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Refundados os Saruhanoğulları — Manisa saiu dos otomanos", "ac747b05"], "d": ["Três semanas depois do desastre de Ancara, com o apoio de Tamerlão, Orhan Bey assumiu a chefia do beylik e a província de Saruhan voltou a ser independente. A região com centro em Manisa desapareceu do mapa doze anos depois da anexação otomana de 1390. É uma das primeiras aplicações, de data com certeza conhecida, da política de Tamerlão de fazer reviver os beyliks.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["O emir Süleyman fugiu para a Rumélia com o tesouro do Estado", "0a2b7363"], "d": ["O emir Süleyman, que levou consigo o tesouro do Estado em Bursa, os arquivos, a família e os irmãos, passou de Gemlik por navio a Güzelcehisar (Anadoluhisarı), alcançou dali Galípoli e proclamou o seu domínio em Edirne. A transferência do arquivo do Estado e do tesouro para a Rumélia é o início da deslocação do centro de gravidade otomano para os Balcãs durante uma geração. No mapa, a Rumélia é traçada, a partir desta data, com a cor própria do emir Süleyman.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Tamerlão refundou os beyliks da Anatólia — dissolvida a unidade turca", "15187774"], "d": ["Tamerlão, depois da vitória de Ancara, restituiu aos beys que estavam consigo os seus antigos territórios. Aos Karamanoğlu Mehmed e Ali beys foram dados a província de Karaman e Kayseri, Kırşehir, Sivrihisar e Beyşehir; ao Germiyanoğlu Yâkub Bey II, Kütahya e a província de Germiyan; ao Candaroğlu İsfendiyar Bey, além da linha Kastamonu-Sinope, Çankırı e Kalecik. As províncias de Aydın, Menteşe e Teke voltaram também às suas antigas dinastias. A unidade turca da Anatólia que Yıldırım Bayezid criara em dez anos dissolveu-se num único verão; no mapa, estes beyliks reaparecem nas suas próprias cores.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Tamerlão tomou Esmirna aos Cavaleiros de São João", "66dd1dd4"], "d": ["Tamerlão, que descia para ocidente por Kütahya, Denizli, Aydın, Ayasuluk e Tire, sitiou e tomou Esmirna, porto que estava em mãos cristãs desde 1344. Tendo tomado rapidamente esta fortaleza, que Yıldırım Bayezid não conseguira tomar durante anos, Tamerlão, depois de ocupar também as fortalezas vizinhas, deixou a província de Aydın aos antigos donos e voltou para oriente. A cidade passou daí em diante à administração do Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi tomou Bursa — nasceu a parte da Anatólia", "955128c1"], "d": ["Îsâ Çelebi, que se retirara para os lados de Karesi depois do desastre de Ancara, apoderou-se de Bursa enquanto Tamerlão estava em Esmirna. Na antiga capital, saqueada e queimada pelos soldados de Tamerlão, proclamou o seu domínio e mandou cunhar moeda em seu nome; em janeiro de 1403 era reconhecido na Anatólia como 'soberano dos turcos'. No mapa, esta parte, que se estende ao longo da costa asiática do Mármara, aparece com a cor própria de Îsâ Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Retirada de Tamerlão da Anatólia", "93a98839"], "d": ["Tamerlão, ao receber a notícia de que Yıldırım Bayezid morrera em Akşehir, deu por concluída a sua tarefa na Anatólia e voltou-se para oriente. Atrás ficaram os beyliks que lhe declararam fidelidade e os príncipes otomanos desavindos entre si; algumas cidades como Sivas foram deixadas nas mãos de emires como Mezid Bey, sujeitos a Tamerlão. Tamerlão nunca mais voltou à Anatólia, mas esta ordem fragmentada que criara durou dez anos.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["O emir Süleyman passou à Anatólia: Bursa caiu nas suas mãos", "9b27aa5f"], "d": ["O emir Süleyman, ao saber da derrota de Îsâ Çelebi, passou à Anatólia com um forte exército, juntamente com Çandarlı Ali Paşa, e tomou Bursa; os registos de março de 1404 mostram que Karadeniz Ereğlisi estava também sob a sua administração. Çelebi Mehmed não pôde resistir a Süleyman, que dominou rapidamente tanto a Rumélia como a maior parte da Anatólia. No mapa, desta data até à nova tomada de Bursa por Çelebi Mehmed (1410), as duas margens aparecem numa só cor, na parte do emir Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Batalha da planície de Yenişehir — Çelebi Mehmed retirou-se para Amásia", "f1568288"], "d": ["Çelebi Mehmed, que perdera Bursa e Ancara, derrotado na planície de Yenişehir pelo emir Süleyman, perdeu todos os ganhos na Anatólia ocidental e retirou-se para a sua base de Tokat-Amásia. Depois desta derrota, evitando o confronto direto, voltou-se para consolidar a sua autoridade no interior da Anatólia. Assim começou a mais longa fase silenciosa do Fetret.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["O emir Süleyman tomou Ancara a Çelebi Mehmed", "d6a2acd6"], "d": ["O emir Süleyman sitiou em 1406 Ancara, que restava em poder de Çelebi Mehmed depois da retirada de Tamerlão da Anatólia. O comandante da fortaleza, Yâkub Bey, resistiu algum tempo, mas, por um ardil do grão-vizir Çandarlı Ali Paşa, entregou a fortaleza a Süleyman. Em consequência, Çelebi Mehmed, entendendo-se com o Karamanoğlu Mehmed Bey, agiu contra Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed recuperou Sivas ao timúrida Mezid Bey", "90079b0c"], "d": ["Depois da invasão de Tamerlão, a administração de Sivas fora deixada a Mezid Bey, vassalo de Tamerlão. Çelebi Mehmed, em Amásia, enviou o seu comandante Bayezid Paşa para tomar a cidade e, após uma resistência violenta, Sivas passou pela segunda vez às mãos da dinastia otomana. Assim, a parte de Mehmed alcançou, seis anos depois da batalha de Ancara, a sua antiga fronteira no leste.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fim da dinastia artúquida: entrega de Mardin aos Kara Koyunlu", "15b06f33"], "d": ["Os Artúquidas, que reinavam em Mardin desde 1106 e eram o ramo mais duradouro da dinastia, não resistiram à pressão ak koyunlu. O melik Ahmed, compreendendo que não poderia defender a cidade, entendeu-se com o soberano kara koyunlu Kara Yûsuf e entregou-lhe Mardin. O domínio artúquida, de mais de três séculos, terminou assim; Mardin e os seus arredores foram o cenário da luta Kara Koyunlu-Ak Koyunlu até passarem aos otomanos um século depois.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Batalha de Yambol — Mûsâ Çelebi entrou em Edirne", "8f978408"], "d": ["Mûsâ Çelebi, que passou à Rumélia pela Valáquia, com apoio valáquio e sérvio desbaratou em Yambol as forças do emir Süleyman e entrou em Edirne. Durante o Fetret Devri, a Rumélia saiu pela primeira vez das mãos do emir Süleyman. Contudo, o seu domínio não foi duradouro; quatro meses depois, derrotado em Cosmídion, retirar-se-ia para o interior dos Balcãs.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Batalha de İnceğiz — primeira derrota de Çelebi Mehmed na Rumélia", "3c35cd43"], "d": ["Çelebi Mehmed, que passara à Rumélia nos navios de Bizâncio, travou batalha com Mûsâ Çelebi em İnceğiz; Musa, com os sete mil janízaros sob o seu comando, derrotou Mehmed, e Mehmed foi forçado a regressar à Anatólia. Esta derrota orientou Mehmed, em vez da luta direta, para a estratégia de atrair para o seu lado os beys de fronteira da Rumélia e o despotado sérvio. O terreno da vitória de Çamurlu, nove meses depois, foi preparado com esta diplomacia.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Cerco de Konya e tratado com os Karamanoğulları — Hamîd-ili, Said-ili, Beyşehir, Seydişehir e Akşehir recuperados", "0996257e"], "d": ["Contra os Karamanoğulları, que atacaram o território otomano durante o Fetret Devri e sitiaram e queimaram Bursa, Çelebi Mehmed organizou uma grande campanha e sitiou Konya em Muharrem de 818. O Karamanoğlu Mehmed Bey II foi forçado a pedir paz; em resultado do tratado, Hamîd-ili (região de Isparta) e Said-ili foram de novo incorporados no território otomano, Beyşehir, Seydişehir e Akşehir foram também devolvidos; também Sivrihisar, que Tamerlão dera aos Karamanoğulları em 1402, voltou aos otomanos. Esta campanha, em que começou a remendar-se a unidade da Anatólia dissolvida com a batalha de Ancara, é uma das razões concretas de Çelebi Mehmed ser considerado o 'segundo fundador'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Tomada de Esmirna ao Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["Esmirna, centro do Aydınoğlu Cüneyd Bey, que mudava continuamente de lado entre os príncipes durante o Fetret, foi tomada por Çelebi Mehmed após um cerco de dez dias; Cüneyd foi perdoado e enviado para o sanjaco-beylik de Niğbolu. A cidade, que Tamerlão restituíra aos Aydınoğulları em 1402, voltou assim aos otomanos treze anos depois. Cüneyd retomaria a cidade em 1422, e a questão só seria encerrada por Murad II em 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Execução de Torlak Kemal — Saruhan definitivamente otomana", "8a09dbf1"], "d": ["Torlak Kemal, que conduzia o braço da Anatólia ocidental do movimento do xeique Bedreddin, foi derrotado na região de Manisa e executado. Depois desta data, a região de Saruhan passou definitivamente ao controlo otomano e o beylik que Tamerlão fizera reviver em 1402 desapareceu da história. Foram assim limpos os últimos resquícios políticos do Fetret Devri na Anatólia ocidental.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Conquista de Vlorë, Berat e Kanina", "1e1949b8"], "d": ["Os otomanos submeteram em 1417 Vlorë, na costa do Adriático, com a cidade de Berat, no interior do país, e a Fortaleza de Kanina. Um ano depois, a tentativa de Veneza de recuperar a cidade fracassou e, estabelecida ali uma organização de sanjaco, a autoridade otomana tornou-se duradoura. A tomada de Vlorë, fazendo dos otomanos pela primeira vez donos diretos de um porto no Adriático, deu-lhes um trampolim ultramarino face à Itália.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Recuperação da Anatólia central: Kayseri e Kırşehir", "204eacb3"], "d": ["As cidades da Anatólia central que, durante o Fetret Devri, passaram para as mãos dos Karamanoğulları voltaram à administração otomana durante as campanhas de reorganização do Estado de Çelebi Mehmed. Com a incorporação de Kayseri e Kırşehir, a bacia do Kızılırmak, perdida na batalha de Ancara, foi em grande parte recuperada. Este avanço é a continuação da política de orientação para leste iniciada quatro anos antes com o cerco de Konya.", "c663fc08"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["A morte de Mehmed I e a entronização de Murad II", "98acac77"], "d": ["Mehmed I, que pusera fim ao Interregno e reunira de novo numa só mão o país otomano, morreu em Edirne a 25 de junho de 1421, e o seu filho Murad subiu ao trono em Bursa. Segundo o ajuste feito com Bizâncio antes da sua morte, os filhos mais novos seriam enviados como reféns junto do imperador, e o imperador não libertaria o pretendente ao trono Mustafa Çelebi, que tinha em seu poder; Murad II recusou-se a enviar os irmãos ao imperador.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Liquidação definitiva dos Tekeoğulları: tomada de Antalya", "e65565b2"], "d": ["O Beylik dos Tekeoğulları, refundado depois da batalha de Ancara por obra de Tamerlão, chegou ao fim com o cerco de Antalya pelas forças otomanas sob o comando de Hamza Bey; foi eliminado Osman Çelebi, último homem importante do beylik. Assim, a província de Teke, na costa mediterrânica, foi definitivamente incorporada nos otomanos após uma separação de vinte e um anos. O beylik, como ramo separado dos Hamîdoğulları, reinava em Antalya desde 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Campanha de Turahan Bey na Moreia e destruição da Muralha do Hexamílion", "c6c2706d"], "d": ["Em consequência do apoio de Bizâncio ao pretendente rival ao trono, Mustafa Çelebi, Murad II enviou Turahan Bey contra a Moreia. Turahan Bey, derrubando a muralha do Hexamílion que fechava de lado a lado o istmo de Corinto, entrou na península e causou grande destruição. A paz foi obtida com a condição de que a muralha não fosse reconstruída e de que se pagasse um imposto anual; o despotado da Moreia foi assim deixado militarmente indefeso, e o terreno da conquista final de 1460 foi preparado trinta e sete anos antes.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Os mosteiros do Monte Atos sob a proteção otomana", "562de5ea"], "d": ["Nos anos em que Salónica estava sitiada, a república monástica do Monte Atos, no dedo oriental da Calcídica, recorreu a Murad II pedindo proteção e aceitou a soberania otomana. Os direitos de propriedade e de culto dos monges foram assegurados; os mosteiros foram deixados livres nos seus assuntos internos em troca de imposto. Esta ordem tornou-se o exemplo mais duradouro da relação de proteção que os otomanos estabeleceram com as instituições ortodoxas e durou cinco séculos.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Anexação do Beylik dos Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Por pressão do beylerbei de Amásia, Yörgüç Paşa, o Tâceddinoğlu Hüsâmeddin Hasan Bey entregou, no ano 830 (1427), as chaves do seu país, com centro em Niksar; foi-lhe dado um sanjaco na Rumélia. O beylik, fundado na segunda metade do século XIV e cujas fronteiras se estenderam por vezes até Kelkit, Amásia, Samsun, Ordu e Giresun, chegou assim ao fim. No mesmo ano, os territórios dos Hacıemiroğulları foram também recenseados e ligados ao sanjaco de Canik; o período dos beyliks do mar Negro central ficou encerrado.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["A cedência de Belgrado à Hungria — o Tratado de Tata", "62481183"], "d": ["Com a morte do déspota sérvio Stefan Lazarević, em virtude do Tratado de Tata, feito entre o rei húngaro Sigismundo e o seu herdeiro Georg Branković, a fortaleza de Belgrado foi cedida à Hungria. A fortaleza, situada no ponto de confluência do Danúbio e do Sava, estivera até então nas mãos do despotado sérvio e era, para os otomanos, o ferrolho da porta que se abre para a Europa Central. Esta cedência fez de Belgrado, durante cem anos, o mais duro obstáculo ao avanço otomano: os cercos de 1440 e 1456 falhariam, e a fortaleza só cairia em 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin passou do guarda kara koyunlu ao Ak Koyunlu Karayülük Osman Bey", "d82bc97f"], "d": ["Mardin, tomada por Kara Yûsuf em 1409, foi governada pelos Kara Koyunlu por governadores; o emir Nâsır, deixado como guarda, entregou a cidade em 835 (1432) ao Ak Koyunlu Karayülük Osman Bey. A administração ak koyunlu durou até ao início do século XVI.", "407382cb"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Incidente de Buçuktepe — primeira revolta dos janízaros e regresso de Murad II ao trono", "6388dda1"], "d": ["O Incidente de Buçuktepe, a primeira revolta de janízaros conhecida na história, que irrompeu em Edirne, começou com a exigência de um aumento de meio akçe nos seus soldos e resultou na deposição do jovem Mehmed II. Murad II partiu apressadamente de Manisa em 8 de Safer de 850 e iniciou o seu segundo reinado. O acontecimento foi o primeiro sinal de que o corpo dos kapıkulus se tornara uma força com voz sobre o trono e moldou a prudência vitalícia de Maomé II, o Conquistador, face aos janízaros.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Incorporação da costa do Épiro: Arta e Preveza", "796f7ecf"], "d": ["Dezanove anos depois da rendição de Ioannina em 1430, também Arta e Preveza, na parte costeira do despotado do Épiro, passaram à administração otomana. Assim, o golfo de Ambrácia, que se abre para o mar Jónico, foi posto sob controlo e a ligação marítima de Ioannina ficou completa. Preveza é o ponto-chave da baía que, noventa anos depois, daria o nome à vitória de Barbarossa que passaria à história.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Morte de Murad II e segunda subida ao trono de Mehmed II", "8f8256ad"], "d": ["Murad II, que adoeceu depois do casamento do seu filho, morreu em Edirne em 1 de Muharrem de 855 (3 de fevereiro de 1451). Mehmed II, de dezanove anos, subiu pela segunda vez ao trono otomano em 16 de Muharrem de 855 (18 de fevereiro de 1451) — desta vez de forma duradoura. O regresso do jovem soberano, deposto cinco anos antes em Buçuktepe, será coroado dois anos depois com a conquista de Constantinopla e é o início do reinado que transformaria o Beylik Otomano num império mundial.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Primeiro cerco de Kefe pelas forças conjuntas otomano-crimeanas", "e346d163"], "d": ["O cã da Crimeia Hacı Giray, que em junho de 1454 se entendera com Maomé II, o Conquistador, sitiou Kefe por terra com 7000 cavaleiros; uma armada otomana de cinquenta a sessenta galés posicionou-se também ao largo. A Kefe genovesa fez levantar o cerco pagando tributo e a conquista definitiva ficou para vinte e um anos depois, 1475. Esta primeira operação conjunta foi o primeiro exemplo da cooperação militar otomano-crimeana que se repetiria depois na conquista definitiva de Kefe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Tomada das ilhas do norte do Egeu: Bozcaada, İmroz e Thasos", "76575895"], "d": ["Logo depois da conquista de Constantinopla, Maomé II, o Conquistador, voltou-se para as ilhas da boca do Egeu do estreito dos Dardanelos para assegurar a rota marítima da nova capital; Bozcaada e İmroz foram tomadas a Bizâncio e Thasos à família Gattilusio, de origem genovesa. Estas ilhas, que fechavam as duas margens do estreito, foram daí em diante o primeiro elo da linha de abastecimento e defesa de Istambul. O domínio oscilou durante algum tempo com as intervenções das armadas do papado e de Veneza, e só ficou definitivo em 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Conquista do Kosovo: tomada de Priština e Novi Pazar", "d7ed2345"], "d": ["O exército otomano, que marchou contra o Despotado Sérvio, tomou Priština, na planície do Kosovo, e Novi Pazar, centro da região de Raška; na mesma operação foi tomada também Novo Brdo, célebre pelas suas minas de prata. Assim, a metade meridional da Sérvia foi ligada à administração otomana direta e o despotado de Semendire foi separado dos seus territórios centrais. Esta conquista foi o passo decisivo do caminho que, quatro anos depois, conduziria à anexação total da Sérvia.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć passou à administração otomana — um dos centros do sanjaco de Dukakin", "19511588"], "d": ["Em 1455, logo depois da campanha da Sérvia de Maomé II, o Conquistador, Peć, centro do patriarcado sérvio, passou à administração otomana; nas fontes otomanas não há registo desta passagem. A vila tornou-se com o tempo uma pequena vila muçulmana e uma das residências do sanjak-bey no sanjaco de Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Conquista de Enez e de Samotrácia — conclusão da costa da Trácia ocidental", "106e723b"], "d": ["Enez, na foz do Maritsa, foi tomada à família Gattilusio, de origem genovesa, que a detinha havia oitenta anos; a ilha de Samotrácia, que dela dependia, foi também tomada na mesma operação. Com a queda de Enez, a faixa costeira da Trácia ocidental tornou-se território otomano ininterrupto, de Salónica a Galípoli. Em mãos da família Gattilusio restou apenas Lesbos, que seria tomada seis anos depois.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Fracasso do cerco de Belgrado", "3d53a604"], "d": ["Maomé II, o Conquistador, depois da conquista de Constantinopla, sitiou Belgrado, considerada o fecho da Europa Central; mas o reforço trazido por Jan Hunyadi pelo Danúbio e os voluntários reunidos pelo pregador da cruzada Capistrano impediram a queda da fortaleza. O sultão, apesar do heroísmo pessoal que demonstrou diante do cerco, foi forçado a retirar-se ferido. Este fracasso fechou a fronteira húngara ao avanço otomano durante sessenta e cinco anos; Belgrado só poderia ser tomada em 1521 pelo Legislador.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Conquista da Moreia setentrional: Balyabadra (Patras)", "c08a8509"], "d": ["As forças de Maomé II, o Conquistador, que se voltaram para o despotado da Moreia nos mesmos anos da anexação da Sérvia, tomaram Balyabadra, no noroeste da península. Este porto, que guarda a entrada do golfo de Corinto, é a chave da entrada por terra na Moreia; a sua tomada preparou o terreno da conquista final, dois anos depois. A cidade era o último grande embarcadouro por onde os déspotas bizantinos estabeleciam ligação com o mundo latino.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Tomada da costa ocidental do mar Negro: Amasra", "f43608fc"], "d": ["Amasra, colónia fortificada de Génova no mar Negro ocidental, rendeu-se sem resistência à pressão conjunta da armada e das forças terrestres de Maomé II, o Conquistador. Este porto, na costa de Bartın-Zonguldak, estava como um bolsão latino entre os Candaroğulları e o território otomano; com a sua tomada a costa ficou unificada. A queda de Amasra é o primeiro passo da grande campanha do mar Negro que, dois anos depois (1461), se dirigiria a Sinope e Trebizonda.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Conquista da ilha de Lesbos", "fe17aeba"], "d": ["O exército otomano sob o comando de Maomé II, o Conquistador, tomou e anexou Lesbos, em Zilhicce de 866, depois de um cerco breve mas violento, à família Gattilusio, de origem genovesa. A queda da maior ilha do norte do Egeu liquidou também a última base importante dos genoveses na região. A ilha, graças à proximidade da costa da Anatólia, serviria daí em diante de posto avançado da armada otomana e passaria também à história marítima como lugar onde se formaram os irmãos Barbarossa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Início da Guerra Otomano-Veneziana de dezasseis anos", "563ddb68"], "d": ["Os venezianos, para deter o avanço otomano na Moreia e no Egeu, aliaram-se com os governantes de Karaman e dos Ak Koyunlu e iniciaram a guerra em 1463. Esta estratégia de cerco, formada por Uzun Hasan no leste, Veneza no oeste e Karaman no meio, forçou Maomé II, o Conquistador, a combater em várias frentes ao mesmo tempo. A luta, que durou dezasseis anos, abrangeu todas as grandes operações da época, de Otlukbeli às campanhas da Albânia, e só terminaria com o Tratado de Istambul de 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Conquista da maior parte da Herzegovina: Trebinje e Mostar", "f54c0100"], "d": ["Os territórios do duque da Herzegovina Stjepan Vukčić-Kosača, que estabelecera uma administração separada da Bósnia, passaram em grande parte à administração otomana três anos depois da destruição do Reino da Bósnia: no sul, Trebinje foi tomada em 1466 \"juntamente com quase toda a região da Herzegovina\". Mostar, edificada em torno de duas pequenas fortalezas da ponte sobre o Neretva, deve ter sido tomada pouco antes da conquista de Blagaj, centro da Herzegovina, em 1466-1468; está registada com o nome de \"Köprülü Hisar\" no recenseamento sumário da Bósnia de 1468-1469. A conquista da Herzegovina, com as restantes fortalezas do ducado, foi concluída em 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["II campanha da Albânia — marcha pessoal do Conquistador contra Skanderbeg", "9cdd2bfa"], "d": ["Para quebrar a resistência de Skanderbeg, que durava mais de um quarto de século, Maomé II, o Conquistador, organizou em 1466-1467 grandes campanhas que comandou pessoalmente. O exército otomano sitiou Akçahisar e construiu a Fortaleza de İlbasan (Elbasan) para pôr a região sob controlo. A campanha, embora tenha quebrado a espinha da resistência albanesa, não conseguiu fazer cair a fortaleza; a sujeição completa da região demoraria uma década depois da morte de Skanderbeg.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Colapso do Estado Kara Koyunlu: morte de Cihan Şah", "30bc6358"], "d": ["Cihan Şah, soberano kara koyunlu, que regressava de uma campanha contra Uzun Hasan por causa da chegada do inverno, foi atacado e morto quando fugia entre Bingöl e Kiğı. Depois deste golpe, o Estado não se recompôs; o último soberano, Hasan Ali, foi capturado e morto em 1469 por Uğurlu Mehmed, filho de Uzun Hasan. O domínio kara koyunlu, que durava havia quase um século na Anatólia oriental, no Azerbaijão e no Iraque, passou assim aos Ak Koyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Morte de Skanderbeg — extinção da resistência albanesa", "9158c35f"], "d": ["Skanderbeg, que, criado no palácio otomano, se revoltara em 1444 depois do desastre de Zlatica e resistira durante mais de um quarto de século na Albânia, morreu em Lezhë, onde se refugiara. Esta resistência, que entreteve repetidamente os exércitos otomanos nos tempos de Murad II e do Conquistador, perdeu com a sua morte a direção central. Com o colapso da frente albanesa, alimentada pelo papado e por Veneza, os otomanos tomaram em dez anos Akçahisar e Shkodër e incorporaram definitivamente a região nos seus territórios.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Foi estabelecida a administração otomana em Kayseri: Gedik Ahmed Paxá pôs fim aos Karamanoğulları", "33cf35fc"], "d": ["Com o fim dos Karamanoğulları por Gedik Ahmed Paxá em 1474, Kayseri entrou na administração otomana; a cidade mudara de mãos, ao longo do século XV, entre os Dulkadıroğulları, os Ramazanoğulları e os Karamanoğulları. Com o governo otomano, Kayseri tornou-se centro de sanjaco do beylerbeylik de Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos foi abandonada: terminou a propriedade genovesa (Maona)", "5bdc380c"], "d": ["Segundo a TDV, a ilha foi abandonada depois de 1475; em 1479 o sultão Maomé II, o Conquistador, conquistou a ilha e mandou construir uma fortaleza.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Desastre de Račova (Vaslui) na Moldávia", "a1a74bf7"], "d": ["O voivoda da Moldávia, Stefan cel Mare, atraindo as forças otomanas sob o comando do beylerbei da Rumélia Hadım Süleyman Paşa para um terreno pantanoso, infligiu-lhes uma pesada derrota. Este desastre, uma das mais pesadas derrotas terrestres do tempo do Conquistador, causou grande eco na Europa e deu a Stefan fama no mundo cruzado. O sultão partiria no ano seguinte pessoalmente em campanha de represália.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Vitória de Akdere (Valea Albă) — campanha da Moldávia", "45a66791"], "d": ["Maomé II, o Conquistador, que partiu pessoalmente em campanha para vingar o desastre de Račova do ano anterior, infligiu ao exército otomano e às tropas moldavas uma grande derrota no lugar de Akdere e entrou em Suceava, centro do beylik. Contudo, as fortalezas não puderam ser tomadas; por dificuldades de abastecimento, pela peste surgida entre os janízaros e pelos preparativos húngaros, o exército foi forçado a retirar-se. A fidelidade definitiva da Moldávia só poderia ser obtida nos anos seguintes, com a tomada de Kili e de Akkirman em 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Conquista de Akçahisar (Krujë) e conclusão da Albânia", "559a79b4"], "d": ["Dez anos depois da morte de Skanderbeg, com a captura em 1478 de Akçahisar, Drivasto, Lezhë e Jabyak, a conquista da Albânia ficou em grande parte concluída. A queda da Fortaleza de Krujë, que resistira durante anos aos exércitos otomanos e era o símbolo da resistência de Skanderbeg, significava o fim da aliança veneziano-albanesa na região. Shkodër, que restava, seria deixada aos otomanos pelo Tratado de Istambul, a assinar no ano seguinte.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Incorporação da península de Taman", "4ef917b8"], "d": ["Depois da tomada de Kefe e Kerç em 1475, a armada que Maomé II, o Conquistador, enviou às costas do Cáucaso tomou, juntamente com Anapa e Kopa, a Matrega genovesa (Tamatarhan) na península de Taman. Assim, as duas margens do estreito ficaram sob controlo e a entrada no mar de Azov tornou-se totalmente controlável. Taman foi ligada ao sanjaco de Kefe como porta que se abre para o Cáucaso setentrional.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["A entrada de Samos na administração otomana (o Conquistador)", "c877bc14"], "d": ["O sultão Maomé II, o Conquistador, conquistou Samos, mandou construir uma fortaleza e reorganizou o recenseamento; a fortaleza foi mandada demolir por Bajazeto II em 1483, por razões políticas.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Fracasso do cerco de Rodes", "35a85c28"], "d": ["A armada de 160 unidades sob o comando de Mesih Paşa, por ordem de Maomé II, o Conquistador, sitiou Rodes na primavera de 885 (1480) e a ilha ficou três meses bloqueada. Os cavaleiros de São João, sob a direção do grão-mestre Pierre d'Aubusson, resistiram com violência apesar das pesadas perdas; com a repulsa do último grande assalto, feito em 20 de Cemâziyelevvel de 885, a armada retirou-se em 3 de agosto. Depois deste fracasso, as muralhas da cidade foram renovadas de alto a baixo, fazendo dela a mais forte fortificação da Europa, e a ilha só pôde ser tomada em 1522 pelo Legislador.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikarya (Ícaro) entrou na administração dos Cavaleiros de São João de Rodes", "5cbc2669"], "d": ["Nikarya, entre Samos e Quios, esteve de 1481 a 1521 sob a administração dos Cavaleiros de São João de Rodes.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Batalha de Yenişehir — derrota do sultão Cem", "c35abee2"], "d": ["Os dois irmãos que, depois da morte do Conquistador, se moveram pelo trono, encontraram-se frente a frente na planície de Yenişehir e o sultão Cem sofreu uma derrota decisiva. O príncipe, que reinara dezoito dias em Bursa e fizera ler a hutba em seu nome, foi obrigado, depois da derrota, a refugiar-se primeiro em Konya e daí em território mameluco. Yenişehir deu início à mais longa crise dinástica da história otomana: a questão de Cem paralisaria durante catorze anos a política externa otomana face à Europa.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Anexação da Herzegovina", "bf247891"], "d": ["Depois da conquista da Bósnia em 1463, os territórios do Ducado da Herzegovina, que se mantinha de pé, passaram por fases à administração otomana: Trebinje e Mostar tinham sido tomadas em 1466, o sanjaco da Herzegovina fora organizado em 1470 e os últimos territórios do ducado na costa do Adriático, com Herceg Novi, foram conquistados no início de 1482 e incorporados no sanjaco. Assim, a região montanhosa por trás do Adriático tornou-se inteiramente otomana e a Bósnia e a Herzegovina formaram uma só geografia administrativa. O filho do último duque, que entrou no palácio otomano, é Hersekzâde Ahmed Paşa, que viria a ser elevado até ao grão-vizirato.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["A cedência de Zante a Veneza em troca de tributo anual", "268a691a"], "d": ["Zante, uma das ilhas Jónicas tomadas à família Tocco no fim da época do Conquistador, foi cedida a Veneza pelo novo sultão, que, ocupado com a questão do sultão Cem, procurava sossego no Ocidente. A ilha foi entregue a uma administração veneziana que reconhecia a soberania otomana e pagava um tributo anual de quinhentos ducados. Assim, no mar Jónico, a administração direta otomana ficou apenas em Ayamavra.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Refúgio do sultão Cem em Rodes", "2228d6da"], "d": ["O sultão Cem, cuja tentativa de cercar Konya fora também infrutífera, fugiu da Anatólia com cerca de trinta homens, chegou a Rodes e foi recebido com cerimónia pelos cavaleiros de São João. Contudo, a hospedagem converteu-se rapidamente em cativeiro; o príncipe, cedido primeiro à França e depois ao papado, tornou-se um trunfo nas mãos da política europeia. Bajazeto II foi forçado a fazer um pagamento anual em troca da retenção do irmão, e as ações militares otomanas voltadas para o Ocidente ficaram suspensas até à morte de Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Início da Guerra Otomano-Mameluca (frente de Çukurova)", "3fe3f0c7"], "d": ["A luta de influência sobre os Dulkadıroğulları e a inimizade deixada pelo refúgio do sultão Cem em território mameluco iniciaram em 1485 uma guerra de seis anos entre as duas grandes potências sunitas. Nos combates em Çukurova, em torno de Adana e Tarso, as partes não conseguiram obter superioridade uma sobre a outra; os exércitos otomanos sofreram alguns golpes pesados. Esta guerra é a primeira fase da rutura nas relações otomano-mamelucas e a abertura do processo que seria concluído trinta anos depois com as campanhas de Yavuz em Mercidâbık e Ridâniye.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Paz otomano-mameluca — mediação de Tunes", "60dd6719"], "d": ["Na guerra otomano-mameluca iniciada em 1485, as partes não obtiveram vitória decisiva; chegou-se a um acordo em 1491 por mediação do soberano de Tunes, Osman Hafsî. O tratado repôs em grande parte as fronteiras ao estado anterior à guerra e o ajuste de contas entre os dois Estados islâmicos foi adiado por uma geração. A luta desgastante de seis anos é uma das principais razões da política externa prudente de Bajazeto II e do facto de ter dado peso aos ordenamentos internos em vez de se voltar para oriente.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Acolhimento nos otomanos dos judeus sefarditas expulsos de Espanha", "5c2b5c24"], "d": ["Depois da queda de Granada, parte dos judeus que fugiam da perseguição da Inquisição em Espanha refugiou-se em território otomano e foi instalada em várias cidades. Sob a administração otomana, estas comunidades sefarditas obtiveram uma liberdade que até então não tinham conhecido: a de se instalar onde quisessem, de viver a sua fé, de abrir instituições de ensino e de construir novas sinagogas. Esta migração, que, com os conhecimentos de tipografia, medicina e finanças que trouxe consigo, transformou a vida económica de Salónica e de Istambul, tornou-se o exemplo mais comentado na Europa da ordem de tolerância otomana.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Morte do sultão Cem — fim de catorze anos de cativeiro", "f6588b70"], "d": ["O sultão Cem, cedido pelo papado ao rei de França Carlos VIII, morreu no lugar chamado Castel Capuana depois de ter partido de Roma em 27 de janeiro de 1495; as fontes registam que pode ter sido envenenado por círculos papais. A morte do príncipe, que durante catorze anos foi mantido nas mãos dos Estados europeus como carta de ameaça contra os otomanos, libertou finalmente a mão de Bajazeto II. De facto, o sultão declararia depois guerra a Veneza e levaria a sua armada à primeira grande vitória.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Vitória naval de Sapienza (Zonchio) — primeiro grande êxito da armada no Mediterrâneo", "9754aaef"], "d": ["Bajazeto II, que encontrou a mão livre com o fim da questão de Cem, declarou guerra a Veneza em 1499; a armada otomana derrotou a frota veneziana ao largo de Sapienza (Zonchio) e ganhou a primeira grande vitória naval no Mediterrâneo. Com esta vitória, a armada declarou que já podia opor-se a Veneza no mar.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["A perda de Cefalónia e Ítaca", "60f0f687"], "d": ["Veneza, abalada pela tomada de Modon e Koron, uniu-se à Espanha e passou ao contra-ataque, cercando Cefalónia, que estava nas mãos dos otomanos desde 1479. Depois de uma resistência de quarenta e sete dias, a fortaleza caiu, a ilha passou a Veneza juntamente com Ítaca e durante trezentos anos não voltou à administração otomana. Esta perda criou um equilíbrio em que o que se ganhara na Moreia era devolvido no Jónico.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Destruição do Canato da Horda Dourada e ascensão da Crimeia", "0d1dc515"], "d": ["O último soberano, Şeyh Ahmed Han (1481-1502), não pôde salvar o seu país da crise em que caíra e o Canato da Horda Dourada desapareceu da história em 1502 com o golpe do cã da Crimeia Mengli Giray. Em consequência das lutas pelo trono e da fragmentação, surgiram nos antigos territórios da Horda Dourada os canatos da Crimeia, de Cazã, dos Nogai, de Astracã e da Sibéria. Esta vitória da Crimeia, sob a proteção otomana, tornou indiscutível a influência otomana a norte do mar Negro, ao passo que o vazio nascido na região seria preenchido no século seguinte por Moscovo.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Fim da Guerra Otomano-Veneziana e paz", "125b1526"], "d": ["A guerra iniciada em 1499, que abalou Veneza com Sapienza, Lepanto e a perda de Modon e de Koron, terminou em 1502 com a paz. Veneza, tendo perdido as suas bases mais importantes na Moreia, foi obrigada a reconhecer a supremacia otomana em troca da preservação dos seus privilégios comerciais no Mediterrâneo oriental. O reinado de Bajazeto II, tido por prudente, elevara com esta guerra, pela primeira vez, os otomanos à condição de uma séria potência naval no Mediterrâneo.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Revolta de Şahkulu — insurreição kizilbash da região de Teke a Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, que em 1510 manifestara abertamente a sua revolta, por efeito da propaganda safávida na Anatólia, tinha assaltado em março de 1511 o bazar de Antalya e, em abril, derrotado forças otomanas em Kütahya e arredores. No último combate que travou perto de Sivas com o grão-vizir Hadım Ali Paşa, ambas as partes sofreram pesadas perdas; morreram tanto o grão-vizir como o líder da revolta. Esta insurreição, que abalou a autoridade do Estado na Anatólia, pôs à vista o vazio de poder dos últimos anos de Bajazeto II e foi a razão mais forte da marcha do príncipe Selim para o trono.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdicação de Bajazeto II e subida ao trono de Yavuz Sultão Selim", "c4cfab69"], "d": ["Sob a pressão do príncipe Selim, que na luta pelo trono com os seus irmãos tinha o apoio dos janízaros, Bajazeto II abdicou em 24 de abril de 1512 e Selim I subiu ao trono no mesmo dia como nono soberano otomano. O idoso sultão, quando se dirigia para Dimetoka, onde nascera, morreu no caminho, na aldeia de Abalar, perto de Çorlu, em 25 de Rebîülevvel de 918 (10 de junho de 1512). Ao reinado prudente e voltado para o interior de trinta e um anos sucedeu a era de Yavuz, que em oito anos duplicaria as fronteiras do império.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["A conquista da fortaleza de Sinj", "83271ea5"], "d": ["As forças otomanas de incursão da fronteira da Bósnia tomaram ao Reino da Hungria a fortaleza de Sinj, que se estende para o interior da Dalmácia. Foi um elo precoce da linha de fronteira da Dalmácia, que se alargaria nove anos depois com a conquista de Knin e dos arredores por Gazi Hüsrev Bey; a fortaleza seria perdida para Veneza em 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Batalha de Yenişehir e eliminação do príncipe Ahmed", "e2ed15dd"], "d": ["Yavuz Sultão Selim derrotou na planície de Yenişehir, perto de Bursa, o príncipe Ahmed, seu irmão mais velho e mais forte rival ao trono, e eliminou-o fazendo-o prisioneiro. Assim terminou a luta fraticida que durava desde 1511 e acabou a divisão interna na Anatólia. Selim, tendo assegurado a retaguarda, ganhou a liberdade de se orientar para a questão safávida.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Entrada de Yavuz Sultão Selim em Tabriz", "dad2e227"], "d": ["Depois da vitória de Çaldıran, o exército otomano entrou em Tabriz, capital safávida, e a hutba foi lida na cidade em nome do sultão. Selim permaneceu aqui uma semana e mandou transferir para Istambul parte dos artistas e dos ulemás de Tabriz; esta transferência influenciaria profundamente a arte do palácio otomano. Embora a cidade tenha sido abandonada com a aproximação do inverno e o descontentamento dos janízaros, a supremacia safávida no Oriente ficara quebrada. No mapa, os lugares que passam nesta data para os otomanos não são contíguos, e isso é correto: Tabriz é uma ocupação militar de nove dias; a planície de Erzincan rendeu-se sem combate durante a campanha, ao passo que a fortaleza de Kemah, no meio dela, resistiu entre os safávidas até 19 de maio de 1515; Siirt foi retomada aos safávidas pelo melik de Hasankeyf, Halil Bey, libertado da prisão do xá Ismail em Tabriz, obedecendo aos otomanos — Diyarbakır, em redor, ficou safávida até 1515 e Hasankeyf até 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş e Bingöl (Çapakçur) passaram dos safávidas para a administração otomana", "b0a53b5a"], "d": ["Com a tomada da Anatólia Oriental aos safávidas depois de Çaldıran, Muş entrou em 921/1515 na administração otomana; a vizinha Çapakçur (Bingöl) foi incorporada pelos otomanos no mesmo processo.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Conquista aos safávidas da Fortaleza de Kemah", "73fd8671"], "d": ["Yavuz Sultão Selim, que passou o inverno em Amásia no regresso de Çaldıran, encarregou Bıyıklı Mehmed Paşa da conquista da fortificada Fortaleza de Kemah, que guardava o ponto de passagem do Eufrates. No termo do cerco, em que o sultão participou pessoalmente, a fortaleza foi tomada à mão safávida e abriu-se a porta da Anatólia oriental. Esta conquista é o primeiro passo concreto que transformou a vitória de Çaldıran em ganho territorial duradouro.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Vitória de Turnadağ — o Beylik de Dulkadir tornou-se vassalo dos otomanos", "fd879145"], "d": ["As forças otomanas derrotaram no lugar de Ördekli, entre Göksun e Andırın, o bey de Dulkadir Alâüddevle Bozkurt, que assumira uma atitude ambígua durante a campanha de Çaldıran; Alâüddevle foi morto nesta batalha. O beylik não foi anexado nesta data: depois de Alâüddevle, foi posto à frente do Beylik dos Dulkadıroğulları, por Yavuz Sultão Selim, Şehsuvaroğlu Ali Bey, e o país com centro em Maraş-Elbistan continuou como beylik vassalo dos otomanos. A zona-tampão na fronteira mameluca entrou assim sob controlo otomano e abriu-se o caminho da campanha do Egito, dois anos depois; a anexação far-se-á depois da morte de Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Conquista de Âmid (Diyarbekir) e criação do beylerbeylik de Diyarbekir", "a6867d5b"], "d": ["Depois de İdrîs-i Bitlisî ter ganho para os otomanos os beys curdos sunitas da região, as forças safávidas não resistiram a um longo cerco e as chaves de Âmid foram entregues a Bıyıklı Mehmed Paşa. A cidade foi feita centro do recém-criado beylerbeylik de Diyarbekir. Assim, o núcleo administrativo da Alta Mesopotâmia passou às mãos otomanas.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Conquista de Harput — abertura da rota de Diyarbekir", "564eb269"], "d": ["O beylerbei de Karaman, Hüsrev Paşa, que partiu para salvar do cerco safávida Diyarbekir, tomada depois de Çaldıran, tomou, no termo de um cerco de três dias, a Fortaleza de Harput, cujos arredores tinham sido antes conquistados por Çerkez Hüseyin Bey. O caminho que se estende para Diyarbekir, a leste do Eufrates, ficou assim assegurado.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Batalha de Koçhisar (Kızıltepe) — derrota de Kara Han", "9ea9e843"], "d": ["O exército otomano sob o comando de Bıyıklı Mehmed Paşa derrotou o governador safávida Kara Han, perto de Koçhisar, no lugar de Koruk, na planície de Dede Garkın, numa batalha campal que durou todo o dia; a cabeça decepada de Kara Han foi enviada ao acampamento do sultão. Em seguida, embora as forças otomanas tenham entrado na cidade de Mardin, permaneceram poucos dias e partiram; a Fortaleza de Mardin, mantida pelos guardas safávidas, só pôde ser recebida um ano depois. Esta vitória, assegurando a fronteira sul de Yavuz, tornou possível a sua orientação para a campanha do Egito. Outros lugares incorporados na mesma data: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Partida de Yavuz Sultão Selim de Istambul para a campanha do Egito", "ac258b4b"], "d": ["Yavuz Sultão Selim partiu de Istambul, aparentemente com os preparativos de uma nova campanha oriental contra os safávidas, e orientou-se para sul por Akşehir. O facto de o sultão mameluco Kansu Gavri estabelecer contacto com o xá Ismail e ameaçar o flanco oriental otomano levaria em breve a uma mudança do objetivo. A campanha é o início da grande operação que duraria dois anos e transformaria os otomanos num império do Médio Oriente.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Tomada de Zabid: primeira entrada de marinheiros otomanos no mar Vermelho", "38740e0c"], "d": ["Os marinheiros de origem otomana Hüseyin Bey e Selman Reis, enviados ao mar Vermelho a pedido do sultão mameluco Kansu Gavri perante a pressão portuguesa no oceano Índico, tomaram Zabid com as suas armadas. Esta operação, ainda conduzida ao serviço mameluco, é a primeira presença efetiva da marinha otomana na linha mar Vermelho-Índia. Um ano depois, quando o Egito passou aos otomanos, a mesma frota ficaria diretamente ligada a Istambul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Declaração oficial do objetivo da campanha como os mamelucos e Alepo", "689e310d"], "d": ["Yavuz Sultão Selim, quando Kansu Gavri, entendendo-se com os safávidas, conduziu o seu exército a Alepo, declarou abertamente como objetivo da campanha o sultão mameluco e Alepo. Assim, a rivalidade encoberta que durava havia anos entre os dois Estados sunitas transformou-se em guerra aberta. Esta declaração iniciou a contagem decrescente de quatro semanas que conduz a Mercidâbık.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Fracasso do cerco de Áden: primeira tentativa no mar Vermelho contra Portugal", "8ffd46f2"], "d": ["Selman Reis e Hüseyin Bey conduziram um cerco de oito dias para tomar Áden, porta do mar Vermelho para o oceano Índico, mas foram obrigados a retirar-se perante as fortes fortificações da cidade. O facto de Áden não ter sido tomada atrasará durante muitos anos a estratégia meridional a conduzir contra Portugal. Esta tentativa é a primeira prova da política oceânica otomana.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Ligação do Beylik dos Ramazanoğulları aos otomanos", "cfaa3754"], "d": ["Nas investiduras feitas após a vitória de Mercidâbık, o Beylik dos Ramazanoğulları, com centro em Adana, foi dado a Mahmud Bey e posto sob o domínio otomano. O beylik, que saía da vassalagem mameluca, em vez de ser abolido, foi deixado à família com o estatuto de 'ocaklık'; os Ramazanoğulları continuaram a administrar Çukurova na qualidade de sanjak-beys otomanos. Esta ordem privilegiada manteve-se até 1608, ano em que Pîr Mansûr deixou o beylik. Outros lugares incorporados na mesma data: Malatya, Tarsus, Musul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Alepo, Raqqa e Deir ez-Zor passam ao domínio otomano", "2088eb6a"], "d": ["Quatro dias depois de Mercidâbık, Yavuz Sultão Selim entrou em Alepo sem encontrar resistência e a hutba foi lida em seu nome nas mesquitas da cidade. A queda tão rápida de Alepo, tida por capital comercial e administrativa da Síria, mostra que a autoridade mameluca na região ruíra. A tomada da cidade abriu de súbito o caminho para Damasco e daí para o Egito. Outros lugares incorporados na mesma data: Antakya, Rakka, Deyrizor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Encontro em Gökmeydan, Alepo, com o califa abássida Mutawakkil III", "22979f42"], "d": ["O califa abássida do Cairo Mutawakkil III, que fora feito prisioneiro em Mercidâbık com o exército mameluco, foi levado à presença do sultão em Gökmeydan, em Alepo, e Yavuz Sultão Selim mostrou-lhe grande respeito. O califado do Cairo, cargo simbólico à sombra dos sultões mamelucos desde 1261, passou com este encontro de facto à proteção otomana. O califa seria depois levado a Istambul com o sultão.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Trípoli da Síria e Hama passam à administração otomana", "a1e19a79"], "d": ["Depois de Alepo e de Hama, também Trípoli da Síria, na costa síria, passou sem resistência à administração otomana. A cidade, um dos portos mais movimentados do Mediterrâneo oriental, era a porta de Damasco para o mar e o centro do comércio da seda e do açúcar. Com a sua tomada, a faixa costeira do Bilâdüşşam mudou inteiramente de mãos.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damasco (Dımaşk) passa ao domínio otomano", "2b844d91"], "d": ["Yavuz Sultão Selim, a quem se abrira o caminho com a rendição de Hama e de Homs depois de Alepo, chegou em 27 de setembro diante de Damasco; não entrou logo na cidade, instalou a sua tenda no exterior, no lugar de Mastaba, e entrou com grande cerimónia no décimo segundo dia da sua chegada. Permaneceu longamente em Damasco, estabeleceu a ordem administrativa da Síria e mandou construir o túmulo de Muhyiddin Ibn Arabi. Assim, todo o Bilâdüşşam saiu da administração mameluca. Outros lugares incorporados na mesma data: Beyrut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tomanbay proclamado sultão mameluco no Cairo", "6020d90d"], "d": ["Depois de Kansu Gavri, morto em Mercidâbık, os emires mamelucos puseram no trono Tomanbay, que seria o último sultão do Estado. O novo sultão, de origem circassiana, herdou um Estado que perdera a Síria, com o tesouro esgotado e sem armas de fogo. Apesar disso, estabelecendo uma linha de defesa diante do Cairo, organizará uma última resistência contra o avanço otomano.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Batalha de Gaza (Khan Yunis): derrota de Canbirdi Gazâlî", "9f1eb8cb"], "d": ["Yavuz Sultão Selim enviou a Gaza o grão-vizir Hadım Sinan Paşa com uma força de vanguarda de quatro mil homens. Canbirdi Gazâlî, nomeado por Tomanbay naib de Damasco, tentou deter a vanguarda otomana na linha Gaza-Khan Yunis, mas sofreu uma pesada derrota e fugiu para o Egito. Com a dispersão da última força-tampão mameluca na Palestina, o caminho do deserto do Sinai ficou totalmente aberto.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["A leste do Jordão: Amã passa à administração otomana", "9db62667"], "d": ["Quando as forças otomanas, que se preparavam para a campanha do Egito após a batalha de Gaza, desciam para sul, também Amã, a leste do Jordão, passou à administração otomana. As cidades costeiras e interiores da Palestina (Yafa, Nablus, Sayda, Akkâ, Kudüs) já tinham mudado de mãos no outono de 1516, depois de Mercidâbık. Estas cidades foram administradas durante quatro séculos como sanjacos da província de Damasco.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Chegada de Yavuz Sultão Selim a Jerusalém", "66d7bfad"], "d": ["A Jerusalém, que passara sem resistência à administração otomana depois de Mercidâbık, veio, depois da batalha de Gaza, Yavuz Sultão Selim com os dignitários do Estado e o exército. O sultão visitou a Cúpula da Rocha e a Mesquita de Al-Aqsa e confirmou o estatuto sagrado da cidade. Jerusalém permanecerá, a partir desta data e até dezembro de 1917, quatro séculos inteiros sob administração otomana.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Entrada de Yavuz Sultão Selim em Gaza e marcha para o deserto do Sinai", "2106bfc7"], "d": ["Depois da derrota de Canbirdi Gazâlî em Khan Yunis (21 de dezembro de 1516), Gaza estava nas mãos da força de vanguarda. O sultão entrou em Gaza em 2 de janeiro de 1517, encontrou-se aqui com Sinan Paşa, à frente da vanguarda, e o exército fez os últimos preparativos para a passagem ao Egito. No deserto sem água de Katya (Sinai), que se estende de Gaza a Salihiyya, caminhar-se-iam oito etapas e a água seria transportada em camelos. Esta passagem é a fase mais arriscada e logisticamente mais difícil da campanha.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Tomada de Suez — porta que se abre para o mar Vermelho", "05f3324e"], "d": ["Com a entrada das unidades otomanas no Cairo, depois da vitória de Ridâniye, também Suez, na extremidade norte do mar Vermelho, passou à administração otomana. Este estaleiro-porto, de onde os mamelucos enviavam armadas ao oceano Índico, tornou-se a base da política meridional a conduzir contra Portugal. Suez é a embocadura norte da linha em que, três séculos depois, seria aberto o canal.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Primeira entrada das unidades otomanas no Cairo", "0a3f4f4d"], "d": ["No dia seguinte à vitória de Ridâniye foi permitida a entrada dos exércitos otomanos no Cairo e em 24 de janeiro as unidades instalaram-se na cidade. Contudo, esta entrada não significava o controlo total da cidade; Tomanbay retirara-se para o Alto Egito e a resistência mameluca não estava ainda quebrada. A conquista do Cairo não se completará num único dia, mas num processo sangrento que se estenderá por semanas.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Ataque de Tomanbay ao Cairo e três dias de combates de rua", "b83b6ce6"], "d": ["Tomanbay, que se retirara para o Alto Egito, com cerca de sete mil homens que tinha consigo, entrou de súbito no Cairo na noite de 27-28 de janeiro e iniciou a resistência dentro da cidade, deixando as unidades otomanas em situação extremamente difícil. Nos violentos combates de rua que duraram três dias, os mamelucos mantiveram temporariamente em seu poder a maior parte da cidade. A resistência só pôde ser quebrada com a entrada em ação da artilharia otomana e das forças de reforço.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi Gazâlî entra ao serviço otomano", "a94ea459"], "d": ["Canbirdi Gazâlî, antigo emir mameluco que se retirara para Salihiyya depois de Ridâniye, recorreu ao sultão pedindo perdão. Yavuz Sultão Selim, pensando que lhe seria útil no restabelecimento da ordem no Egito e na Síria, aceitou-o ao seu serviço. Esta opção é o primeiro grande exemplo da política otomana de integrar os quadros mamelucos no sistema em vez de os liquidar.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Entrada cerimoniosa de Yavuz Sultão Selim no Cairo e leitura da hutba", "6d98080c"], "d": ["Depois de reprimidos os combates de rua, o sultão entrou no Cairo em 15 de fevereiro de 1517 com uma cerimónia muito brilhante e a hutba foi lida nas mesquitas em seu nome. A leitura da hutba no Cairo em nome do sultão otomano é a proclamação do fim jurídico do domínio mameluco, que durava desde 1250. Esta data é considerada o momento simbólico da conclusão da conquista efetiva do Egito.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Captura de Tomanbay, último sultão mameluco, em Terrûce", "7058e6ad"], "d": ["Tomanbay, que se escondera no delta do Nilo depois de abandonar o Cairo, foi denunciado pelos beduínos que lhe davam refúgio e capturado na região de Terrûce. A sua captura eliminou o centro organizado da resistência mameluca. O último sultão será mantido a partir daí catorze dias em mãos otomanas.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Execução de Tomanbay em Bâbüzüveyle e fim do Estado mameluco", "ad9820be"], "d": ["Catorze dias depois de capturado, Tomanbay foi enforcado em Bâbüzüveyle, a célebre porta do Cairo; o seu corpo foi depois sepultado na madraça mandada construir pelo seu tio. Assim, o Estado mameluco, que governava o Egito e a Síria desde 1250, desapareceu oficialmente da história. Com a quebra da resistência, cidades do Alto Egito (Said) como Asyut e Aswan foram também ligadas à administração otomana.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Ataque da armada portuguesa a Jidá e defesa de Selman Reis", "52322cf5"], "d": ["A armada portuguesa, composta por cerca de trinta galés e galeões, atacou Jidá; Selman Reis, dirigindo a defesa da cidade, impediu o desembarque do inimigo e afundou alguns navios portugueses. Esta defesa evitou que o porto de Meca, e portanto a rota da peregrinação, caísse nas mãos de um Estado cristão. Jidá será oficialmente incluída na administração otomana poucos meses depois, com a bîat do Hejaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Alexandria recebida com a armada — conclusão da conquista do Egito", "386878fe"], "d": ["Quatro meses inteiros depois de Ridâniye e trinta e seis dias depois da execução de Tomanbay, com a chegada ao porto da armada otomana sob a direção de Câfer Bey, Alexandria passou à administração otomana; também os portos do delta como Reşîd e Dimyat foram ligados no mesmo processo. O facto de este grande porto do Egito que se abre para o Mediterrâneo ter sido recebido meses depois da queda do Cairo e não por terra, mas por mar, mostra claramente que a conquista não se completou com uma só batalha, mas região a região. Alexandria tornar-se-á daí em diante o porto vital que liga Istambul ao Cairo. Outros lugares incorporados na mesma data: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Incorporação do Hejaz sem guerra: bîat de Ebû Nümeyy, filho do xerife de Meca", "c13b98c7"], "d": ["Yavuz Sultão Selim pensara primeiro em enviar soldados para tomar Meca e arredores, mas desistira disso quando o emir de Meca, o xerife Berekât, comunicou a sua obediência. Ebû Nümeyy, filho de Berekât, de doze anos, veio ao Cairo com os presentes do pai e as chaves de Meca e foi recebido na presença do sultão. Assim, o Hejaz foi incorporado nos otomanos não como consequência automática de Ridâniye, mas cinco meses e meio depois e sem um tiro, pacificamente e por bîat. Outros lugares incorporados na mesma data: Tâif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Aceitação do título de Hâdimü'l-Haremeyn e hutba em Medina", "63b32b59"], "d": ["Depois da segunda audiência da delegação de Meca, Yavuz Sultão Selim assumiu oficialmente a proteção dos Haremeyn e começou a usar o título de 'hâdimü'l-Haremeyni'ş-şerîfeyn'. O xerife Berekât, vestindo o hil'at que lhe foi enviado, mandou ler a hutba em nome do sultão; com a ida da delegação de Medina a Istambul, o emirado de Berekât foi confirmado por berat. O sultão, enviando à população dos Haremeyn duzentas mil moedas de ouro e abundantes provisões, iniciou a tradição do surre, que se repetiria todos os anos. Outros lugares incorporados na mesma data: Yenbu, Tebük.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis entra ao serviço otomano e transferência da política do mar Vermelho", "771da99a"], "d": ["Selman Reis, que defendera Jidá contra os portugueses, veio ao Cairo e foi apresentado a Yavuz Sultão Selim; embora tenha sido detido algum tempo, foi chamado em 1519 a Istambul e comprometeu-se a preparar trinta galés e alguns galeões contra a ameaça portuguesa. Este encontro é o início da assunção da política do mar Vermelho e do oceano Índico, herdada dos mamelucos, e da sua ligação direta a Istambul. Os otomanos eram agora, além de um Estado mediterrânico, uma potência que conduzia também uma política oceânica.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Partida de Yavuz Sultão Selim do Cairo e beylerbeylik de Hayır Bey", "8cd4fb23"], "d": ["Yavuz Sultão Selim, que permaneceu cerca de oito meses no Egito e estabeleceu a ordem administrativa, financeira e militar, deixou o Cairo; Hayır Bey, antigo naib de Alepo que, ao retirar a ala esquerda em Mercidâbık, acelerou a derrota mameluca, começou a governar a partir de Kal'atülcebel como o primeiro beylerbei otomano do Egito. A escolha de um governador de origem mameluca era uma política de transição consciente, que fazia com que a nova administração não parecesse estranha à população local. No caminho de regresso, o sultão levou consigo para Istambul o último califa abássida, Mutawakkil III, e artistas e sábios escolhidos do Egito.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fim do califado abássida do Cairo — relato da 'cerimónia de transferência'", "1d357640"], "d": ["Quando Yavuz Sultão Selim conquistou o Egito, trouxe consigo a Istambul o último califa, Mutawakkil III Alallah, feito prisioneiro em Mercidâbık; o califado abássida do Cairo, que se prolongava sem autoridade à sombra dos sultões mamelucos desde 1261, terminou assim. Em contrapartida, o célebre relato segundo o qual o califado foi transferido a Yavuz numa cerimónia oficial em Santa Sofia aparece pela primeira vez, no final do século XVIII, na obra de d'Ohsson e não se encontra em nenhuma das fontes do tempo de Yavuz. O TDV İslâm Ansiklopedisi, como não há nenhuma fonte original que documente a cerimónia, considera o relato inventado; contudo, regista também que, segundo a lei religiosa, não era necessária tal cerimónia de transferência para a passagem do califado.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum incorporada na administração otomana — quebrada a influência safávida na Anatólia oriental", "78d1be02"], "d": ["Embora depois da vitória de Çaldıran (1514) a influência otomana na região tivesse aumentado, a tomada completa de Erzurum atrasou-se até à quebra da influência persa; a cidade só foi incorporada na administração otomana em 1518-19, depois da campanha do Egito. Erzurum entrara no domínio safávida em 1502 com o fim, pelo xá Ismail, do Beylik Ak Koyunlu; este período de dezasseis anos ficou assim encerrado. Em 1534, durante a Campanha dos Dois Iraques, será criado o beylerbeylik de Erzurum.", "e137cb2e"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Início das revoltas celalis: revolta de Şeyh Celâl de Bozok", "99bd8a99"], "d": ["Na região de Bozok, um indivíduo chamado Şeyh Celâl, proclamando-se mahdi, revoltou-se nas imediações de Tokat; embora a revolta tenha sido reprimida, o seu nome serviu durante um século de designação para todos os movimentos de bandoleiros e de revolta na Anatólia. O celalismo, combinando-se no final do século XVI com a dissolução da ordem do timar e a pressão demográfica, transformou-se no mais duradouro problema de segurança interna do império. As revoltas provocaram na Anatólia migrações em massa, chamadas 'grande fuga'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Ligação de Argel ao Estado otomano", "b8eba4c1"], "d": ["Hayreddin Reis, que resistia à pressão espanhola no Norte de África, para se manter recorreu a Istambul e ofereceu Argel ao sultão, e a hutba foi lida em nome de Yavuz Sultão Selim. Assim, Argel foi oficialmente incorporada no território otomano e foram enviados a Hayreddin soldados e canhões com o título de beylerbei. Esta ligação lançou a base do domínio naval otomano no Mediterrâneo ocidental, que duraria séculos. Outros lugares incorporados na mesma data: Konstantin, Şerşel (Cherchell), Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Morte de Yavuz Sultão Selim em Çorlu", "9fe83744"], "d": ["Selim I, que em oito anos aumentou o território do Estado para mais do dobro, saiu de Istambul em 18 de julho de 1520 para uma nova campanha; devido a um grande tumor surgido nas costas, não pôde avançar além de Çorlu. Apesar da intervenção dos médicos, a doença agravou-se e, depois de um tratamento desesperado de dois meses, morreu aqui em 8-9 de Şevval de 926 (21-22 de setembro de 1520). Com Çaldıran, Mercidabık e Ridâniye, tinha detido o Irão e eliminado o Estado mameluco, trazendo aos otomanos o califado e o patrocínio dos Haremeyn. Deixou um único filho varão: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["A entrada da ilha de Nikarya (Ícaro) na administração otomana", "6afa972b"], "d": ["Nikarya, entre Samos e Quios, esteve de 1481 a 1521 sob a administração dos Cavaleiros de São João de Rodes; o primeiro período otomano na ilha começou em 1522 e durou até 1822. Neste período, o kaymakam era responsável pela cobrança e pelo pagamento dos impostos; tal como nas outras ilhas do Egeu, subsistiu também o conselho local de anciãos (demogerontia), que por vezes entrou em conflito com a administração otomana.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["A anexação do país de Dulkadir — a província de Dulkadır com centro em Maraş", "595c3c30"], "d": ["O país de Dulkadır, que continuava como beylik súbdito dos otomanos depois do desastre de Turnadağ de 1515, foi incorporado diretamente nas terras otomanas e transformado em província com centro em Maraş, depois de Şehsuvaroğlu Ali Bey ter sido massacrado com os filhos em Artukova. A região de Bozok do beylik foi ligada à administração otomana como sanjaco separado. Assim se encerrou o período dulkadırlı, de cerca de dois séculos, de Maraş, Elbistan, Göksun, Gürün, Zamantı e Darende; o beylik-tampão da fronteira mameluca desapareceu por completo.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["A conquista de Knin", "a46d3117"], "d": ["Com as incursões do sanjakbeyi da Bósnia Gazi Hüsrev Bey nos anos 927-928 (1521-1522), uma série de fortalezas venezianas, a começar por Knin, Skradin e Ostrovica, passou para a administração otomana; a fronteira foi empurrada para além da segunda cadeia de montanhas. Esta cadeia de conquistas lançou a base do sanjaco da Dalmácia, que seria completado quinze anos depois com a tomada de Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["A retirada dos Cavaleiros: a cedência de Bodrum, Cós e do Dodecaneso", "ea01666e"], "d": ["Pelas condições de rendição de Rodes, os Cavaleiros de São João evacuaram não só o centro da ilha, mas todas as posições que detinham havia duzentos anos. A fortaleza de Bodrum (São Pedro), na costa da Anatólia, e as ilhas de Cós, Kalymnos e Leros passaram assim, sem combate, à administração otomana. Com esta cedência, concluída duas semanas depois da queda de Rodes, a presença latina terminou por completo no canto sudeste do Egeu.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Revolta de Hain Ahmed Paşa no Egito", "b18bb805"], "d": ["Ahmed Paşa, que, quando esperava o grão-vizirato, foi enviado como governador do Egito, proclamou no Cairo a sua independência declarando-se 'al-Malik al-Mansur Sultão Ahmed'. A revolta foi rapidamente reprimida e o paxá foi morto, mas o acontecimento mostrou a fragilidade do controlo central na província mais rica do império. Em consequência, İbrahim Paşa foi ao Egito e mandou preparar o célebre Kanunnâme do Egito, que reordenou a administração da província.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["A anexação da Bósnia do Norte: Jajce e Banja Luka", "8ec86cfa"], "d": ["Quando a linha de defesa húngara ruiu depois de Mohács, o sanjakbeyi da Bósnia Gazi Hüsrev Bey marchou para o vale do Vrbas e tomou as últimas fortalezas bósnias que restavam ao reino húngaro. Com a queda de Jajce e Banja Luka, a província da Bósnia chegou a norte ao rio Sava e nasceu a frente da Croácia. Banja Luka tornou-se depressa o segundo centro da província.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Buda tomada e entregue a Zápolya", "fba4f89b"], "d": ["A caminho da campanha de Viena, o exército otomano sitiou Buda, que passara para as mãos de Fernando, e recuperou-a, entregando a cidade ao rei húngaro János Szapolyai, sob a proteção otomana. Estabeleceu-se assim, na rivalidade habsburgo-otomana pela Hungria, um modelo de reino vassalo tampão. Esta ordem durou até 1541, e depois da morte de Zápolya Buda seria feita província otomana direta.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["O Legislador partiu em campanha alemã — desafio a Carlos V", "7c3d7055"], "d": ["Depois do insucesso do cerco de Viena e do novo cerco de Buda por Fernando, o sultão partiu de Istambul, desta vez para atrair diretamente o imperador Carlos V a uma batalha campal. O exército seria retido em agosto pela resistência da pequena fortaleza de Güns e, não saindo o imperador a combate, a campanha ficaria limitada a incursões. A campanha preparou o terreno da primeira paz com os Habsburgos, no ano seguinte.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Campanha alemã e cerco de Güns (Kőszeg)", "8aec937a"], "d": ["O Legislador marchou com o seu exército contra a Áustria com o objetivo de forçar Carlos V a uma batalha campal; a pequena fortaleza de Güns resistiu vinte e cinco dias e atrasou o avanço do exército. Como o imperador não saiu a combate, os akıncıs golpearam os arredores de Viena e regressou-se com o avanço da estação. A campanha não trouxe ganhos territoriais, mas, fazendo sentar à mesa os Habsburgos, preparou o terreno da paz do ano seguinte.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Tratado de Istambul — primeira paz com os Habsburgos", "b085767a"], "d": ["O sultão, que recebeu o enviado de Fernando, Cornelius, consentiu num armistício e surgiu o primeiro texto de paz oficial entre os otomanos e a Áustria. Com o tratado, Fernando aceitou pagar um imposto anual pelos territórios húngaros que detinha e o arquiduque da Áustria foi considerado, no protocolo, igual ao grão-vizir. Este estatuto desigual era a expressão aberta da pretensão de supremacia da diplomacia otomana no século XVI.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["A tomada de Kars e a abertura da fronteira nordeste", "742e3101"], "d": ["Quando a coluna de vanguarda da Campanha dos Dois Iraques se dirigia de Erzurum para leste, a fortaleza de Kars, que estava nas mãos do atabegado georgiano e jazia em ruínas desde Timur, foi tomada sem encontrar resistência. A cidade, por guardar a passagem entre o arco do Aras e Çıldır, era considerada a chave da porta norte que se abre para o Irão. Este ganho foi o primeiro elo do beylerbeylik de Kars, que seria criado trinta anos depois, e da linha do Cáucaso.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["A primeira entrada em Tabriz — a abertura da Campanha dos Dois Iraques", "cf7ed4e3"], "d": ["Ibrahim Paxá, que avançava à frente na qualidade de comandante-em-chefe, entrou sem resistência em Tabriz, capital safávida, quando o xá Tahmasb evitou a batalha em campo aberto e se retirou para o interior. O Legislador chegou também à cidade em setembro; mas, devido ao aperto do inverno e ao excessivo alongamento da linha de abastecimento, o exército voltou-se na direção de Bagdade e Tabriz não pôde ser mantida por muito tempo. A cidade, tomada pela segunda vez depois de Çaldıran, foi o lugar onde os otomanos aprenderam que no Oriente conquistar era fácil e conservar era difícil.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Conquista de Tunes por Barbarossa", "d8754216"], "d": ["O kapudan paxá Barbarossa Hayreddin Paşa, depois de golpear com a sua armada as costas da Itália, dirigiu-se a Tunes e entrou na cidade, pondo em fuga o soberano hafsida Mevlây Hasan. A tomada de Tunes, pela sua posição de controlo do estreito da Sicília, inverteu de súbito a favor dos otomanos o equilíbrio de forças no Mediterrâneo ocidental. Contudo, este domínio não duraria muito e Carlos V responderia no ano seguinte com uma grande armada.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Perda de Tunes para Carlos V", "a691f0f8"], "d": ["Carlos V, com uma grande campanha apoiada pelas armadas de Génova e do papado, depois de fazer cair La Goulette, tomou Tunes e repôs no trono, sob proteção espanhola, Mevlây Hasan. Com a instalação de uma guarnição espanhola na cidade, o avanço otomano no Mediterrâneo central foi temporariamente detido. A conquista definitiva de Tunes só seria possível quarenta anos depois, em 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["A operação de Gazi Hüsrev Bey ao longo do Sava: Bosanski Brod e Jasenovac", "3740ec83"], "d": ["Depois da tomada de Jajce e Banja Luka em 1528, as fortalezas ao longo do rio Sava permaneceram ainda algum tempo na fronteira croata-eslavónia ligada à coroa dos Habsburgos. Gazi Hüsrev Bey, que em 1536 se tornou pela terceira vez sanjakbeyi da Bósnia, ao tomar nesse mesmo ano Požega e os arredores, anexou também à administração otomana as fortalezas de Brod e Jasenovac, na margem do Sava. Assim, a fronteira norte da Bósnia chegou ao Sava; a região foi completada dois anos depois com a tomada de Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Execução de Makbul İbrahim Paşa", "348aa7b8"], "d": ["İbrahim Paşa, que durante treze anos foi grão-vizir, amigo mais próximo do Legislador e de facto o segundo homem do Estado, foi executado, estrangulado no palácio, onde fora chamado para o iftar, sem que se apresentasse qualquer motivo. A sua atitude na campanha do Iraque, o uso do título de 'serasker sultão' e os equilíbrios internos do palácio são tidos como influentes na sua morte. A execução é um ponto de viragem que mostra que, na administração central otomana, os grão-vizires não tinham segurança absoluta.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Conquista da Fortaleza de Klis e criação do sanjaco da Dalmácia", "6ffd4ebf"], "d": ["Murad Bey, kethüdâ de Gazi Hüsrev Bey, convertido de origem croata, tomou a Veneza a estratégica Fortaleza de Klis, imediatamente a norte de Split. Logo depois da conquista, Klis foi feita centro de um novo sanjaco e kaza que abrangia os arredores; os limites deste sanjaco traçaram em grande parte o quadro da Croácia otomana. Esta conquista, que veio quinze anos depois de Knin, completou o esqueleto administrativo do interior da Dalmácia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Cerco de Corfu e guerra com Veneza", "11af95bd"], "d": ["Depois da campanha de Apúlia, o exército otomano desembarcou soldados em Corfu e sitiou a poderosa fortaleza veneziana da ilha. Devido ao carácter escarpado da fortaleza, às pesadas perdas e às condições da estação, o bloqueio foi levantado e retirou-se em 6 de setembro. Embora o cerco tenha sido infrutífero, a guerra iniciada com Veneza resultou na incorporação nos otomanos de numerosas ilhas do Egeu e do Adriático e, no ano seguinte, na vitória de Preveza.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["A campanha de Barbarossa no Egeu: a tomada das ilhas administradas diretamente por Veneza", "1b32ed96"], "d": ["A frota, que regressava do cerco de Corfu, aproveitando o facto de ter sido declarada guerra a Veneza, foi recebendo uma a uma no Egeu as ilhas dependentes não do ducado, mas diretamente de Veneza. Egina foi tomada depois de uma resistência violenta, Astipalaia, nas mãos da família Querini, Kárpathos e Kasos renderam-se, e Patmos, sob administração monástica, aceitou também a proteção otomana. O Ducado de Naxos foi deixado no seu lugar, sujeito a tributo; a sua anexação aguardaria 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["A campanha de Barbarossa no Egeu Norte: a tomada de Esquiros e das Espórades do Norte", "20ab688e"], "d": ["A caminho de Preveza, a frota foi recebendo uma a uma as ilhas do Egeu Norte que se tinham refugiado em Veneza depois da conquista de Constantinopla. Esquiros, a norte de Negroponte, e Skiathos, Skopelos e Alonissos, que guardam a entrada do golfo de Salónica, passaram assim para a administração otomana. Estas ilhas fecharam o último vazio do Egeu Norte que, embora Negroponte tivesse sido tomada em 1470, permanecera sessenta e oito anos mais em mãos venezianas.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["A tomada de Áden e a anexação da costa do Iémen", "e7d46d8f"], "d": ["A frota que partiu de Suez para a campanha da Índia dirigiu-se primeiro à costa do Iémen, porque não se podia sair para o oceano sem assegurar o mar Vermelho. Hadım Süleyman Paxá entrou no porto de Áden a 3 de agosto de 1538; o senhor tahirida Âmir b. Dâvud, inclinado aos portugueses, foi trazido à porta do capitão e executado, e deixou-se na cidade uma guarda de 500 homens. Durante a mesma campanha foram também tomados Moca e as ilhas Kamaran e Farasan, que dominam o estreito, e lançou-se a base do beylerbeylik do Iémen. Assim, o Estado Otomano passou pela primeira vez a possuir toda a margem norte de Bab el-Mandeb; Sana e as regiões do interior teriam de esperar ainda nove anos.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Campanha da Moldávia e anexação da região de Bucak (Bender)", "90a88a56"], "d": ["Na campanha dirigida contra o voivoda da Moldávia, Petru Rareş, que não cumpria as obrigações para com os otomanos, foi tomada Suceava e a cidade de Iași foi saqueada pelo cã da Crimeia Sâhib Giray. O sultão pôs no voivodado Stefan Lăcustă e incorporou, com Bender, a região de Bucak (Bessarábia meridional) diretamente no território otomano. Esta anexação tornou-se um dos elos que fizeram do noroeste do mar Negro um mar interior otomano. A Moldávia era já um voivodado vassalo dos otomanos; esta campanha não tomou o território a nenhum Estado estrangeiro, apenas retirou ao voivoda a administração interna de Bender e Bucak e ligou-a diretamente ao sultão; o resto do voivodado manteve o estatuto de vassalo. A mesma estrutura seria repetida em 1484 em Kili e Akkirman e em 1713 em Hotin: fortalezas de fronteira diretas, territórios interiores vassalos.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["A tomada de Anabolu (Náuplia) por tratado", "104d0937"], "d": ["A guerra com Veneza, que durou três anos depois de Preveza, terminou com a aceitação, pela república, de abandonar as suas duas últimas fortalezas na Moreia. Anabolu e Benefşe, que não puderam ser tomadas por cerco, foram cedidas à mesa aos otomanos, além de uma indemnização de guerra de trezentos mil ducados. A península da Moreia ficou assim unificada, sem restar uma só pegada veneziana.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["A entrada de Szeged na administração otomana e a organização do livâ de Szeged", "019aa000"], "d": ["Depois de estabelecida plenamente a administração otomana em Buda, em 1541, os notáveis de Szeged adotaram a soberania de Fernando I e prepararam-se para a defesa armada. O beylerbeyi de Buda, Küçük Bâlî Paşa, no início de 1543 mandou chamar os dirigentes da cidade e fê-los executar sob acusação de traição, enviando em seguida uma unidade para tomar a cidade. Nessa altura foi organizado o livâ de Szeged e, para o primeiro cargo de sanjakbeyi, foi nomeado Derviş Bey, filho de Bâlî Paşa; o livâ estendia-se inicialmente entre o Danúbio e o Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["A conquista de Valpo, Şikloş e Peçuy", "2ca030a3"], "d": ["O primeiro objetivo da campanha da Hungria, empreendida dois anos depois da anexação de Buda, era assegurar o flanco sul da nova província entre o Drava e o Danúbio. Depois de tomadas as fortalezas de Valpo e Şikloş, rendeu-se Peçuy, o centro de Baranya. A cidade tornar-se-ia o centro mais populoso e mais urbanizado da Hungria otomana, e o historiador İbrahim Peçuylu tomaria daí o seu nome.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Conquista de Esztergom e Székesfehérvár", "efca9e05"], "d": ["Na campanha da Hungria que o Legislador conduziu pessoalmente, depois de um cerco de duas semanas e meia, Esztergom, centro religioso do Reino da Hungria e cidade arquiepiscopal, passou à administração otomana. Em seguida foi também tomada Székesfehérvár, cidade de coroação dos reis húngaros, ficando completa a cintura de defesa da província de Buda. Esztergom permaneceria em mãos otomanas, até 1595, como fortaleza-chave da linha do Danúbio.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["O cinturão de defesa norte e oeste de Buda: Vác, Hatvan e Simontornya", "733ee5ce"], "d": ["Depois de tomadas Esztergom e Székesfehérvár, o beylerbeyi de Buda pôs-se em movimento, sem campanha do sultão, para completar o anel de fortalezas em torno da capital. Vác, no cotovelo do Danúbio, Hatvan, porta do Alföld, e Simontornya, na linha do Sió, foram tomadas uma a uma. Os ganhos deste ano silencioso fizeram de Buda deixar de ser uma cidade de fronteira para se tornar um centro de província que resistiria cento e quarenta anos.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["A anexação de Bassorá e a saída para o golfo Pérsico", "02f87c11"], "d": ["Durante a conquista de Bagdade (1534), o senhor de Bassorá, Râşid b. Megāmis, comunicara ao Legislador a sua obediência e, em 1538, enviara-lhe as chaves da cidade. Quando o xeique Yahyâ, que lhe sucedeu, se pôs contra os otomanos, o beylerbeyi de Bagdade Ayas Paxá marchou por terra e o bei do sanjaco de Mossul, com 120 navios, pelo Eufrates; Ayas Paxá entrou em Bassorá a 26 de dezembro de 1545 e a cidade tornou-se centro de um beylerbeylik. Este porto, na foz do Shatt al-Arab, era a porta pela qual os otomanos se abriam para o golfo que Portugal controlava a partir de Ormuz; pelo Tratado de Amasya de 1555, o Irão reconheceu também esta situação.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["A conquista de Sana e do interior do Iémen", "d31ded85"], "d": ["Depois de Taiz foi tomada também Sana, e todo o país foi ligado ao beylerbeylik. Mas, devido à geografia escarpada e à diferença de confissão, este domínio nunca foi cómodo; o Iémen converteu-se, para os otomanos, numa frente que devorava soldados continuamente.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["A conquista de Taiz", "d4509df9"], "d": ["No Iémen, onde nove anos antes se tinham contentado com a faixa costeira, com o crescente fortalecimento dos imames zaiditas na região montanhosa do interior, as forças de Özdemir Paxá subiram ao planalto e tomaram Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-18:0":{"b": ["Tratado de Istambul — paz de cinco anos com os Habsburgos", "41f81773"], "d": ["Foi assinada entre os otomanos e os Habsburgos uma paz de cinco anos; Fernando aceitou pagar 30.000 ducados por ano pelos territórios húngaros que detinha. O tratado registou juridicamente a situação de facto da Hungria dividida em três. A segurança assim obtida na frente ocidental deu ao Legislador a possibilidade de organizar novas campanhas contra o Irão.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["A Segunda Campanha da Pérsia e a retomada de Tabriz", "e82365df"], "d": ["Na campanha empreendida por incitamento de Elkas Mirza, irmão do xá Tahmasb, que se revoltara contra ele e se refugiara em Istambul, o exército entrou pela segunda vez em Tabriz. Como os safávidas, de novo sem entrar em batalha campal, se retiraram queimando a terra, só se pôde permanecer na cidade algumas semanas. A campanha confirmou que Tabriz não podia ser conservada e orientou a estratégia otomana para estabelecer uma linha de fronteira permanente, isto é, para fortificar Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["A conquista de Van e a fixação da fronteira oriental", "fc8f930b"], "d": ["A fortaleza de Van, cercada no regresso de Tabriz, era, pela sua posição erguida sobre uma rocha na margem oriental do lago, a chave indiscutível da região e rendeu-se depois de um breve cerco. A cidade foi imediatamente feita centro de beylerbeylik; os sanjacos de Erciş, Adilcevaz e Hakkâri foram ligados a ela. Ao contrário de Tabriz, Van foi conservada e durante quatrocentos anos permaneceu a posição permanente mais avançada dos otomanos no Oriente.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["A anexação de Lahsa e Katîf — a costa arábica do golfo", "f6701e60"], "d": ["Depois da tomada de Bassorá, foi tomada Katîf, que se tornara posto avançado de Portugal na costa ocidental do golfo, e foi criado um novo beylerbeylik juntamente com os oásis de Lahsa, no interior. Era o ponto de partida das operações contra o Bahrein e Ormuz. O Estado Otomano passou assim a ter voz ao mesmo tempo nas costas da península Arábica, tanto do mar Vermelho como do golfo Pérsico.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["A perda de Şehrizor — o bei de Erdelân, Sührâb, inclinou-se para os safávidas", "5600efc9"], "d": ["A região de Şehrizor, que reconhecera a administração otomana durante a Campanha dos Dois Iraques (1535), estava sob o governo do emir de Erdelân, Bige Bey, residente na fortaleza de Zalm. Com a morte de Bige Bey em 1550, o irmão Sührâb, que tomou a fortaleza de Zalm e dominou o beylik, voltou-se para os safávidas e deixou a obediência aos otomanos; a região de Şehrizor saiu assim da influência otomana. A região só foi recuperada em 1554, durante a campanha de Nakhichevan, com o cerco e a tomada da fortaleza de Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["A tomada de Ardahan e da bacia de Çıldır", "14c9eb76"], "d": ["O beylerbeyi de Erzurum, durante a guerra em curso com os safávidas, dirigiu-se às terras dos atabegues georgianos no arco do Kura e ligou Ardahan e os arredores de Çıldır à administração otomana. A linha Kars-Ardahan ficou assim completa e foram postas sob controlo as terras altas que se abrem para a Geórgia no nordeste. A ordem administrativa definitiva da região seria completada pela província de Çıldır, que seria criada vinte e sete anos depois.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Paxá atravessou o Danúbio — o início da guerra da Transilvânia", "38fde931"], "d": ["Perante as desordens causadas por Martinuzzi, o frade tutor do jovem rei da Transilvânia János Zsigmond, e por a Transilvânia ter cedido a Fernando as fortalezas do Banato, julgou-se necessária uma nova campanha; o comando foi dado ao beylerbeyi da Rumélia, Sokullu Mehmed Paxá. O exército atravessou o Danúbio apesar dos esforços dilatórios de Martinuzzi e tomou Beçe, Beçkerek, Çanad e Lippa; mas o cerco de Timișoara foi levantado a 16 de novembro por causa do frio. Abria-se assim na Hungria uma nova guerra otomano-habsburga.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["A cidade de Lipova (Lippa) caiu nas mãos do exército austríaco de Castaldo — a fortaleza rendeu-se a 5 de dezembro", "a0e1ff0d"], "d": ["Lipova, tomada por Sokullu Mehmed Paxá em outubro de 1551, foi cercada a 4 de novembro pelo exército do general Castaldo; dois dias depois a cidade caiu nas mãos dos austríacos. Ulama Paxá defendeu a fortaleza mais nove dias com uma guarnição de 5.000 homens e saiu por acordo a 5 de dezembro de 1551. Até à queda de Timișoara em 1552, Lipova permaneceu em mãos habsburgas.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["As forças enviadas de Timișoara tomaram as palancas do Banato meridional — Vršac, Haram, Keve", "edca0921"], "d": ["Depois da rendição de Timișoara ao exército otomano, as unidades destacadas do exército sitiante dirigiram-se às pequenas palancas do Banato; segundo a narração de Bánlaky, as palancas de Versec, Facset, Mehádia, Csákóvár, Haramvár e Keve foram tomadas por estas forças. Assim, também Haram, nas margens do Danúbio, passou às mãos otomanas.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["A conquista de Szolnok e o fracasso do cerco de Eger", "a7156e8f"], "d": ["Os dois exércitos otomanos, unidos depois da tomada de Timișoara, tomaram quase sem combate Szolnok, sobre o Tisza, ao abandonarem a fortaleza os guardas mercenários. A fortaleza de Eger, em seguida cercada, não pôde ser tomada perante a resistência de trinta e oito dias da guarnição de duas mil pessoas comandada por István Dobó, e o exército retirou-se quando o inverno apertou. O facto de, na mesma campanha, uma fortaleza cair facilmente enquanto a outra resistia foi o primeiro sinal claro de que a fronteira já não avançava por si própria em favor dos otomanos na Hungria.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Aliança otomano-francesa — armada francesa posta às ordens otomanas", "a8e01b22"], "d": ["Com o tratado de 1 de fevereiro de 1553, a armada da França foi posta às ordens da armada otomana; previu-se uma ação conjunta no Mediterrâneo ocidental contra a Espanha. Depois do tratado, Turgut Reis partiu em campanha em 15 de junho de 1553, com quarenta e cinco galés, para apoiar a França. Foi o primeiro tratado de aliança oficial que levou o terreno comercial das capitulações de 1536 para uma cooperação militar.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Execução do príncipe Mustafa em Konya Ereğlisi", "dec36858"], "d": ["O príncipe Mustafa, que entrara na tenda do pai para se juntar ao exército reunido para a campanha de Nakhchivan, encontrou os carrascos quando ia comparecer perante ele e foi morto por estrangulamento. O assassinato do candidato herdeiro, muito amado no exército, provocou entre os janízaros uma profunda ira e Rüstem Paşa foi retirado do grão-vizirato. O acontecimento passou à literatura e à memória popular como uma das rupturas mais discutidas da política dos príncipes otomanos.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["A deslocação de Ibrim e da fronteira da Núbia para sul", "c57d5d77"], "d": ["A fronteira sul do beylerbeylik do Egito deslocou-se para além da segunda catarata com a fortificação, por obra de Özdemir Bey, da fortaleza de Ibrim, que se ergue sobre um promontório rochoso no Nilo, e com a incorporação plena da Baixa Núbia no Egito otomano. (A organização administrativa otomana em Ibrim fora estabelecida logo depois da conquista do Egito; no mapa, Ibrim é mostrada como otomana desde 1517. Este ano é aproximado, a fonte não dá ano.) A fortaleza era tanto um dique contra as incursões vindas da Núbia como o ponto de controlo da rota do ouro e dos escravos que ia a Sennar. A unidade de guarda bósnia aí instalada foi tão duradoura que os seus descendentes ainda se encontravam na fortaleza trezentos anos depois. As fontes dão duas narrativas distintas sobre o momento da entrada de Ibrim na administração otomana: o artigo Sudão da TDV liga a incorporação da Baixa Núbia no Egito otomano, em meados do século XVI, à operação de Özdemir Paxá, ao passo que o artigo Núbia escreve que a região até ao vale de Halfa e a organização administrativa em Ibrim foram estabelecidas logo depois da conquista de 1517. O sanjaco de Ibrim foi ligado à província da Abissínia a 26 de julho de 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["A tomada de Bugia aos espanhóis", "49691cda"], "d": ["Bugia, que estava nas mãos da Espanha havia quarenta e três anos e dividia a costa entre Argel e Constantina, rendeu-se depois de cercada por terra e por mar. Com a queda da fortaleza, o litoral da milícia (ocak) de Argel tornou-se contínuo até Orão. Na Espanha esta perda suscitou uma indignação tão grande que o comandante que entregou a fortaleza, Alonso de Peralta, foi executado na sua terra.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["A incorporação de Zeila na Província da Abissínia", "7bbf369a"], "d": ["O porto de Zeila, na costa africana do golfo de Áden, no extremo sul da província da Abissínia, foi ligado à administração otomana. Esta cidade, porta de saída para o mar do sultanato de Adal, era o último ponto de abastecimento para os navios que saíam de Bab el-Mandeb. Com a incorporação de Zeila, a fronteira do Estado Otomano em África alcançou o seu ponto mais meridional.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Batalha dos Príncipes em Konya", "1c8de387"], "d": ["O príncipe Bayezid, que entrara na luta pelo trono, chegou diante de Konya com uma força de cerca de 30.000 homens e foi derrotado em dois dias de combates pelo seu irmão, o príncipe Selim. Bayezid, desbaratado, refugiou-se por Amásia no Irão, junto do xá Tahmasb. A batalha transformou, nos últimos anos do Legislador, a crise da sucessão ao sultanato num problema de política externa.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Vitória naval de Djerba", "c7b905c1"], "d": ["A armada otomana sob o comando de Piyâle Paşa dispersou, diante de Djerba, com uma manobra de divisão em duas, a frota aliada hispano-genovesa-maltesa reunida para recuperar Trípoli. Os aliados perderam a maior parte das suas armadas e a fortaleza da ilha caiu pouco depois. Djerba é considerada, depois de Preveza, a segunda grande vitória naval que consolidou a supremacia otomana no Mediterrâneo.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Execução do príncipe Bayezid em Qazvin", "a759de14"], "d": ["O príncipe Bayezid, refugiado no Irão, foi, no termo de longas negociações, entregue pelo xá Tahmasb à delegação otomana e morto por estrangulamento juntamente com os seus quatro filhos. Em troca da entrega, os safávidas obtiveram importantes concessões materiais e garantia de fronteira. Com esta execução, caiu o último obstáculo à subida ao trono de Selim II e preservou-se a ordem de paz de Amásia.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["A tomada de Quios aos genoveses", "a4559b96"], "d": ["Quios, governada havia duzentos anos como colónia comercial da família Giustiniani de Génova e que pagava tributo aos otomanos, foi tomada por Piyâle Paxá sem se disparar um tiro, sob o pretexto de ter deixado de pagar o tributo e de dar porto a navios inimigos. Com Quios e Psara, liquidou-se também a última presença genovesa na costa oriental do Egeu. Preservados a produção de mástique dos habitantes de Quios e os seus privilégios, a ilha foi ligada à província do Arquipélago.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["A anexação do Ducado de Naxos — todas as ilhas Cíclades", "68f0ec0b"], "d": ["O Ducado latino de Naxos, que durava desde 1207 e pagava tributo aos otomanos desde 1537, foi abolido, tomando-se por pretexto as queixas surgidas pela opressão do povo pelo último duque, Giacomo Crispo. Naxos, Paros, Antiparos, Andros, Siros, Míconos, Ios, Anafi e todas as ilhas Cíclades em redor foram postas por uma só decisão sob administração otomana direta. O Legislador entregou por algum tempo a administração das ilhas a Yasef Nasi; o domínio latino de três séculos e meio terminou assim no meio do Egeu.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Revolta do Iémen e campanha de Koca Sinan Paşa ao Iémen", "c8218d8e"], "d": ["O imame zaidita Mutahhar, revoltando-se sob o pretexto de que se cobravam impostos à força, expulsou a administração otomana de grande parte do Iémen. Koca Sinan Paşa, enviado de Istambul, com a operação conduzida entre 1568 e 1570, tomou Kawkaban após um longo cerco e restabeleceu o domínio otomano na região. A campanha era de importância vital para preservar o controlo da porta sul do mar Vermelho e da rota comercial do oceano Índico.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Aliança de defesa com o Sultanato de Aceh e auxílio ao oceano Índico", "8e835f24"], "d": ["Os enviados de Aceh, que pediam auxílio ao Legislador perante os ataques portugueses, com a morte do sultão em Szigetvár, apresentaram a sua fidelidade a Selim II e foi assinado com ele um tratado de defesa. O sultão ordenou que fossem enviados de Alexandria canhões, espingardas, munições e mestres; foram preparados dezassete navios de guerra para serem enviados às águas da Índia. O crescimento da revolta do Iémen impediu a partida da frota, mas os artilheiros e mestres otomanos que chegaram a Aceh deixaram marca duradoura na região.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["O desembarque em Chipre: a tomada de Limassol", "9074ccc9"], "d": ["O exército otomano desembarcado na ilha tomou Limassol sem encontrar grande resistência e no dia seguinte dirigiu-se a Larnaca. Por a população local estar descontente com a administração veneziana e ter ajudado as forças otomanas, também em Larnaca não se encontrou resistência séria; a escala de Tuzla foi feita base de desembarque de soldados e material. Veneza concentrara a sua defesa em Nicósia e Famagusta; o governador de Pafos só comunicou a sua obediência ao serdar depois da queda de Nicósia.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Conquista de Nicósia", "413d866b"], "d": ["Depois de um cerco de quarenta e cinco dias, iniciado em 25 de julho de 1570, Nicósia, capital de Chipre sob administração veneziana, rendeu-se ao exército otomano. A queda do centro da ilha comprimiu a resistência veneziana na fortaleza de Famagusta. A conquista causou grande eco no Ocidente e acelerou o processo que conduziu à constituição da armada da Santa Aliança sob a liderança do Papa.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["A rendição de Kyrenia — a costa norte de Chipre", "39fdeea5"], "d": ["A queda de Nicósia, a 9 de setembro, passada a fio de espada, quebrou a resistência no norte de Chipre. A fortaleza de Kyrenia, atrás das montanhas de Beşparmak, ao saber do destino da capital, rendeu-se oito dias depois sob condições, e a sua guarnição foi enviada permitindo-se-lhe sair da ilha. Na ilha, a bandeira veneziana ficou apenas em Famagusta; esta resistiria ainda onze meses.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Reconstrução da armada depois de Lepanto", "db51fe44"], "d": ["A primeira tarefa de Kılıç Ali Paşa, nomeado kapudan paxá depois do desastre de Lepanto, foi reconstruir a armada que sofrera pesadas perdas; os estaleiros trabalharam sem interrupção durante o inverno de 1571-1572. Em junho de 1572 largou para o Mediterrâneo uma nova frota composta por cerca de 250 galés e 300 galés de reis voluntários. Esta rápida recuperação mostrou que Lepanto não quebrara de forma duradoura o poder naval otomano.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Tratado de Istambul com Veneza — reconhecimento de Chipre", "4d08ef50"], "d": ["Veneza, que ficou só com a dissolução da Santa Aliança, fazendo uma paz separada com os otomanos, reconheceu oficialmente que Chipre pertencia aos otomanos e aceitou pagar uma indemnização de guerra. O tratado pôs claramente a descoberto que a vitória de Lepanto não proporcionara ao mundo cristão qualquer ganho político. Veneza evitaria daí em diante, durante setenta anos, entrar em guerra direta com os otomanos.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Morte de Selim II", "c289f5ee"], "d": ["Selim II, depois de uma queda, não pôde comparecer ao divã durante cerca de dois meses e morreu. A sua morte foi mantida secreta no palácio durante doze dias, até à chegada a Istambul do seu filho mais velho, Murad, que estava em Manisa. Quanto ao dia da morte, as fontes divergem: Selânikî diz 15 de dezembro; Gerlach, Mehmed b. Mehmed e Cenâbî dizem 13 de dezembro.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Proclamação da morte de Selim II e subida ao trono de Murad III", "84334d70"], "d": ["A morte de Selim II e a subida ao trono de Murad III, trazido de Manisa, foram oficialmente proclamadas em 22 de dezembro de 1574. O novo sultão permaneceria vinte e um anos no trono e o seu reinado seria recordado pelas longas guerras com o Irão no Oriente, pela véspera da Longa Guerra no Ocidente e pela depreciação do akçe no interior. A velha ordem na administração do Estado continuou até à morte de Sokullu Mehmed Paşa, em 1579.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Batalha de Wadi al-Makhazin (Alcácer-Quibir) — Abdulmelik, apoiado pelos otomanos, aniquilou o exército português", "21280dac"], "d": ["Abdulmelik, que subira ao trono de Marrocos com apoio otomano, aniquilou em Wadi al-Makhazin o grande exército do rei de Portugal, Sebastião; como na batalha morreram três soberanos ao mesmo tempo, é chamada nas fontes ocidentais 'Batalha dos Três Reis'. O poderio militar de Portugal ruiu e o país passou, pouco depois, para as mãos da Espanha. Abdulmelik morreu também na batalha; o seu irmão e sucessor Ahmed al-Mansur comunicou a vitória a Istambul por uma delegação. A relação entre os dois Estados ficou ao nível não de tributo ou vassalagem, mas de troca de enviados e presentes, e pouco depois tornou-se tensa por causa da questão dos presentes.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["O ato de vassalagem do povo de Derbent a Lala Mustafa Paxá — Demirkapı sob administração otomana", "9c55aeff"], "d": ["Durante a campanha de Şirvan, uma delegação de sete pessoas do povo de Derbent foi ter com o serdar Lala Mustafa Paxá, que se encontrava em Ereş, e apresentou-lhe a sua vassalagem. Derbent (Demirkapı), que fecha a estreita passagem entre a muralha do Cáucaso e o mar Cáspio, desempenhou, como passagem obrigatória das vias terrestres vindas do norte, um papel-chave na conservação de Şirvan. O domínio otomano durou aí até 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["A conquista de Şirvan: a tomada de Şamahı", "9afae4c1"], "d": ["O exército que, depois da Vitória de Çıldır, se abriu para o Cáucaso entrou em Şirvan, a mais rica província dos safávidas na costa do Cáspio, e tomou a cidade-centro, Şamahı. Özdemiroğlu Osman Paxá foi nomeado beylerbeyi aí e o ramo norte da Rota da Seda foi posto sob controlo otomano. Şirvan tornar-se-ia a frente que mais mudou de mãos e que mais custou na guerra oriental de doze anos.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["A tomada de Baku — a saída para a costa do Cáspio", "eb5adab8"], "d": ["Como último elo da operação de Şirvan, foi tomado o porto de Baku, na costa ocidental do mar Cáspio. Os poços de nafta em redor da cidade eram já então uma fonte de rendimento conhecida, e o porto era o ponto de escoamento da seda persa que vinha pelo Cáspio. O Estado Otomano passou assim a ter, pela primeira e única vez na sua história, costa no mar Cáspio.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["A conquista de Erevan e a construção da fortaleza", "7f623b7b"], "d": ["Ferhad Paxá, que em Kars recebeu a ordem de ir a Revan e aí construir uma fortaleza, marchou sobre Revan, e a cidade foi posta sob controlo otomano no início do Ramadão de 991 (meados de setembro de 1583). Em Revan, que guarda a porta norte do vale do Aras, foi construída uma nova e grande fortaleza; a cidade foi feita centro de beylerbeylik. Situada a meio da estrada militar entre Kars e Tabriz, Revan era a espinha dorsal logística da frente oriental. A fortaleza foi construída tão sólida que, durante os duzentos anos seguintes, foi o alvo constante das guerras otomano-persas.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["A anexação de Karabakh e Gence", "29abaead"], "d": ["Como último ganho da guerra oriental de dez anos, Ferhad Paxá marchou em 1588 sobre Gence e entrou na cidade a 1 de setembro; a região de Karabakh, entre o Kura e o Aras, e o seu centro, Gence, foram postos sob administração otomana. Assim, Şirvan, Revan e Karabakh uniram-se e formaram no Cáucaso uma linha otomana contínua. O Tratado de Ferhad Paxá, assinado em 1590, registaria esta fronteira, mas o ganho só poderia ser conservado durante vinte anos.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Conquista de Bihać", "651a7275"], "d": ["O beylerbei da Bósnia, Telli Hasan Paşa, depois de tomar em novembro de 1591 Ripač, fortaleza avançada de Bihać, tomou em 1592 também a própria cidade e a fortaleza; após um cerco de dez dias, o comandante Lamberg rendeu-se. Esta conquista fez avançar a fronteira da Bósnia ao longo do rio Una e foi o último grande ganho otomano na véspera da Longa Guerra, que irrompeu um ano depois com a morte mártir de Telli Hasan Paşa diante de Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Início da 'Longa Guerra' otomano-austríaca", "bd22c392"], "d": ["Com a derrota e a morte mártir do beylerbei da Bósnia, Telli Hasan Paşa, diante de Kulpa (Sisak), o Estado otomano declarou guerra à Áustria e começou a Longa Guerra, que duraria treze anos. Esta guerra, em que a infantaria com armas de fogo foi decisiva, acelerou na ordem do exército otomano o emprego de sekbans e de soldados com espingarda e aprofundou o declínio do sipahi do timar. A guerra terminaria em 1606 com o Tratado de Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Paşa partiu em campanha contra a Áustria — primeira campanha da Longa Guerra", "d4a2f46d"], "d": ["Depois da derrota e da morte mártir do beylerbei da Bósnia, Hasan Paşa, diante de Sisak, o grão-vizir Koca Sinan Paşa, com palavras brilhantes e promessas, persuadiu o sultão à guerra e partiu com 12.000 janízaros e outras unidades. Abriu-se assim a primeira campanha da guerra otomano-austríaca que duraria treze anos.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Conquista de Yanıkkale (Győr)", "14b75207"], "d": ["O grão-vizir Koca Sinan Paşa recebeu a rendição de Yanıkkale, considerada o fecho do caminho de Viena, depois de um cerco de mais de um mês. A queda da fortaleza causou grande pânico na Europa e foi o mais brilhante ganho otomano na Longa Guerra. Contudo, a fortaleza só poderia ser mantida quatro anos.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Morte de Murad III", "1b62e886"], "d": ["Depois de um reinado de vinte e um anos, Murad III morreu nos dias em que o exército da Valáquia incendiou Brăila e se estendeu até Silistre, e foi sepultado no cemitério de Santa Sofia. O seu filho Mehmed III, chamado de Manisa, chegou a Istambul dez dias depois e subiu ao trono (27 de janeiro de 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Perda de Esztergom para a Áustria", "f420d333"], "d": ["Os guardas de Esztergom, que não receberam socorro suficiente no cerco dirigido por Karl von Mansfeld, entregaram a fortaleza ao arquiduque Matias. Com o fim do domínio otomano de cinquenta e dois anos, a cadeia de defesa da linha do Danúbio foi quebrada e Buda ficou diretamente ameaçada. A fortaleza só poderia ser recuperada dez anos depois, em 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Conquista da Fortaleza de Eger", "3e511629"], "d": ["Depois de uma luta de três semanas, a poderosa Fortaleza de Eger, que os otomanos antes nunca tinham conseguido tomar, caiu com a rendição dos guardas. Esta conquista, em que o sultão esteve pessoalmente presente, reparou em certa medida o moral criado pela perda de Esztergom e foi criada a província de Eger. Com a vitória de Mezőkeresztes, ganha duas semanas depois, 1596 foi o ano mais bem-sucedido dos otomanos na Longa Guerra.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Perda de Yanıkkale (Győr)", "b4ccc679"], "d": ["As unidades sob o comando de Miklós Pálffy e Adolf von Schwarzenberg, fazendo explodir com um ataque as portas da fortaleza, recuperaram Yanıkkale. A perda da fortaleza, que Koca Sinan Paşa obtivera quatro anos antes com grandes esforços, fez ruir a linha avançada dos otomanos na Hungria. Embora no mesmo ano as forças inimigas que sitiaram Buda tenham sido repelidas, o equilíbrio da guerra foi-se transformando numa guerra de desgaste.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Revolta de Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, que reuniu os sekbans e levends fugidos do exército na Longa Guerra, tomou sob o seu controlo uma vasta região da Anatólia central, apoderou-se da Fortaleza de Urfa (novembro de 1599) e, proclamando-se sultão com o título de 'Halim Şah', enviou firmões com o seu próprio tuğra. Considerado o primeiro líder da grande vaga celali, Karayazıcı morreu em 1602, e o movimento foi prosseguido pelo seu irmão Deli Hasan. A revolta é o início do período da 'grande fuga', em que os camponeses da Anatólia abandonaram em massa a sua terra.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Defesa de Kanizsa por Tiryaki Hasan Paşa", "d56a5e6a"], "d": ["O arquiduque Fernando e os seus aliados, que queriam recuperar Kanizsa, conquistada um ano antes, sitiaram a fortaleza durante mais de dois meses; Tiryaki Hasan Paşa resistiu com a sua força de 9000 homens. Embora sem receber auxílio do exterior, repeliu os assaltos gerais e, com as operações de saída, forçou o inimigo a retirar-se com pesadas perdas. A defesa tornou-se lendária na historiografia otomana e o 'Cerco de Kanizsa' tornou-se um género literário por si só.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Morte de Mehmed III e subida ao trono de Ahmed I", "da735fde"], "d": ["Com a morte de Mehmed III em 20 de dezembro, subiu ao trono o seu filho Ahmed I, de catorze anos. O facto de ser o primeiro sultão a sentar-se no trono em tenra idade e sem ter ido a um sanjaco mostra que o costume de formar os príncipes nas províncias terminou de facto. No reinado de Ahmed I, abandonado o fratricídio, passar-se-ia ao princípio do 'ekberiyet' (subida ao trono do membro masculino mais velho).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Recuperação de Esztergom", "7330f273"], "d": ["O grão-vizir Lala Mehmed Paşa, sitiando Esztergom, perdida dez anos antes, voltou a incorporá-la na administração otomana. Na mesma campanha foram também salvas Pest e Vác, e os otomanos recompuseram a sua linha na Hungria. Este êxito permitiu sentar-se à mesa de Zsitvatorok, no ano seguinte, de forma relativamente forte; Esztergom permaneceria em mãos otomanas até 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Vitória de Oruç Ovası e repressão da revolta de Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Paşa, que fundara em Alepo um beylik independente e procurava uma aliança com a Toscana, foi gravemente derrotado na planície de Oruç pelo grão-vizir Kuyucu Murad Paşa. Com o restabelecimento da autoridade central na Síria, foi quebrado o ramo mais perigoso da vaga celali. A liquidação implacável de dois anos de Kuyucu Murad Paşa assegurou, ainda que temporariamente, a ordem na Anatólia.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Vitória de Alaçayır e repressão da revolta de Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, líder celali que submetia a tributo as regiões de Manisa e Bursa, foi derrotado em Alaçayır por Kuyucu Murad Paşa e foi forçado a fugir para o Irão. Com esta vitória foi dispersado o último dos grandes exércitos celalis da Anatólia. A dura liquidação de Kuyucu Murad Paşa, que segundo o relato mandava encher de rebeldes mortos poços que fazia cavar, embora tenha assegurado a ordem a curto prazo, não pôde compensar a perda de população e de produção da Anatólia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Concessão do primeiro ahidnâme aos Países Baixos", "5d9d117e"], "d": ["O enviado da República das Províncias Unidas, Cornelis Haga, conseguiu obter de Ahmed I um ahidnâme com o mesmo alcance que os concedidos à França e à Inglaterra. Os Países Baixos obtiveram assim o direito de abrir embaixada em Istambul, consulados nos portos otomanos e de comerciar com a sua própria bandeira. Este ahidnâme simboliza a entrada no mercado otomano das potências marítimas do norte que tomaram o lugar de Veneza no comércio do Mediterrâneo.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Morte de Ahmed I e subida ao trono de Mustafa I — princípio da ekberiyet", "9901c09e"], "d": ["Depois de uma doença de estômago de cinquenta e um dias, Ahmed I, de vinte e oito anos, morreu, e ao trono foi levado, no lugar do seu filho, o seu irmão Mustafa I. Assim, abandonada a ordem de sucessão de pai para filho, passou-se de facto ao sistema da 'ekberiyet', em que sobe ao trono o membro masculino mais velho da dinastia. Este primeiro reinado, de noventa e seis dias, é também o início da era da formação dos príncipes no 'kafes'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Deposição de Mustafa I e subida ao trono de Genç Osman (Osman II)", "e0f552f2"], "d": ["Alegando que não gozava de saúde mental, Mustafa I foi deposto ao cabo de noventa e seis dias e Osman II, filho de Ahmed I, de catorze anos, tornou-se sultão. Segundo a transmissão que remonta a Hasanbeyzâde, nesta decisão de deposição foi influente o aga dos eunucos Mustafa Ağa. Genç Osman, com o projeto de abolir o corpo dos janízaros e criar um novo exército, é considerado o primeiro nome radical dos debates de reforma otomanos. Este projeto custar-lhe-ia a vida quatro anos depois.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Tratado de Serav — renovação da paz com o Irão", "e778aca8"], "d": ["O Tratado de Serav, concluído com o Irão depois do desastre de Pul-i Shikasta, confirmou em grande parte as condições do Tratado de Nasuh Paşa de 1612; a quantidade anual de seda a enviar pelos safávidas foi reduzida de duzentas cargas para cem. Assim, a segunda fase das guerras do Oriente, que durava desde 1603, ficou encerrada. A paz não seria duradoura, e com a perda de Bagdade em 1623 a guerra voltaria a acender-se.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Campanha de Hotin e Tratado de Hotin", "bc4c823c"], "d": ["Diante do grande exército comandado pessoalmente por Osman II, o acampamento fortificado que Chodkiewicz estabeleceu diante de Hotin não pôde ser transposto, e depois de assaltos que duraram meses não se obteve resultado. Com o tratado assinado em 9 de outubro, o rio Dniester foi aceite como fronteira e os polacos comprometeram-se a impedir as incursões cossacas. A campanha, que, embora apresentada como vitória, não deu resultado, reforçou a desconfiança do jovem sultão em relação aos janízaros e a sua intenção de liquidar o corpo.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Segunda deposição de Mustafa I e subida ao trono de Murad IV", "1b3a9e74"], "d": ["Mustafa I, que fora levado pela segunda vez ao trono depois do assassinato de Osman II, foi deposto de novo ao cabo de um ano e três meses e Murad IV, de onze anos, foi proclamado sultão. Durante os primeiros nove anos, o Estado foi governado de facto pela mãe, Kösem Sultan, e pelos dignitários do palácio. Murad IV, a partir de 1632, tomaria pessoalmente o governo nas mãos, iniciando um período de dura centralização.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Perda de Bagdade para os safávidas", "db81be0c"], "d": ["Em consequência das negociações que Bekir Subaşı, que se revoltara em Bagdade, entabulou com os safávidas, o seu filho Derviş Mehmed, que defendia a cidadela interior, entregou a cidade às forças do xá Abbas. A perda de uma das cidades-símbolo da herança do califado e de grande parte do Iraque suscitou grande indignação em Istambul. Recuperar Bagdade seria, durante quinze anos, o único objetivo da política oriental otomana.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Repressão da revolta de Abaza Mehmed Paşa, com centro em Erzurum", "e6da2729"], "d": ["Abaza Mehmed Paşa, beylerbei de Erzurum, que se revoltara contra os janízaros alegando querer vingar o assassinato de Osman II, manteve durante anos a Anatólia oriental sob o seu controlo e resistiu ao centro. Foi obrigado a render-se com o cerco de Erzurum pelo grão-vizir Hüsrev Paşa e, perdoado, foi nomeado para a Bósnia. O fim da revolta era a condição prévia para que Murad IV pudesse partir em campanha contra o Irão.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Primeira execução de um xeique do Islão: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["O xeique do Islão Ahîzâde Hüseyin Efendi foi executado perto de Büyükçekmece, apresentando-se como pretexto a sua mediação na desordem militar e o facto de ter enviado ao sultão um aviso escrito sobre o processo judicial. Ser o primeiro xeique do Islão otomano executado quebrou a tradição profundamente enraizada de que a pena mais grave para os membros do ilmiye era o exílio. O acontecimento é considerado o símbolo da autoridade endurecida de Murad IV e da rutura do equilíbrio entre o Estado e os ulemás.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Conquista de Erevan por Murad IV", "b65a9b73"], "d": ["Murad IV, que partiu de Istambul em 28 de março de 1635, sitiou Erevan em 28-29 de julho e recebeu a fortaleza em rendição em 8 de agosto; em seguida entrou em Tabriz, evacuada, e mandou destruir a cidade. O sultão mandou construir no Palácio de Topkapı o Pavilhão de Erevan em memória da vitória. Esta campanha foi a primeira grande operação oriental, depois de uma pausa de trinta anos, em que o sultão comandou pessoalmente o exército.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Perda de Erevan para os safávidas", "fbb8dd25"], "d": ["Depois da retirada do exército otomano, as forças do xá Safi sitiaram Erevan e recuperaram-na em oito meses. A perda tão rápida da fortaleza mostrou quão difícil era, em termos logísticos, o domínio duradouro no Cáucaso. Erevan seria também deixada ao Irão pelo Tratado de Kasr-ı Şirin de 1639 e os otomanos renunciariam à pretensão sobre o Azerbaijão.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Reconquista de Bagdade", "4d2f27f3"], "d": ["Murad IV, que partiu de Istambul em 8 de maio de 1638, recuperou Bagdade, que estava em mãos safávidas havia quinze anos, depois de um violento cerco de quarenta dias; no cerco morreu mártir o vizir Tayyar Mehmed Paşa. Com a conquista da cidade, restabeleceu-se a administração otomana no Iraque e o sultão tomou o título de 'Conquistador de Bagdade'. A conquista, tornada duradoura pelo Tratado de Kasr-ı Şirin do ano seguinte, lançou a base da atual fronteira Turquia-Irão.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Morte de Murad IV e subida ao trono do sultão İbrahim", "e2ca1ca0"], "d": ["Depois de Murad IV, que morreu aos vinte e oito anos, subiu ao trono o seu irmão İbrahim, único membro masculino sobrevivente da dinastia. No reinado do novo sultão, que vivera anos no kafes, as despesas do palácio e as lutas de influência dentro do palácio abalaram a ordem do Estado. Com a sua deposição e assassinato oito anos depois, a história otomana viveria o segundo assassinato de um sultão.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Recuperação aos cossacos da Fortaleza de Azov", "e5fcf160"], "d": ["A Fortaleza de Azov, que os cossacos do Don tinham tomado em 1637, foi evacuada diante da operação conjunta de Sultanzâde Mehmed Paşa e do cã da Crimeia Mehmed Giray IV; os cossacos retiraram-se incendiando a fortaleza. A recuperação da porta setentrional do mar Negro encerrou o período perigoso em que as incursões cossacas se estendiam até ao Bósforo. A fortaleza seria perdida em 1696, desta vez para o czar russo Pedro I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Início da campanha de Creta e conquista de Chania", "a1b0c77f"], "d": ["Sob o pretexto de que corsários de Malta atacaram um navio otomano de peregrinação e se refugiaram em Creta, declarou-se guerra a Veneza e a armada sob o comando de Yûsuf Paşa desembarcou soldados na ilha. Depois de um cerco de cinquenta e quatro dias, a fortaleza de Chania foi tomada e estabeleceu-se em Creta a primeira base otomana duradoura. Começou assim a mais longa guerra da história otomana; a ilha só poderia ser totalmente conquistada vinte e quatro anos depois, em 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["A conquista de Réthymno — a divisão de Creta em duas", "8f2c4353"], "d": ["Um ano depois da tomada de Chania, caiu também a fortaleza de Réthymno, na parte central da ilha, e a metade ocidental de Creta passou por inteiro à administração otomana. A Veneza restaram apenas a capital, Cândia, e o extremo oriental; a ilha viveu vinte e três anos dividida em duas. A tomada de Réthymno foi o passo que iniciou o cerco de Cândia — o mais longo cerco da história começou aqui.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Perda de Klis para Veneza", "5473c22c"], "d": ["Na frente da Dalmácia da Guerra de Creta (Candia), a contraofensiva do comandante veneziano Leonardo Foscolo abrangeu também Klis, centro de sanjaco desde 1537; a fortaleza passou para Veneza. A concentração de todo o poder otomano em Creta tornou impossível recuperar esta perda na fronteira da Dalmácia — Klis não voltaria à administração otomana; o centro do sanjaco foi transferido para Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Início do cerco de Candia", "13016b10"], "d": ["Depois da tomada de Chania e Rethymno, o exército otomano pôs sob cerco Candia, o último grande ponto de apoio de Veneza na ilha. Este bloqueio, que duraria vinte e um anos, ficou registado como um dos mais longos cercos da história militar mundial. Durante o cerco, as tentativas da armada veneziana de fechar o estreito dos Dardanelos levariam a guerra ao coração do Egeu.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Assassinato da Grande Valide Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, de cerca de sessenta e dois anos, foi encontrada e morta num quarto do Harém por Başlala Uzun Süleyman Ağa e os seus homens, que agiam por ordem de Turhan Sultan, mãe de Mehmed IV. A morte desta poderosa mulher da dinastia, que orientou a política do Estado durante o tempo de três sultões, é considerada o fim de facto do período chamado 'Sultanato das Mulheres'. A autoridade que ficou vaga abriu o caminho que, cinco anos depois, conduziria Köprülü Mehmed Paşa a grão-vizir com poderes extraordinários.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Desastre dos Dardanelos e perda de Bozcaada e Lemnos", "e01a1f7e"], "d": ["A grande vitória naval que o almirante veneziano Mocenigo ganhou diante do estreito dos Dardanelos em junho de 1656 destruiu quase por completo a armada otomana; em seguida foram ocupadas Bozcaada, Lemnos e Samotrácia. Com a entrada do estreito no bloqueio veneziano, os preços dos géneros dispararam em Istambul e espalhou-se o medo de um ataque à capital. Este desastre foi a causa direta da nomeação, em setembro de 1656, de Köprülü Mehmed Paşa a grão-vizir com poderes condicionais e extraordinários.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Vitória dos Dardanelos e recuperação de Bozcaada", "603da863"], "d": ["A armada mobilizada por Köprülü Mehmed Paşa derrotou a frota veneziana diante do estreito em 19 de julho de 1657; em seguida, as forças sob o comando de Kurd Paşa recuperaram Bozcaada em 25 de agosto e em 30 de agosto os venezianos evacuaram totalmente a ilha. Em novembro, Lemnos foi também salva, o bloqueio dos Dardanelos foi quebrado e a rota de abastecimento de Istambul foi reaberta. Köprülü passou pessoalmente à ilha e mandou reparar as fortificações; este êxito é o primeiro grande ganho militar da era dos Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["A reconquista de Lemnos a Veneza", "a4c3c69b"], "d": ["Lemnos, tomada por Veneza em julho de 1656, voltou aos otomanos em novembro de 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Conquista de Yanova (Ineu) e campanha da Transilvânia", "d1089616"], "d": ["Köprülü Mehmed Paşa, que partiu em campanha para castigar o príncipe da Transilvânia György Rákóczi II, que violara a proteção otomana lançando-se sem autorização numa campanha da Polónia, marchando por Belgrado tomou a estratégica fortaleza de Yanova. Foi nomeado para a Transilvânia um novo príncipe e o vínculo de vassalagem foi duramente recordado. Esta campanha foi o primeiro elo da tentativa otomana de restabelecer a sua autoridade na Europa Central. A Transilvânia era já um principado vassalo dos otomanos; a tomada de Yanova não foi uma conquista a um Estado estrangeiro, mas a retirada desta fortaleza da Transilvânia vassala à administração principesca e a sua ligação direta a um sanjaco otomano; o resto do principado permaneceu com o estatuto de vassalo.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Repressão da revolta de Abaza Hasan Paşa", "4ba74321"], "d": ["Abaza Hasan Paşa, que, tendo por trás de si os beylerbeis da Anatólia e os aga dos sekbans contra as duras liquidações de Köprülü Mehmed Paşa, iniciou uma grande revolta exigindo a destituição do grão-vizir. A revolta foi reprimida em Alepo e os cabecilhas foram eliminados; foi a última resistência coletiva dos paxás das províncias contra o centro. A autoridade de Köprülü tornou-se assim indiscutível e o cargo de grão-vizir elevou-se de novo à posição de verdadeiro centro executivo do Estado.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Conquista de Várad (Oradea)", "0e6ad300"], "d": ["No âmbito da campanha organizada contra o príncipe da Transilvânia György Rákóczi II, que declarara guerra aos otomanos, foram tomadas a fortaleza e a cidade de Várad. Com a queda de uma das fortalezas-chave da Transilvânia, foi criada na região uma nova província otomana (Província de Várad). A conquista pôs os Habsburgos em alerta e foi uma das causas diretas da guerra otomano-austríaca que começaria três anos depois. Outros lugares incorporados na mesma data: Varat. Também aqui o território não foi tomado a um Estado estrangeiro: a Transilvânia era já um principado vassalo otomano; o facto de Várad se tornar província apenas retirou a administração desta cidade ao principado vassalo e ligou-a diretamente ao sultão, tal como dois anos antes em Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Batalha de São Gotardo (St. Gotthard)", "61ebc1f2"], "d": ["As forças otomanas que atravessaram o rio Raab foram detidas pelo exército europeu aliado sob o comando de Montecuccoli e sofreram pesadas perdas. A batalha é considerada um ponto de viragem na história militar por ter posto a descoberto pela primeira vez a superioridade do tiro de mosquete da infantaria disciplinada diante da carga de cavalaria otomana. Apesar da derrota, os otomanos conseguiram obter condições vantajosas no Tratado de Vasvár, assinado nove dias depois.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Tratado de Vasvár", "089c978c"], "d": ["O tratado, assinado apesar do desastre de São Gotardo, estabeleceu que Uyvar e Várad permaneceriam com os otomanos, que a Transilvânia seria deixada neutra sob proteção otomana e que a Áustria pagaria um 'presente' de 200.000 kuruş. Esta paz de vinte anos é um dos raros exemplos em que a parte que perdeu a guerra ganhou à mesa. O descontentamento que o tratado criou na opinião pública habsburga alimentaria o movimento da Hungria Central e, indiretamente, a campanha de Viena de 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Início da administração do dey em Argel", "e99faa51"], "d": ["O corpo de Argel e a taife-i reîs (capitães corsários) depuseram o último aga e elegeram dey, a título vitalício, Hacı Mehmed. A partir desta data, Argel passou a ser governada não pelo beylerbei nomeado por Istambul, mas pelo dey, eleito do seio do próprio corpo local; o vínculo otomano ficou limitado à leitura do nome do sultão na hutba, ao sanjaco e à obrigação de campanha. Argel passou assim de província a ocaklık — a mesma transformação que Túnis viveu em 1705 com os Huseínidas e Tripolitânia em 1711 com os Karamanlis.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Começou a campanha da Polónia — Mehmed IV e Fâzıl Ahmed Paşa à frente do exército", "75e15a39"], "d": ["Quando os ataques da Polónia contra o hetman da Ucrânia, Petro Doroshenko, que passara à proteção otomana, continuaram, Istambul pediu ao rei polaco que renunciasse aos ataques; como não veio resposta favorável, decidiu-se a campanha contra a Polónia. O grão-vizir Fâzıl Ahmed Paşa partiu para a Polónia em 4 de junho de 1672 com o exército, em que estava também o sultão. A campanha resultaria na conquista de Kamieniec e no Tratado de Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Conquista de Kamieniec e criação da Província da Podólia", "c3f4f6d0"], "d": ["Depois de um cerco de nove dias, foi tomada Kamieniec, considerada a mais forte fortaleza da Polónia no leste; Mehmed IV fez a primeira oração de sexta-feira, em 2 de setembro, na mesquita convertida a partir da catedral. A fortaleza foi feita centro da recém-criada Província da Podólia e a bandeira otomana alcançou o ponto mais ao norte nos territórios da atual Ucrânia. Kamieniec permaneceria como extremidade noroeste do império até ao Tratado de Karlowitz de 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Paşa recebeu Uman à Polónia", "0d3543a0"], "d": ["Kara Mustafa Paşa, enviado contra a Polónia, recebeu em rendição Uman, uma das fortalezas em poder da Polónia; a cidade permaneceu sob administração otomana até Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Conquista da Fortaleza de Chyhyryn", "a17cedd0"], "d": ["Depois da operação do ano anterior, em que Melek İbrahim Paşa não obtivera resultado, o grão-vizir Kara Mustafa Paşa de Merzifon, comandando pessoalmente, sitiou a fortificada Fortaleza de Chyhyryn (19/21 de julho) e tomou-a em 21 de agosto. A queda da fortaleza, símbolo da rivalidade otomano-russa sobre o hetmanato cossaco da Ucrânia, forçou a Rússia à paz. Este êxito foi também uma das fontes da confiança que levaria o de Merzifon a voltar-se para Viena.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Tratado de Bahçesaray — primeira paz oficial com a Rússia", "df82bc0b"], "d": ["No termo das negociações conduzidas por mediação do cã da Crimeia depois das campanhas de Chyhyryn, foi assinada entre o Estado otomano e a Rússia uma paz de vinte anos, aceitando-se o rio Özü (Dnieper) como fronteira. Por ser o primeiro tratado abrangente entre os dois Estados, é considerado o documento inicial das relações otomano-russas. Graças à paz, a frente oriental foi assegurada e o exército pôde ser orientado para a Europa Central.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Concessão a Imre Thököly do berat de rei da Hungria Central", "3cd8d51d"], "d": ["Imre Thököly, nobre húngaro protestante que se revoltara contra a pressão habsburga, começou a ser considerado, a partir de abril de 1682, 'rei eleito da Hungria Central' e em 16 de setembro o beylerbei de Buda, İbrahim Paşa, apresentou-lhe as insígnias principescas. Foi assim criado, sob proteção otomana, um novo Estado húngaro vassalo. Esta intervenção, tornando a guerra com a Áustria inevitável, iniciou a cadeia que conduziu ao II Cerco de Viena do ano seguinte.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Perda de Santa Maura (Lefkada) para Veneza", "e6905fee"], "d": ["A armada de Veneza, que aderira à Santa Aliança, depois de bombardear a cidade ocupou a ilha de Santa Maura, no mar Jónico. No mesmo ano, com a queda também de Preveza, o controlo otomano na entrada do Adriático foi quebrado. Estas perdas foram os passos iniciais da operação em que Morosini tomaria toda a Moreia em três anos.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Perda de Koroni para Veneza", "2ed762bc"], "d": ["As forças venezianas sob o comando de Morosini tomaram a fortaleza de Koroni, na extremidade sudoeste da península da Moreia; a cidade permaneceria daí em diante trinta anos sob administração veneziana. A queda de Koroni foi o primeiro grande ganho da operação veneziana para a conquista da Moreia. A fortaleza só pôde ser recuperada em 1715 pelo exército otomano sob o comando de Silâhdar Ali Paşa.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["A reconquista de Atenas — a retirada de Veneza", "03393b46"], "d": ["Morosini, que em setembro de 1687 bombardeara a Acrópole e fizera explodir o Pártenon, depois de passar o inverno em Atenas compreendeu que não se poderia manter na cidade. Perante a epidemia de peste, a dificuldade de abastecimento e a recomposição das forças otomanas, a guarnição veneziana evacuou a cidade e recuou para a Moreia. Atenas voltou assim, sem luta, à administração otomana, mas a destruição sofrida pelo Pártenon não pôde ser desfeita.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) rendeu-se a Caraffa — passou para as mãos da Áustria", "7f0a8d38"], "d": ["Depois do cerco de três dias de Antonio Caraffa, Lipova rendeu-se entre 12 e 22 de junho de 1688 e passou para as mãos da Áustria. Os otomanos retomaram depois a cidade, a Áustria voltou a tomá-la em 1691; na campanha de 1695 os otomanos reassumiram o controlo.", "9ddd4e2f"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Repulsa do cerco veneziano de Negroponte", "aae7e6a0"], "d": ["Morosini, que se voltou para o Egeu depois de tomar a Moreia, tentou tomar Negroponte com um cerco de mais de três meses; contudo, perante as fortificações reforçadas no inverno de 1687-1688 e a resistência da guarnição, foi obrigado a retirar-se com pesadas perdas. Este fracasso deteve o avanço veneziano no Egeu e abalou o prestígio militar de Morosini. Negroponte permaneceria em mãos otomanas também em Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Perda da Fortaleza de Kanizsa para a Áustria", "553b45f3"], "d": ["Kanizsa, posta desde janeiro de 1690 sob o apertado bloqueio de um exército habsburgo de 60.000 homens, depois de resistir durante meses sem receber auxílio, perdeu-se com o acordo de rendição assinado pelo seu último guarda, Mustafa Paşa. Terminou assim o domínio otomano de noventa anos na fortaleza que era recordada pela lendária defesa de Tiryaki Hasan Paşa. A perda de Kanizsa foi o colapso do último grande ponto de apoio otomano no oeste da Hungria.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["A morte de Süleyman II", "d2478080"], "d": ["Süleyman II, elevado ao trono em 1687 depois de cerca de quarenta anos passados em reclusão, morreu em Edirne por volta do meio-dia de sexta-feira, 22 de junho de 1691, doente, enquanto acompanhava os preparativos do exército; o seu reinado durou três anos, oito meses e dois dias. O grão-vizir dera previamente as instruções necessárias para que, em caso de morte do sultão, o irmão Ahmed fosse elevado ao trono. A oração fúnebre foi feita no mesmo dia no Alay Köşkü; o seu corpo foi trazido a Istambul e sepultado no mausoléu do sultão Solimão, o Legislador, à direita deste.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Subida ao trono de Ahmed II", "52947b14"], "d": ["Com a morte de Süleyman II, o seu irmão Ahmed II, de quarenta e nove anos, subiu ao trono em Edirne. O seu reinado coincidiu com os anos mais pesados das guerras da Santa Aliança; dois meses depois da subida ao trono, o grão-vizir Fâzıl Mustafa Paşa morreu mártir em Slankamen. Em contrapartida, o sistema do mâlikâne posto em prática no seu tempo foi uma das ordenações mais importantes que mudaram a estrutura de longo prazo das finanças otomanas.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["A morte de Mehmed IV em Edirne", "17388b7e"], "d": ["Avcı Mehmed, deposto em 1687, foi trazido a Edirne durante a campanha húngara de Süleyman II em 1689 e testemunhou também o reinado do outro irmão, Ahmed II. Morreu nesta cidade, que tanto amava. O seu corpo foi trazido a Istambul e sepultado no mausoléu da mãe, Turhan Sultan, junto à Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["A morte de Ahmed II em Edirne", "c6306c08"], "d": ["Ahmed II, cujo reinado de quatro anos decorreu em guerra, morreu em Edirne, aos cinquenta e dois anos, de istiskā (hidropisia). O seu corpo foi trazido a Istambul e sepultado no mausoléu do sultão Solimão, o Legislador. Sucedeu-lhe o sobrinho Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["A tomada de Bassorá pelos persas", "a9cdf3a3"], "d": ["Enquanto o Estado Otomano se ocupava a oeste das guerras da Santa Aliança, Bassorá, depois da epidemia de peste de 1690, sofrera primeiro o saque do xeique Mâni dos Müntefik e, depois, o de Ferecullah, cã de Huveyze. Aproveitando esta confusão, os persas tomaram a cidade em 1696 e deixaram em Bassorá uma guarda.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Tratado de Istambul — Azov deixada à Rússia", "79db4724"], "d": ["Em Karlowitz só se pudera fazer com a Rússia um armistício de dois anos; a paz duradoura foi assinada em Istambul depois de árduas negociações de um ano e meio. O Estado otomano cedeu oficialmente à Rússia a Fortaleza de Azov, perdida em 1696, e os territórios vizinhos, e renunciou ao imposto anual que o cã da Crimeia recebia de Moscovo. Em contrapartida, a Rússia obteve o direito de manter em Istambul um enviado permanente; assim, a presença russa na costa norte do mar Negro ficou juridicamente registada.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["A reconquista de Kürne e Bassorá por Daltaban Mustafa Paxá", "7adb777d"], "d": ["Daltaban Mustafa Paxá, nomeado governador de Bagdade e serasquer de Bassorá depois do Tratado de Karlowitz, marchou para sul com as forças de Alepo, Raqqa, Sivas e Karaman e com uma flotilha fluvial descida de Birecik. Os xeiques das tribos circundantes obedeceram um a um, o guarda persa de Bassorá, Dâvud Han, abandonou a cidade, e Kürne e Bassorá voltaram à administração otomana.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["A morte de Mustafa II", "626c394d"], "d": ["Mustafa II, que deixou o trono ao irmão Ahmed III com o Incidente de Edirne, morreu cerca de cinco meses depois de deposto, em Edirne, que tanto amava. À sua doença juntara-se também a aflição pelos últimos acontecimentos. Algumas fontes ocidentais escrevem que era generalizada entre o povo a convicção de que fora envenenado.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Início da administração mameluca em Bagdade", "abe52618"], "d": ["Com a nomeação de Hasan Paşa, de origem georgiana, para o governo de Bagdade, começou no Iraque o período em que, em vez de governadores nomeados pelo centro, dominava uma classe dirigente formada dos seus próprios escravos. Com o governo de Süleyman Paşa, em 1749, o sistema ficou bem assente e a Sublime Porta passou a ser obrigada a nomear não quem queria, mas um dos kölemen que tinham tomado o poder. Esta estrutura semiautónoma, embora útil na defesa da fronteira iraniana, enfraqueceu durante século e meio o controlo da autoridade central sobre o Iraque.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Fundação da dinastia Huseínida em Tunes", "cb1a98f9"], "d": ["No vazio de autoridade surgido com a invasão de Tunes pelas forças de Argel, o aga dos sipahis de origem turca Hüseyin b. Ali apoderou-se do beylik e obteve legitimidade comunicando a sua fidelidade ao sultão otomano. A dinastia que fundou governou Tunes entre 1705-1735 e 1756-1957; a ordem do corpo foi substituída por uma ordem de beylik transmitida de pai para filho. Nasceu assim o primeiro exemplo, nos ocaklık do Ocidente, de estruturas dinásticas ligadas ao centro mas de facto autónomas.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Tomada de Orão e Mers el-Kébir aos espanhóis", "b67ce06a"], "d": ["As forças do beylerbei do Corpo de Argel tomaram, depois de um longo cerco, Orão, que estava havia dois séculos em poder da guarnição espanhola, e o porto de Mers el-Kébir. Foi o maior êxito dos ocaklık do Ocidente, sob proteção otomana, contra a Espanha no Mediterrâneo ocidental e assegurou o flanco ocidental de Argel. A cidade sofreria nova ocupação espanhola em 1732, mas seria definitivamente recuperada em 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Tratado do Prut — recuperação de Azov e Taganrog", "bac5d2a1"], "d": ["O tratado de sete artigos, assinado com a rendição do exército russo cercado nas margens do Prut, estabeleceu a restituição aos otomanos da Fortaleza de Azov com o seu território e munições. As fortificações de Taganrog, Kamenka e Yenikale seriam demolidas e as partes não construiriam novas fortalezas nestas regiões. A ordem de armada e de base que Pedro I construíra durante dezasseis anos em Voronej e Azov ruiu; a chegada da Rússia ao mar Negro atrasou-se cerca de cinquenta anos.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Fundação da dinastia Karamanli em Tripolitânia", "e1105d4a"], "d": ["Em Tripolitânia, exasperada com as disputas dos agas do corpo, o oficial de cavalaria Ahmed Karamanlı tomou o governo e oficializou a sua posição com o berat de beylerbei obtido em Istambul. Com Ahmed Paşa, o seu filho Mehmed Paşa e o seu neto Yûsuf Paşa, nasceu uma dinastia que durou entre 1711 e 1835; surgiu uma estrutura semi-independente, que criou a sua própria armada e assinava tratados diretamente com os Estados europeus. Este período só terminaria em 1835, com a ligação da província diretamente ao centro.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Tratado de Edirne com a Rússia", "14901a70"], "d": ["Como as promessas dadas no Prut não foram cumpridas, tinha-se declarado guerra mais duas vezes e, finalmente, aceitando os russos os compromissos, foi assinada em Edirne a paz duradoura. O tratado confirmou as condições do Prut; a Rússia não interviria nos assuntos da Polónia, retirar-se-ia do território cossaco e não impediria o regresso ao seu país do rei sueco Carlos Cabeça de Ferro. O encerramento da frente setentrional permitiu ao Estado otomano voltar o rosto para a frente da Moreia e de Veneza. Outros lugares incorporados na mesma data: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Declaração de guerra a Veneza — preparação da campanha da Moreia", "d970b122"], "d": ["No Divã decidiu-se a guerra apresentando como motivos o apoio de Veneza aos revoltosos de Montenegro, a apreensão de navios mercantes otomanos e o esmagamento com pesados impostos da Moreia, que obtivera em Karlowitz. A campanha preparada pelo grão-vizir Silâhdar Damad Ali Paşa resultaria, no ano seguinte, na recuperação de toda a península da Moreia em menos de cem dias. Contudo, este êxito poria a Áustria em movimento e entreabriria em 1716 a porta de uma guerra muito mais pesada.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): a entrega da última ilha de Veneza no Egeu", "4abec891"], "d": ["A frota que partia para a campanha da Moreia fundeou, no caminho, diante de İstendil, a única ilha que restava a Veneza no Egeu. A ilha, que, embora o Ducado de Naxos tivesse caído em 1566, graças à sua população latina ostentara a bandeira veneziana por mais cento e cinquenta anos, rendeu-se sem derramamento de sangue depois de um breve cerco. Apagou-se assim a última pegada de Veneza no mar Egeu e o mar tornou-se por inteiro um mar interior otomano.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["A conquista de Anabolu — a fortaleza-chave da Moreia", "62a5808a"], "d": ["Anabolu, capital de Veneza na Moreia e a sua mais forte fortificação, caiu com a tomada do bastião de Palamidi depois de nove dias de bombardeamento. A rapidez com que a fortaleza foi tomada quebrou a resistência no resto da península. A recuperação da Moreia, perdida em Karlowitz, ficou de facto completa aqui.", "9b883577"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["A rendição de Modon", "43faa909"], "d": ["Depois da queda de Anabolu, a fortaleza de Modon, no extremo sudoeste da Moreia, foi cercada pelo exército por terra e pela frota por mar e rendeu-se em pouco tempo. Este porto, que Veneza usou durante duzentos anos nas suas campanhas do Mediterrâneo Oriental, era o ponto de escala obrigatório onde os navios tomavam água e mantimentos. A sua perda pôs fim à capacidade de movimento da frota veneziana no Egeu.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["A rendição de Koron — a conclusão da campanha da Moreia", "e4b9c8a4"], "d": ["Com a rendição da fortaleza de Koron, que guarda a entrada do golfo da Messénia, terminou por completo a administração veneziana na península da Moreia. A península, perdida em Karlowitz, ficou integralmente recuperada apenas três meses depois da abertura da campanha. Na continuação da mesma campanha, em setembro de 1715, foi também tomada a Veneza a ilha de Ayamavra (Lefkada), no mar Jónico. Esta rapidez forçou Veneza a levar a Áustria para a guerra e, três anos depois, abriu o caminho de Požarevac.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["A tomada da ilha de Çuha (Kythira)", "494de6c6"], "d": ["A ilha de Çuha, no extremo sul da Moreia, foi recebida pela frota depois de completada a península. A ilha, que vigia a passagem entre o mar Jónico e o Egeu, era o posto avançado de que Veneza se servia para controlar estas águas. Mas não ficou como única ilha conservada: três anos depois foi devolvida a Veneza em Požarevac.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Áustria e Veneza constituíram aliança — porta da Guerra Otomano-Austríaca de 1716-1718", "99511ca2"], "d": ["Depois da recuperação da Moreia a Veneza pelos otomanos, a Áustria, alegando a violação do Tratado de Karlowitz, assinou com Veneza um tratado de aliança; o príncipe Eugénio, numa carta ao grão-vizir, pediu a restituição dos lugares tomados a Veneza. Na consulta no acampamento de Davutpaşa, por pressão do grão-vizir Ali Paşa, declarou-se guerra à Áustria e para isso obteve-se a fetua do xeique do Islão.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["O grão-vizir Ali Paşa partiu em campanha contra a Áustria", "2fbdce42"], "d": ["Depois da declaração de guerra à Áustria, o serdâr-ı ekrem Ali Paşa partiu em campanha contra a Áustria com um exército de mais de 100.000 homens; a armada, por seu lado, dirigiu-se no mesmo verão a Corfu. O exército marcharia de Belgrado sobre Varadin e, no desastre do início de agosto, o grão-vizir morreria mártir.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Desastre de Varadin (Petrovaradin) — martírio de Damad Ali Paşa", "265c1d81"], "d": ["O exército otomano, que atravessou o Danúbio por Belgrado, encontrou-se diante de Varadin com as forças austríacas sob o comando do príncipe Eugénio; embora no primeiro ímpeto a carga dos janízaros tivesse forçado as trincheiras inimigas, com o colapso da ala de cavalaria as fileiras dispersaram-se. O grão-vizir Silâhdar Damad Ali Paşa caiu mártir, atingido na testa, e o acampamento e o trem de artilharia passaram por inteiro para mãos inimigas. Este desastre, que os vekāyi'nâmes otomanos recordam como o 'ano de Varadin', foi o primeiro elo da cadeia que conduziu à perda de Timișoara e, no ano seguinte, de Belgrado.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Fracasso do Cerco de Corfu", "b2aa7011"], "d": ["O seraskere da Moreia Kara Mustafa Paşa por terra e o kapudan paxá Canım Hoca Mehmed Paşa pela armada, por mar, lançaram-se sobre Corfu; a ilha era a base-chave de Veneza no Adriático. Contudo, as fortificações extremamente fortes da fortaleza, os reforços trazidos pela armada veneziana e as notícias do desastre na frente do Danúbio levaram ao levantamento do cerco. O facto de Corfu não ter podido ser tomada apagou o ar de entusiasmo que se elevara com a reconquista da Moreia e deslocou o centro de gravidade da guerra para a Hungria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Perda de Timișoara (Timişvar) para a Áustria", "27fe1365"], "d": ["Depois do desastre de Varadin, o príncipe Eugénio marchou diretamente sobre Timișoara e a fortaleza foi entregue por capitulação ao cabo de um cerco de mais de quarenta dias. A cidade, conquistada em 1552 no tempo do Legislador e considerada durante 164 anos, como centro de beylerbeylik, o pilar oriental da defesa da Hungria, perdeu-se assim. Com a queda de Timișoara, todo o Banato passou à Áustria e a fronteira otomana foi empurrada para sul do Danúbio.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Entrega da fortaleza de Haram (Nova Palanka) à Áustria — perdida a margem do Danúbio do Banato", "38ee4c6d"], "d": ["O general de cavalaria austríaco Mercy, encarregado de tomar o resto do Banato depois da queda de Timișoara, marchou em 14 de novembro sobre Haram (Nova Palanka), nas margens do Danúbio; quando chegou à fortaleza em 16 de novembro, a guarnição otomana de 200 homens rendeu-se com a condição de hastear a bandeira branca e retirar-se livremente. Assim, a linha do Danúbio do Banato meridional, que estava em mãos otomanas desde 1552, passou também à Áustria.", "8026e3e4"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["O Tratado de Požarevac — a Moreia ganha, Belgrado e o Banato perdidos", "d46aa216"], "d": ["A Moreia fora retomada a Veneza, mas a Áustria, que entrara na guerra, levou vantagem à mesa com as vitórias obtidas em Petrovaradin e Belgrado. O tratado assinado com a mediação da Inglaterra e da Holanda deixou a Moreia aos otomanos; em contrapartida, juntamente com Belgrado, a Sérvia do Norte, o Banato e a Pequena Valáquia foram cedidos à Áustria; nas palavras da TDV, 'a Bósnia do Norte foi inteiramente cedida à Áustria' — fortalezas como Bosanska Dubica e Bosanski Brod, ao longo do Sava, passam no mapa para a Áustria a partir deste dia (a fronteira exata foi traçada uma a uma pelos comissários, e a TDV não enumera estas fortalezas pelo nome); Veneza, por sua vez, conservou posições como Preveza e Çuha, na costa jónica. Pelo tratado de comércio assinado no mesmo dia, a taxa aduaneira cobrada sobre as mercadorias austríacas foi reduzida de cinco para três por cento. O tratado, ao registar o recuo do Estado Otomano na Europa Central, lançou os alicerces do Período das Tulipas (Lâle Devri, 1718-1730), aberto por uma paz de vinte e sete anos: sob a governação de Nevşehirli Damad İbrahim Paşa, a primeira tipografia otomana (1727, İbrahim Müteferrika), as comissões de tradução, as observações sobre a vacina da varíola e uma nova vida de palácio e de cultura são produto destes anos de paz.", "3a9f1433"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Campanha oriental: tomada de Tbilisi e início da guerra com o Irão", "78343dc2"], "d": ["Com o colapso do Estado safávida pela invasão afegã e a descida da Rússia às costas do Cáspio, o Estado otomano enviou um exército para o leste para que o vazio não ficasse inteiramente entregue à influência russa. Tbilisi foi tomada e a Geórgia foi ligada à administração otomana; em seguida o avanço prosseguiu na direção de Ganja, Erevan e Nakhchivan. Esta campanha, conduzida por trás da aparência pacífica da Era das Tulipas, foi o início de uma longa aventura oriental que duraria treze anos e terminaria com a restituição de tudo o que se ganhara.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["A Campanha da Pérsia de 1723: a entrada em Şirvan e na Geórgia", "c81189fc"], "d": ["Com o colapso do Estado safávida devido à invasão afegã, foi aberta uma campanha para o Oriente sob o pretexto de impedir a Rússia de descer às costas do Cáspio. O exército de Erzurum entrou em Tbilisi pela Geórgia e o ramo de Şirvan em Şamahı, recuperando os territórios perdidos cento e trinta anos antes. Esta campanha foi o último grande avanço otomano no Cáucaso.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["A tomada de Kirmanxá — a porta de Zagros", "ad14799f"], "d": ["O exército de Bagdade transpôs as passagens do Zagros e tomou Kirmanxá, considerada a porta ocidental do Irão. A cidade ficava na estrada de caravanas e de exércitos que vai de Bagdade a Ispaã e a sua tomada assegurava a segurança oriental da província do Iraque. Este avanço iniciou, no país safávida em desagregação, a corrida da partilha entre os otomanos e a Rússia.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukāsemenâme de Istambul — partilha do Irão com a Rússia", "fce8eec2"], "d": ["Para evitar que os otomanos e a Rússia se defrontassem sobre o país safávida em colapso, foi assinado um tratado de partilha por mediação do enviado francês. As costas ocidental e meridional do mar Cáspio foram deixadas à Rússia; a Geórgia, Şirvan, o Azerbaijão e as cidades do Irão ocidental ao Estado otomano. Esta partilha, que parecia um grande ganho no papel, ficaria de facto sem efeito pouco depois, com a ascensão de Nadir Xá.", "36a04f61"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["A tomada de Nakhichevan", "bdf14d0a"], "d": ["As forças otomanas que avançavam ao longo do Aras tomaram Nakhichevan e Ordubad; Culfa foi também incorporada no livâ de Nakhichevan. A cidade foi ligada, como porta noroeste do Irão, à recém-criada província de Revan. Assim, a fronteira otomana alcançou de novo a linha mais oriental da época do Legislador.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["A conquista de Hemedan", "e1339a97"], "d": ["O exército que marchava para leste a partir de Kirmanxá tomou, depois de um longo cerco, Hemedan, no limiar ocidental do planalto iraniano. A cidade era a última grande paragem da estrada de Ispaã, o ponto mais oriental que os exércitos otomanos tinham podido alcançar desde a Campanha dos Dois Iraques. A Convenção de Istambul assinada no mesmo ano com a Rússia pôs no papel a partilha do Irão em desagregação entre os otomanos e a Rússia.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["A reconquista de Erevan", "88acabef"], "d": ["Depois de um duro cerco de noventa dias, Revan, fortaleza-chave do vale do Aras, voltou à administração otomana. A fortaleza, construída em 1583 e perdida em 1604, foi desta vez fortificada com uma guarnição mais forte. A duração do cerco era indício de que o exército otomano já não avançava facilmente. As nahiyes de Karpi (Üçkilise), Şerür, Makû e Şüregel foram também ligadas à província de Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["A tomada de Tabriz — a conquista do Azerbaijão", "e502a4f7"], "d": ["Cercada de novo após a tentativa falhada do ano anterior, Tabriz rendeu-se ao exército otomano depois de uma batalha árdua, travada rua a rua. Merend, Merâga e Sovukbulak (Mahabad), dependentes da província de Tabriz, passaram também para a administração otomana. No mesmo ano foram igualmente tomadas Lori, Gence, Erdebil e Hürremâbâd, ocupando-se de facto as regiões que cabiam aos otomanos pelo Tratado de Istambul. A extensão alcançada a leste foi a fronteira mais avançada desde a época do Tratado de Ferhad Paxá; contudo, mantê-la impôs uma pesada carga ao exército e ao tesouro.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["A conquista de Gence — o fim da campanha do Cáucaso", "875bca7a"], "d": ["Gence, o último objetivo da operação do Cáucaso, foi recebida como centro de Karabakh, entre o Kura e o Aras. Com a conclusão da linha Şirvan, Revan, Nakhichevan e Gence, o Estado Otomano alcançou no Cáucaso a extensão de 1590. Mas este ganho foi de curta duração: a ascensão de Nâdir Xá retomaria toda a região em dez anos.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Tratado de Hemedan — a incorporação do Irão Ocidental no Império Otomano", "94a29dc3"], "d": ["Com o tratado assinado com o soberano afegão Eşref Xá, terminou a guerra de quatro anos e foram juridicamente reconhecidos os territórios do Irão Ocidental ocupados pelo Estado Otomano. Em troca, Eşref Xá aceitou o califado do sultão otomano e comprometeu-se a que a sexta-feira fosse lida em nome do sultão no Irão. Esta vitória diplomática foi de curta duração; a contraofensiva iniciada por Nâdir Xá em 1730 haveria de apagar, em poucos anos, os ganhos do tratado.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Paxá tomou Rûmiye", "eac7f64d"], "d": ["Na campanha do Irão, Hekimoğlu Ali Paxá tomou primeiro Urmia (Rûmiye) e depois Tabriz, evacuada para os otomanos, a 15 de novembro de 1731. A TDV não dá o dia da tomada de Urmia; sabe-se apenas o ano e que foi anterior a Tabriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Tratado de Ahmed Paxá — a devolução da maior parte do Irão Ocidental", "590d839f"], "d": ["Perante a vitória de Nâdir Xá em Melâyir e as ofensivas persas sucessivas, o governador de Bagdade, Ahmed Paxá, assinou um texto de paz sem consultar o centro. Segundo o tratado, o rio Aras foi aceite como fronteira; cidades do Irão Ocidental como Hemedan, Kirmanxá, Erdelan, Erdebil e Tabriz foram devolvidas ao Irão, ficando Gence e Tbilisi com os otomanos. Recebido com indignação em Istambul, este texto foi também considerado insuficiente por Nâdir Xá, e a guerra reacendeu-se antes de findar o ano de 1732.", "b7cf810a"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["A nova perda de Orão para a Espanha", "20485027"], "d": ["A grande frota de desembarque enviada pelo rei Filipe V de Espanha, sob o comando do conde de Montemar, chegou diante de Orão e, derrotando as forças da milícia de Argel, retomou a cidade. O porto, conquistado vinte e quatro anos antes, permaneceria durante sessenta anos nas mãos de uma guarnição espanhola. Esta perda, que mostrou os limites do poder das milícias do Magrebe no Mediterrâneo Ocidental, só foi compensada pela conquista definitiva de Orão em 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["A reforma do Corpo dos Bombardeiros à maneira europeia e a fundação da Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Paxá, de origem francesa e entrado ao serviço otomano, com o apoio do grão-vizir Hekimoğlu Ali Paxá, converteu o corpo dos bombardeiros numa unidade assalariada e organizada à europeia. Trezentos soldados recrutados na Bósnia receberam instrução regular baseada no cálculo e na geometria; prepararam-se novos regulamentos de organização, equipamento e reforma, e produziram-se, com técnica moderna, cem morteiros e cinquenta mil granadas. A Humbarahâne, onde se ensinava geometria, é considerada o primeiro núcleo da formação em engenharia militar moderna no Império Otomano.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["A morte de Ahmed III", "455f7fba"], "d": ["Ahmed III, deposto em 1730 pela revolta de Patrona Halil, passou os últimos seis anos da sua vida no apartamento do Palácio de Topkapı destinado aos sultões depostos e morreu aos sessenta e três anos. Foi sepultado em Bahçekapı, no mausoléu da avó, Turhan Sultan, junto à Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Tratado de Istambul — a cedência do Cáucaso Meridional ao Irão", "8c205aab"], "d": ["A segunda guerra com o Irão, que durara quatro anos, terminou com o tratado assinado após o desastre de Arpaçay e a perda de Gence e de Tbilisi. O Estado Otomano retirou-se de todo o Cáucaso Meridional e do Irão Ocidental que ocupava desde 1723, e a fronteira voltou à linha de Kasr-ı Şîrin de 1639. Das campanhas orientais de treze anos ficaram um pesado encargo financeiro e um tesouro esvaziado; em contrapartida, o encerramento da frente oriental era um ganho vital para a nova guerra que se iniciava com a Rússia.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["A queda da fortaleza de Özi (Ochakov) para os russos", "f93e61f3"], "d": ["O exército russo comandado pelo marechal Münnich cercou a fortaleza de Özi, na foz do Dniéper; com a explosão do paiol, a defesa ruiu e a fortaleza caiu com grandes perdas humanas. A perda de Özi, considerada a chave da costa noroeste do mar Negro, abriu aos russos o caminho da Crimeia e causou grande pânico em Istambul. No ano seguinte, a fortaleza seria evacuada pelos russos devido a uma epidemia e a dificuldades de abastecimento e voltaria para os otomanos.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["A vitória de Banja Luka — a libertação da Bósnia", "f603865a"], "d": ["Quando as forças austríacas entraram na Bósnia e cercaram Banja Luka, o governador da Bósnia, Hekimoğlu Ali Paxá, acorreu em socorro com forças reunidas entre a população local e infligiu uma pesada derrota ao inimigo, superior em número. Esta vitória fez ruir logo no primeiro lance o plano austríaco de ocupar a Bósnia, e o norte da província foi inteiramente recuperado. Banja Luka foi um dos pontos de viragem que reergueram o moral do exército otomano, que após 1683 recuava continuamente perante a Áustria.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["A vitória de Hisarcık (Grocka) — a abertura do caminho de Belgrado", "2101cdff"], "d": ["O exército austríaco, que avançava para proteger Belgrado, foi apanhado numa emboscada num desfiladeiro estreito junto ao Danúbio e sofreu pesadas perdas numa batalha que durou o dia inteiro. Enquanto as forças do marechal Wallis recuavam desordenadamente para Belgrado, o exército otomano chegou diante da fortaleza e iniciou o cerco. Hisarcık foi a vitória em campo aberto mais decisiva obtida contra a Áustria desde Karlowitz e permitiu diretamente a recuperação de Belgrado.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Tratado de Niš — paz com a Rússia, neutralização de Azak e fim das incursões na Crimeia", "674f974e"], "d": ["A Rússia, que ficou sozinha quando a Áustria aceitou a paz em Belgrado, foi obrigada a pôr termo à guerra com a mediação do embaixador francês Villeneuve. As fortificações da fortaleza de Azak foram demolidas e a região declarada terreno neutro entre os dois Estados; a Rússia aceitou a condição de não ter navios de guerra nem de comércio no mar Negro. Assim, o objetivo russo de aceder ao mar foi adiado por mais uma geração, e o Estado Otomano levantou-se da mesa com proveito pela última vez no século XVIII.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi regressa da ocupação russa: a fortaleza foi entregue depois de demolida, pela paz de 1739", "7ecc2bef"], "d": ["Os russos tinham tomado Özi a 11 de julho de 1737. Em virtude da paz feita com a Rússia em 1739, a fortaleza foi entregue de novo aos otomanos depois de demolidas as suas fortificações; os otomanos mantiveram Özi até 1788, antes do Tratado de Iaşi.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["A defesa de Mossul — a repulsa de Nâdir Xá", "c03ffbc1"], "d": ["Nâdir Xá, que chegou diante de Mossul depois de tomar Quircuque e Arbil, bombardeou a cidade durante quarenta dias e lançou ataques gerais sucessivos. A defesa conduzida pelo governador Hüseyin Paxá al-Celîlî, que armou também a população da cidade, obrigou o exército persa a levantar o cerco com pesadas perdas. A resistência de Mossul impediu a perda de todo o Iraque e consolidou, durante um século, a influência da família Celîlî na cidade.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["A Aliança de Dir'iye — a fundação do primeiro Emirado Saudita em Najd", "188751bf"], "d": ["O emir Muhammed b. Suûd, que acolheu sob a sua proteção em Dir'iye o sábio Muhammed b. Abdülvehhâb, expulso de Uyeyne, formou com ele uma aliança que punha a autoridade política ao serviço da pregação religiosa. Este acordo iniciou uma nova história para a família Saud e uniu num único movimento os emirados dispersos dos oásis de Najd. Este poder, que em meio século se estenderia a Cerbala, Meca e Medina, obrigaria o Estado Otomano a defender o seu domínio no Hejaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Tratado de Kerden — o fim das guerras otomano-persas", "1d3a919e"], "d": ["Com o tratado assinado depois da última guerra, que durara quatro anos, a fronteira de Kasr-ı Şîrin de 1639 foi renovada tal como estava; nenhuma das partes obteve ganhos territoriais. A insistente exigência de Nâdir Xá de que o jafarismo fosse reconhecido como quinta escola ficou sem resposta; em compensação, decidiu-se que os peregrinos persas pudessem fazer livremente a peregrinação e que houvesse troca recíproca de embaixadores. As guerras otomano-persas, que se prolongavam por mais de dois séculos, ficaram assim de facto encerradas; esta fronteira foi em grande parte conservada até hoje.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["A morte de Mahmud I e a entronização de Osman III", "30203700"], "d": ["Mahmud I, que no seu reinado de vinte e quatro anos recuperou os territórios perdidos pelo Tratado de Belgrado e apoiou a reforma do Corpo dos Bombardeiros, faleceu quando regressava da cerimónia de sexta-feira (selâmlık). Sucedeu-lhe o irmão Osman III, que vivera em reclusão até aos cinquenta e oito anos. Começou um reinado curto e inquieto; no tempo de Osman III, que mudou seis grão-vizires em três anos, os assuntos do Estado conheceram uma notória estagnação.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["A morte de Osman III e a entronização de Mustafa III", "3ac10f85"], "d": ["Com a morte de Osman III, após um reinado de três anos, subiu ao trono Mustafa III, aberto a ideias de reforma e que mostrava estreito interesse pelos assuntos do Estado. O novo sultão, apoiando-se na experiência do grão-vizir Koca Râgıb Paxá, procurou sanear as finanças e renovar o exército; nesta época foi criada a artilharia ligeira do barão de Tott. Mas a guerra com a Rússia, iniciada em 1768, haveria de ofuscar todos os ganhos de um reinado de dezassete anos.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Declaração de guerra à Rússia — o incidente de Balta e o início da guerra de 1768-1774", "9c6aabe0"], "d": ["Depois de tropas russas e cossacas, que perseguiam a Confederação de Bar na Polónia, terem invadido e incendiado a vila de Balta, na fronteira otomana, o Divã decidiu a guerra e o embaixador russo foi encarcerado em Yedikule. A guerra, empreendida sem preparação militar séria e declarada com seis meses de antecedência, correu mal desde o início. Esta luta, que duraria seis anos, haveria de se converter, com o ataque de Çeşme, o desastre de Kartal e a ocupação da Crimeia, numa das mais pesadas séries de derrotas da história otomana.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["A perda da fortaleza de Hotin para os russos", "66d43ea4"], "d": ["Tendo sido repelidas duas tentativas do exército russo comandado pelo príncipe Golitsyn, o exército recuou após o desastre sofrido pelo grão-vizir entre Kamaniçe e Hotin, e os guardas evacuaram a fortaleza. A perda, sem resistência, da mais forte praça otomana a norte do Danúbio abriu aos russos as portas da Valáquia e da Moldávia. Os dois principados foram ocupados no mesmo ano; Hotin só foi recuperada em 1774, pelo Tratado de Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["O desastre da planície de Kartal (Kagul)", "6f408eaf"], "d": ["Três semanas após a queima da frota em Çeşme, o principal exército otomano junto ao Danúbio dispersou-se na planície de Kartal diante das tropas, muito menores em número mas disciplinadas, do marechal Rumyantsev. O acampamento, as bagagens e centenas de canhões caíram nas mãos do inimigo; as tropas em fuga sofreram grandes perdas ao atravessar o Danúbio. A destruição, no mesmo verão, da frota e do exército de terra levou à queda sucessiva de Kili, Akkirman, İsmail e Bender e à ocupação da Crimeia.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["A ocupação russa da península da Crimeia", "217837b0"], "d": ["Os exércitos russos, que um ano antes tinham tomado o Bucak, sob o comando do príncipe Dolgorukov transpuseram Or Kapı e invadiram toda a península da Crimeia. O cã foi deposto e Sâhib Giray, favorável aos russos, foi posto à frente, dando-se o primeiro passo para separar o canato do Império Otomano. A perda da Crimeia, escudo setentrional dos otomanos havia três séculos, foi o início do processo que levaria à independência em 1774 e à anexação direta em 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["A morte de Mustafa III e a entronização de Abdülhamid I", "42cba8e2"], "d": ["No lugar de Mustafa III, falecido no momento mais crítico da guerra com a Rússia, subiu ao trono, aos quarenta e nove anos, o irmão Abdülhamid I, que passara quarenta e três anos na reclusão do palácio. Tendo herdado um dos períodos mais difíceis do Estado, o novo sultão teve de enfrentar as duras condições do Tratado de Küçük Kaynarca, que seria assinado nesse mesmo ano. O seu reinado de quinze anos decorreria entre a perda da Crimeia e uma nova guerra com a Rússia, e terminaria em 1789 com a paralisia que sofreu ao ler a notícia da queda de Özi.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["O desastre de Kozluca — a derrota que levou a Küçük Kaynarca", "8e0542f9"], "d": ["As forças otomanas reunidas diante de Şumnu foram vencidas em Kozluca pelas colunas conjuntas de Suvorov e Kamenski, e a maior parte do exército dispersou-se. Com este desastre não restou nos Balcãs força capaz de resistir; as vanguardas russas cercaram Şumnu e o quartel-general do grão-vizir ficou ameaçado. O facto de se ter ido à mesa de negociações em Küçük Kaynarca antes de passar um mês e de se terem aceitado condições extraordinariamente pesadas é consequência direta desta derrota.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["A cedência da Bucovina (Moldávia do Norte) à Áustria", "190f9caa"], "d": ["Aproveitando a fraqueza causada por Küçük Kaynarca, a Áustria reclamou a região da Bucovina, que assegura a ligação entre a Moldávia e a Transilvânia, e obteve este território sem entrar em guerra, por ameaça e suborno. A perda desta região fértil e estratégica, a sudoeste de Hotin, dividiu de facto em duas o voivodado da Moldávia. Esta cedência, feita sem se disparar um único tiro, foi considerada um dos sinais mais claros de que o Estado Otomano já perdera a sua capacidade de dissuasão.", "dc1e97dd"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["A ocupação persa de Bassorá", "0161e709"], "d": ["Sâdık Han, irmão do soberano zende Kerim Han, tomou Bassorá depois de um cerco de um ano, e o Estado Otomano perdeu o seu mais importante porto no golfo Pérsico. A ocupação abalou diretamente a rota comercial da Índia, as receitas das tâmaras e das pérolas e a defesa meridional do Iraque. A cidade só pôde ser recuperada em 1779, durante as lutas pelo trono que se seguiram no Irão à morte de Kerim Han.", "838306ba"]},
"OLAYLAR_EK5:1779-03-10:0":{"b": ["Tenkihnâme de Aynalıkavak — acordo provisório sobre a Crimeia", "9b3b0468"], "d": ["Os dois Estados, que estiveram à beira da guerra por causa de quem ficaria à frente do canato da Crimeia, assinaram, com a mediação da França, um texto de esclarecimento no pavilhão de Aynalıkavak. A Rússia aceitou retirar as suas tropas da Crimeia e o Estado Otomano aceitou reconhecer o canato de Şâhin Giray, favorável aos russos; foi confirmado o direito de califado religioso do sultão sobre a Crimeia. Este frágil equilíbrio, que duraria quatro anos, ruiria por completo em 1783 com a anexação direta da península pela Rússia.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["A construção da fortaleza de Anapa — a linha de defesa do Cáucaso", "be92a80f"], "d": ["Com a perda da Crimeia por Küçük Kaynarca, iniciou-se a construção de uma nova fortaleza na foz do rio Kuban para preservar a influência otomana no Cáucaso. Anapa, edificada sobre as ruínas de uma colónia genovesa, com o seu bazar, os banhos e mais de duzentas e cinquenta lojas, tornou-se em pouco tempo uma cidade que assegurava a ligação com as tribos circassianas. A fortaleza permaneceu, durante quarenta e oito anos, o posto mais avançado dos otomanos contra a descida da Rússia para o Cáucaso.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["A destituição e execução do grão-vizir Halil Hamîd Paxá", "c44001ca"], "d": ["O grão-vizir reformador Halil Hamîd Paxá, de cujos serviços Abdülhamid I mostrara em várias ocasiões estar satisfeito, foi destituído de repente por volta da manhã de 31 de março de 1785 e exilado para Gallipoli, e todos os seus bens foram confiscados. Foram-lhe dadas primeiro a província da Abissínia, o sanjaco de Jidá e o cargo de xeique dos haremeyn de Meca; enquanto passava abril de 1785 em Tenedos com os preparativos para a viagem, foi destituído também deste governo e, pelo firmão de execução que saiu, foi morto por Karakethüdâzâde Ali, homem de Cezayirli Gazi Hasan Paxá. A cabeça cortada foi enviada a Istambul e exibida em Ortakapı. Segundo a TDV, embora esta queda súbita tenha sido interpretada com a acusação de uma trama para depor o sultão e pôr em seu lugar o príncipe Selim, as verdadeiras causas devem ter sido a indignação pelo seu silêncio perante a anexação da Crimeia, a hostilidade dos meios lesados pelas suas reformas e a oposição de Gazi Hasan Paxá.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Declaração de guerra à Rússia — começou a guerra otomano-russa de 1787-1792", "3bfb870c"], "d": ["Perante a ostentosa viagem de Catarina II à Crimeia e o facto de ela ter tomado a Geórgia sob a sua proteção, o Divã decidiu a guerra para reverter a anexação, e o embaixador russo foi de novo encerrado em Yedikule. Mas o exército não estava pronto, o tesouro estava vazio e a busca de aliados fora infrutífera. A guerra, que duraria cinco anos, terminaria com a queda de Özi com massacre, a perda de İsmail e as duras condições do Tratado de Iaşi.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["A entrada da Áustria na guerra — luta em duas frentes", "ae912290"], "d": ["Em virtude da aliança secreta que fizera com a Rússia em 1781, o imperador austríaco José II declarou guerra ao Estado Otomano e pôs-se em marcha na direção de Belgrado e da Bósnia. O exército otomano viu-se de repente obrigado a combater em duas frentes ao mesmo tempo: a Rússia a norte e a Áustria a oeste. Apesar das vitórias obtidas contra os austríacos em Lazarethane, Muhâdiye e Şebeş, a frente ocidental ruiria também em 1789 com a perda de Belgrado.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Aliança otomano-prussiana", "03b88e51"], "d": ["Selim III, que procurava aliados na Europa logo que subiu ao trono, assinou com a Prússia um tratado de aliança que previa assistência mútua; a Prússia comprometeu-se a declarar guerra à Rússia e à Áustria, e o Estado Otomano a não fazer a paz sem que a Crimeia fosse recuperada. Este foi, na história otomana, o primeiro verdadeiro texto de aliança recíproca assinado com um Estado europeu e mostrava que fora abandonada a concepção clássica de que 'não há aliança com os infiéis'. A Prússia não entrou na guerra, mas, forçando a Áustria à paz, abriu caminho ao Tratado de Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["A queda da fortaleza de İsmail e o massacre", "6a296b0c"], "d": ["A fortaleza de İsmail, considerada a mais forte praça do delta do Danúbio, foi tomada num só dia por um sangrento assalto geral organizado pelo general Suvorov; a guarnição e a população da cidade foram em grande parte passadas a fio de espada. Este massacre, que teve grande eco na Europa, provocou um choque profundo na opinião pública otomana e quebrou a espinha dorsal da linha de defesa do Danúbio. A fortaleza seria recuperada um ano depois pelo Tratado de Iaşi, mas o destino da guerra já estaria decidido.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Tratado de Sistova — o encerramento da frente austríaca", "58741f1d"], "d": ["Graças à pressão da Prússia e ao facto de a Revolução Francesa ocupar a Áustria a ocidente, os dois Estados chegaram à paz tomando como base as fronteiras anteriores à guerra. A Áustria devolveu todos os lugares que ocupara, incluindo Belgrado; o Estado Otomano aceitou apenas pequenas correções na fronteira da Croácia. O encerramento da frente ocidental nestas condições permitiu ao Estado Otomano concentrar todas as suas forças contra a Rússia e limitou a perda no Tratado de Iaşi.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Tratado de Iaşi — a perda definitiva da Crimeia e a fronteira do Turla", "a56fd194"], "d": ["Pelo tratado assinado no fim da guerra de cinco anos, o rio Turla (Dniestre) foi aceite como fronteira; a margem esquerda do rio ficou para a Rússia e a direita para os otomanos, e Özi e os seus arredores perderam-se definitivamente. O Estado Otomano abandonou por completo a esperança de recuperar a Crimeia e reconheceu juridicamente a anexação de 1783; a Valáquia e a Moldávia foram restituídas com isenção de impostos por dois anos. Aceite também a obrigação de uma indemnização de guerra de doze milhões de kuruş, o norte do mar Negro ficou cedido de modo permanente à Rússia. Outros lugares que passaram na mesma data: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["A evacuação de Orão pelos espanhóis e a sua cedência a Argel", "9f95cee6"], "d": ["Quando a fortaleza e a cidade foram em grande parte destruídas pelo sismo de 1790, a Espanha, que já não podia suportar a dispendiosa guarnição mantida havia três séculos, entendeu-se com a milícia (ocak) de Argel e cedeu sem guerra Orão e Mers el-Kébir. Foi assim liquidada também a última posição europeia na costa do Norte de África. A Argélia otomana manteve-se senhora de toda a costa durante os trinta e oito anos que passariam até à ocupação francesa.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["O domínio de facto de Pazvandoğlu Osman em Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, que se revoltou contra as medidas do Nizâm-ı Cedîd, fez fugir o governador de Vidin, apoderou-se da cidade e fortificou-a com fossos profundos ao longo do Danúbio. Em 1797, no auge do seu poder, reuniu cerca de oitenta mil homens e pôs sob o seu controlo Nikopol, Sistova, Ruse, Sófia e Niš; apresentava-se a si próprio não como rebelde, mas como reformador. O cerco de meses que a Sublime Porta lhe pôs em 1798-1799 foi infrutífero, e ele governou de forma semi-independente no norte da Bulgária até à sua morte, em 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["A abertura da Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Para formar oficiais de artilharia, de fortificação e cartógrafos para o exército do Nizâm-ı Cedîd, abriu em Hasköy a escola de engenharia terrestre; era o equivalente, no exército de terra, da Escola de Engenharia Naval fundada em 1773. O programa ensinava álgebra, geometria, mecânica, fortificação e balística, e foram traduzidos de línguas europeias livros de matemática e de artilharia. Esta escola, considerada a raiz do ensino moderno de engenharia na Turquia, é tida como o início da atual Universidade Técnica de Istambul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Declaração de guerra à França e aliança com a Rússia e a Inglaterra", "80e95bd7"], "d": ["Com a invasão do Egito por Napoleão, o Estado Otomano rompeu a tradicional amizade francesa de dois séculos e meio e declarou guerra à França. No mesmo processo, aliou-se pela primeira vez na sua história à Rússia e permitiu que a frota russa passasse pelos Estreitos e saísse para o Mediterrâneo; a seguir foi assinada também uma aliança com a Inglaterra. Graças a estas alianças, as ilhas Jónicas foram tomadas aos franceses, mas a abertura dos Estreitos a uma frota estrangeira criou um precedente de pesado custo futuro.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["A tomada de Preveza aos franceses — a Batalha de Nicópolis", "d8e5e892"], "d": ["Quando a República de Veneza foi destruída, em 1797, as ilhas Jónicas e, em terra firme, Preveza, Parga e Vonitsa caíram nas mãos da França. O governador de Ioannina, Tepedelenli Ali Paxá, aproveitando a guerra aberta com a invasão do Egito pela França, marchou sobre Preveza e infligiu uma pesada derrota à guarnição francesa nas ruínas de Nicópolis, fora da cidade. Assim, este porto, deixado a Veneza em Požarevac, entrou na administração otomana oitenta anos depois.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["A defesa de Acre — a repulsa de Napoleão", "56b5c45b"], "d": ["Napoleão, que avançava do Egito para a Síria, cercou Acre e lançou ataques sucessivos durante dois meses; a cidade foi defendida por Cezzâr Ahmed Paxá, com o apoio da frota inglesa e das tropas do Nizâm-ı Cedîd enviadas de Istambul. Napoleão, obrigado a levantar o cerco e a recuar para o Egito, enterrou diante destas muralhas o sonho de se estender para o Oriente. A notícia foi recebida com grande alegria em Istambul e considerada a prova de que o exército disciplinado recém-criado passara o seu primeiro exame sério.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["A incursão wahhabita a Cerbala", "522341ed"], "d": ["As forças wahhabitas, partidas de Najd, entraram em Cerbala, saquearam a cidade, destruíram o mausoléu do imam Hussein e mataram mais de três mil pessoas. Os governadores mamelucos do Estado Otomano no Iraque não conseguiram impedir a incursão; o caso suscitou grande reação tanto no Irão como em Istambul. Este ataque foi a proclamação de que o movimento saudita deixara de ser um emirado de oásis e se transformara numa potência regional que ameaçava as cidades santas otomanas.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-12:0":{"b": ["Kartli-Kakheti (Geórgia Oriental) foi anexada à Rússia", "3b650c5e"], "d": ["O czarado de Kartli-Kakheti, que aceitara a proteção russa em 1783 e sofrera em 1795 a devastadora campanha do Irão, foi dissolvido; por ordem de 12 de setembro de 1801 foi declarado província da Rússia e começou a implantar-se o sistema administrativo russo. A Geórgia perdeu a independência a partir desta data; em poucos anos, também Mingrélia (1803), Imerécia e Guria (1804) entraram no domínio russo e a Rússia chegou à fronteira otomana do Cáucaso.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["A evacuação do Egito pelos franceses", "00cfdc8c"], "d": ["Em resultado da operação conjunta das forças otomanas e inglesas por terra e por mar, foram entregues primeiro o Cairo e depois Alexandria, e as forças francesas foram enviadas de navio para o seu país. Ao terminar a ocupação de três anos, o Egito regressou no papel à administração otomana, mas a luta pelo domínio entre os seus beis mamelucos e as tropas albanesas lançou o país no caos. Este vazio preparou, em poucos anos, o terreno para a ascensão de Mehmed Ali de Cavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Tratado de Paris — o restabelecimento da paz com a França", "1b76991f"], "d": ["Com o tratado assinado depois da evacuação do Egito, o estado de guerra entre o Estado Otomano e a França terminou oficialmente e foram renovadas as antigas capitulações. Foi permitida a entrada de navios mercantes franceses no mar Negro; em contrapartida, a França reconheceu a integridade territorial otomana. O estabelecimento da paz devolveu margem de manobra à política externa de Selim III, apertada entre a Rússia e a Inglaterra.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["A tomada de Taif pelos wahhabitas", "7b791359"], "d": ["As forças wahhabitas comandadas por Suûd b. Abdülazîz, no primeiro movimento contra o Hejaz, cercaram e saquearam Taif; a cidade caiu como a primeira porta que se abria para as terras santas. Para o sultão otomano, que ostentava o título de protetor dos Haremeyn, foi um golpe que abalou diretamente a legitimidade do sultanato. Dois meses e meio depois, o mesmo exército marcharia sobre Meca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["A primeira tomada de Meca pelos wahhabitas", "21157c05"], "d": ["Dois meses e meio depois da queda de Taif, as forças wahhabitas entraram em Meca, derrubaram os mausoléus e instauraram uma ordem segundo a sua própria compreensão; o xarife Gālib foi obrigado a retirar-se para Jidá. O encerramento das rotas da peregrinação ecoou em todo o mundo islâmico e obrigou Istambul a pedir ajuda militar ao governador do Egito, Mehmed Ali. Este primeiro domínio duraria apenas três meses.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["A reconquista de Meca pelo xarife Gālib", "83d08dff"], "d": ["O xarife Gālib, que se retirara para Jidá, cercou Meca com as forças que reuniu e, depois de um cerco de vinte e cinco dias, retomou a cidade aos wahhabitas; a hutbe voltou a ser lida em nome dos otomanos. Este segundo domínio também não seria duradouro, pois as forças de Suûd retomariam a cidade em 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["O início da Primeira Insurreição Sérvia", "0f6e8767"], "d": ["Quando os dahis janízaros rebeldes, que tinham tomado o poder em Belgrado, massacraram em massa os notáveis sérvios, começou uma resistência armada sob a liderança de Karađorđe. O movimento, conduzido inicialmente apenas contra os dahis, mantendo-se fiel ao sultão, transformou-se em pouco tempo numa revolta nacional que reclamava autonomia e independência. As forças sérvias tomaram Belgrado em 1806; esta insurreição foi o primeiro elo dos movimentos nacionalistas de independência nos Balcãs.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["A ocupação de Medina pelos wahhabitas", "84e310d7"], "d": ["Depois de Meca, também Medina caiu nas mãos das forças wahhabitas; o tesouro de Ravza-i Mutahhara foi distribuído e os mausoléus abobadados da cidade foram derrubados. Assim, as duas cidades santas saíram ao mesmo tempo do controlo otomano, e as caravanas de peregrinos vindas de Damasco e do Egito não puderam partir durante anos. Medina só pôde ser recuperada sete anos depois, em 1812, pelo exército egípcio comandado por Tosun Paxá, filho de Mehmed Ali Paxá.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["O início da guerra com a Rússia (guerra otomano-russa de 1806-1812) e o encerramento dos Estreitos", "ea170804"], "d": ["Depois de Selim III, que se aproximara da França após a vitória de Napoleão em Austerlitz, ter deposto, apesar da pressão russa, os voivodas da Valáquia e da Moldávia, os exércitos russos ocuparam os dois principados e a guerra começou. O Estado Otomano fechou os Estreitos à frota russa; em contrapartida, a Inglaterra, ao lado da Rússia, enviou uma esquadra a Istambul. Esta guerra, que duraria seis anos, entrelaçada com a Revolta de Kabakçı e a deposição de Selim III, terminaria no Tratado de Bucareste de 1812 com a perda da Bessarábia.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["A chegada da frota inglesa diante de Istambul (operação de Duckworth)", "195bb58f"], "d": ["A Inglaterra, que queria forçar o Estado Otomano a romper os laços com a França, fez passar por Çanakkale a esquadra comandada pelo almirante Duckworth e fundeou-a diante de Istambul. Com a orientação também do embaixador francês Sébastiani, o povo de Istambul mobilizou-se, as baterias costeiras foram reforçadas em poucos dias e a esquadra, sem poder bombardear a cidade, teve de recuar; no regresso sofreu pesadas perdas em Çanakkale. O facto de a capital ser pela primeira vez ameaçada tão de perto por uma frota estrangeira colocou a questão dos Estreitos no centro da diplomacia europeia.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["O estrangulamento de Mustafa IV", "eeb75c20"], "d": ["Quando Alemdar Mustafa Paxá foi atacado e morreu e os rebeldes quiseram marchar sobre o palácio, o deposto Mustafa IV foi estrangulado por ordem do irmão Mahmud II. O seu funeral foi sepultado em Bahçekapı, no mausoléu do pai, Abdülhamid I; espalhou-se entre os rebeldes o rumor de que o caixão estava vazio.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Tratado de Kal'a-i Sultâniyye — paz com a Inglaterra e regra dos Estreitos", "fe282117"], "d": ["Com o tratado assinado com a Inglaterra após o fracasso da operação de Duckworth, terminou a guerra entre os dois Estados e foram restituídos os antigos privilégios dos comerciantes ingleses. A disposição do texto, chamada 'regra antiga', registou que em tempo de paz nenhum navio de guerra estrangeiro podia passar pelos Estreitos. Este princípio tornou-se o fundamento jurídico de todos os arranjos internacionais que moldariam o regime dos Estreitos ao longo do século XIX.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["O desastre de Slobozia — o cerco do exército do Danúbio", "54b60fd1"], "d": ["A maior parte do exército otomano que atravessara o Danúbio diante de Ruse foi encurralada em Slobozia pela manobra de envolvimento de Kutuzov a partir da margem oposta do rio e deixada à fome. Milhares de soldados foram obrigados a render-se; a força nas mãos do grão-vizir derreteu de facto, e a Sublime Porta teve de pedir um armistício um mês depois. Esta derrota é a causa direta de se ter consentido, no Tratado de Bucareste de 1812, na cedência da Bessarábia.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["A reconquista de Belgrado e a repressão da Primeira Insurreição Sérvia", "06f56f52"], "d": ["Privados do apoio russo pelo Tratado de Bucareste, os insurretos sérvios não resistiram à operação conjunta das forças vindas da Bósnia e da Rumélia; Hurşid Ahmed Paxá entrou em Belgrado e a insurreição de nove anos foi totalmente reprimida. Karađorđe fugiu para a Áustria e o sanjaco de Semendire voltou a ficar diretamente sob administração otomana. Mas as duras medidas aplicadas desencadeariam, dois anos depois, uma segunda e duradoura insurreição sob a liderança de Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["A Segunda Insurreição Sérvia e o título de grão-cnez de Miloš Obrenović", "e6e82ad2"], "d": ["Contra as duras medidas aplicadas após a repressão da primeira insurreição, rebentou uma nova revolta sob a liderança de Miloš Obrenović; desta vez a Sublime Porta preferiu o acordo à força. Pelo entendimento alcançado, Miloš foi reconhecido com o título de 'grão-cnez' e a competência de cobrar impostos e conduzir os assuntos internos foi deixada aos cnezes sérvios. Este primeiro núcleo de autonomia de facto foi o ponto de partida do processo que se prolongaria até ao firmão de 1830 e à independência de 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["A Revolta da Valáquia — a travessia do Prut por Ypsilanti e a insurreição de Vladimirescu", "67d46a98"], "d": ["Aleksandr Ypsilanti, general do exército russo, tentou iniciar, em nome da Filikí Etería, uma insurreição geral grega na Valáquia e na Moldávia, atravessando o Prut; nos mesmos dias, Tudor Vladimirescu pôs também em movimento os camponeses locais. Os dois movimentos não se uniram: Vladimirescu respondeu ao apelo de Ypsilanti para combaterem juntos os turcos com 'Não me revoltei contra os turcos, mas contra os gregos', e pouco depois foi morto pelos homens de Ypsilanti. A revolta foi reprimida pelas forças otomanas em maio, mas a ordem dos voivodados fanariotas terminou e o fogo da insurreição propagou-se à Moreia.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["A fundação do Segundo Estado Saudita em Riade", "34dad3bd"], "d": ["Seis anos depois da queda de Dir'iye em 1818 e da destruição do primeiro Estado Saudita, Türkî b. Abdullah expulsou de Najd as guarnições egípcias e fundou um novo emirado saudita com capital em Riade. A nova estrutura evitou estender-se ao Hejaz, preferindo ficar em Najd, e manteve-se afastada do confronto direto com as forças otomano-egípcias. Este segundo Estado duraria até ao fim do século e formaria o segundo elo da cadeia que conduziria à fundação da atual Arábia Saudita. Outros povoamentos perdidos na mesma data: Dir'iye (Najd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Tratado de Akkirman — concessões à Sérvia e aos principados", "c75f15d0"], "d": ["O Estado Otomano, que ficara sem exército logo após a abolição do Corpo dos Janízaros, foi obrigado a aceitar, perante o ultimato da Rússia, um tratado de condições pesadas. Foi confirmada a autonomia prometida à Sérvia, aceitou-se que os voivodas da Valáquia e da Moldávia não pudessem ser depostos sem a aprovação russa e foi concedida aos navios mercantes russos plena liberdade nos Estreitos. Quando a Sublime Porta declarou, dois anos depois, que não reconhecia o tratado por causa da questão grega, a Rússia viria a tomar isso como pretexto de guerra.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["A liquidação do sistema do timar", "84d5d1d6"], "d": ["Um ano depois da abolição do Corpo dos Janízaros, cerca de 5.200 sipahis com timar, existentes em cinquenta e três sanjacos da Rumélia e da Anatólia, foram convertidos, com as rendas dos seus timares, em cavalaria do Asâkir-i Mansûre. Assim terminou de facto o regime do timar, espinha dorsal de quatro séculos da ordem otomana da terra, dos impostos e do exército. Os timares vagos foram transferidos para o tesouro, abrindo-se o caminho para a passagem a um exército central assalariado e a um sistema de impostos em dinheiro.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["A fundação da Tıphâne-i Âmire — o início do ensino moderno da medicina", "ac3e57c0"], "d": ["Para formar médicos e cirurgiões para o exército recém-criado do Asâkir-i Mansûre, abriu em Şehzadebaşı a Tıphâne-i Âmire, por proposta do médico-chefe Mustafa Behçet Efendi. As aulas foram organizadas segundo o currículo europeu e o ensino foi inicialmente dado em francês; alguns anos depois foi fundada também a Cerrahhâne-i Âmire e as duas instituições foram unidas. Esta escola, considerada o início do ensino moderno da medicina na Turquia, é tida como a origem da atual Faculdade de Medicina de Istambul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["O início da guerra otomano-russa de 1828-1829", "9dff4e05"], "d": ["Depois da queima da frota em Navarino e de a Sublime Porta ter declarado que não reconhecia o Tratado de Akkirman, a Rússia declarou guerra em duas frentes ao mesmo tempo. Como o Corpo dos Janízaros acabara de ser abolido e o novo exército estava ainda em fase de formação, a defesa otomana foi fraca desde o início; enquanto os russos atravessavam o Danúbio, tomaram a leste Kars e Ahıska. O exército russo, que em um ano avançou até Edirne, imporia as duras condições do Tratado de Edirne de 1829 e a independência da Grécia.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["O primeiro tratado com os Estados Unidos da América", "d737516f"], "d": ["Com o tratado de comércio e navegação assinado após anos de contactos, os EUA obtiveram nas terras otomanas o estatuto de nação mais favorecida e o direito de passagem comercial pelos Estreitos. Um artigo secreto separado previa que os otomanos pudessem, quando quisessem, mandar construir navios em estaleiros americanos e comprar navios prontos e madeira; o Senado dos EUA ratificou o tratado, mas rejeitou este artigo secreto por 27 votos contra 18. Ainda assim, o caminho dos navios não se fechou: Henry Eckford vendeu aos otomanos, em 1831, o navio que trouxera, e os mestres americanos que trabalhavam em Aynalıkavak deram à marinha novos tipos de navios. Este tratado foi o documento da primeira relação abrangente do Estado Otomano com um Estado fora da Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["O fim do governo mameluco em Bagdade", "7e1d38a3"], "d": ["Mahmud II, que seguia uma política de centralização, declarou rebelde o governador de Bagdade, Dâvud Paxá, que não enviava o dinheiro pedido e mandara matar o funcionário vindo do centro. A força comandada por Ali Rızâ Paxá tomou a cidade após um cerco de noventa dias e quase todos os mamelucos foram liquidados. Assim terminou o governo mameluco semi-independente que durava desde 1704, e o Iraque voltou a depender diretamente do centro.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["A fundação da Mekteb-i Harbiye no quartel de Maçka", "bf31c7d9"], "d": ["Para fornecer ao Asâkir-i Mansûre-i Muhammediyye oficiais formados à europeia, abriu no quartel de Maçka a Mekteb-i Fünûn-ı Harbiyye. Aos alunos ensinaram-se matemática, cartografia, fortificação e línguas estrangeiras; pouco depois foram enviados alunos a Viena e a Paris para reforçar o quadro. Esta escola foi o lugar onde nasceram a tradição do oficial formado em escola no exército otomano e, por conseguinte, a nova geração de militares-intelectuais que surgiria no fim do século XIX.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["A ligação direta de Trípoli de Barbaria ao centro — o fim da dinastia Karamanlı", "faabcb96"], "d": ["Perante as lutas pelo trono dentro da família Karamanlı e a crescente pressão europeia após a ocupação de Argel pela França em 1830, a Sublime Porta interveio diretamente em Trípoli de Barbaria. A esquadra enviada de Istambul entrou na cidade, o último bei Karamanlı foi deposto e levado para Istambul, e a província foi entregue a um governador nomeado pelo centro. Ao terminar o período dinástico de 124 anos, ficou consolidado o último pedaço de território que o Estado Otomano governava diretamente no Norte de África.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["A abolição do defterdarlık e a criação do Ministério das Finanças", "89f8125e"], "d": ["Abolido o cargo de defterdar, chefe da ordem financeira otomana clássica, foi criado o Maliye Nezâreti, um ministério à maneira europeia, e os tesouros dispersos foram reunidos numa só mão. No mesmo ano, as outras unidades da Sublime Porta foram também reorganizadas sob o nome de nezâret, passando-se a uma estrutura de conselho de ministros moderno. Esta organização foi um dos passos mais importantes na preparação da infraestrutura administrativa do Édito de Tanzimat, que seria proclamado um ano depois.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["A instalação dos ingleses em Áden", "ddbd556b"], "d": ["A Inglaterra, apoiando-se no acordo de comércio e amizade que assinara em 1802 com o sultão de Lahej, Ahmed b. Abdülkerîm, desembarcou tropas no porto de Áden e pôs a cidade sob o seu controlo. Este porto, que guarda a entrada do mar Vermelho, converteu-se em ponto-chave da estratégia imperial inglesa como base de abastecimento de carvão da rota da Índia. Embora a pretensão do Estado Otomano sobre o Iémen subsistisse no papel, o seu domínio de facto na costa meridional nunca mais voltou depois desta data.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["O regresso à costa de Tihâme: a tomada de Hudeida, Zabid e Moca", "353982d2"], "d": ["À costa do Iémen, que ficara sem dono com a retirada do exército egípcio em 1840, desembarcaram forças comandadas por Tevfik Paxá, sob a supervisão do xarife de Meca, e puseram os portos de Hudeida, Zabid e Moca sob a administração otomana. Embora se quisesse avançar até Sana, voltou-se a Hudeida devido à resistência da população; assim, as terras altas ficaram com os imames zaiditas e o domínio otomano durou vinte e três anos apenas na faixa de Tihâme. O interior do Iémen só seria recuperado em 1872, com a campanha de Ahmed Muhtar Paxá.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["A Convenção de Baltalimanı: protetorado conjunto otomano-russo na Valáquia e na Moldávia", "d3bb22e9"], "d": ["Com a propagação das revoluções de 1848 à Valáquia e à Moldávia, as forças otomanas e russas tinham ocupado em conjunto os principados. Pela convenção assinada em Baltalimanı, decidiu-se que os voivodas fossem nomeados pelo sultão por sete anos, e não por eleição, e que os dois Estados estabelecessem um controlo conjunto na região. O acordo, ao mesmo tempo que preservava a soberania otomana no papel, concedeu à Rússia um direito de parceria de facto e acelerou a separação dos principados do Danúbio do Império Otomano.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["A questão dos refugiados húngaros: o asilo de Kossuth e dos seus companheiros no Império Otomano", "1c7d7ef4"], "d": ["Quando a revolução húngara de 1848-1849 foi reprimida pela intervenção russo-austríaca, Lajos Kossuth e milhares de refugiados húngaros e polacos acolheram-se em terras otomanas. A Áustria e a Rússia exigiram com dureza a extradição dos refugiados; a Sublime Porta, com o apoio da Inglaterra e da França, recusou a extradição e instalou o grupo em Kütahya. O círculo de Kossuth ficou aí cerca de dezoito meses, e centenas de refugiados converteram-se ao islão e entraram ao serviço otomano. O caso foi considerado uma das raras vitórias diplomáticas que elevaram o prestígio do Império Otomano do Tanzimat na opinião pública europeia.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["A fundação do Encümen-i Dâniş: a primeira academia otomana em Istambul", "6fda1365"], "d": ["O Encümen-i Dâniş, criado por decisão do Meclis-i Maârif-i Umûmiyye, é a primeira academia científica otomana constituída para preparar obras de ciência e manuais em turco. Foi inaugurado com cerimónia no edifício do Dârülmaârif a 18 de julho de 1851; entre os seus membros, nacionais e estrangeiros, contava-se também Ahmed Cevdet Paxá. Embora de curta vida, obras como o Târih de Cevdet Paxá e o Kavâid-i Osmâniyye foram produto desta instituição, que é considerada uma pedra angular na afirmação do turco como língua da ciência.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["A vitória de Oltenița: o primeiro êxito otomano na frente do Danúbio", "a660ad2f"], "d": ["Na fase inicial da Guerra da Crimeia, o comandante-em-chefe Ömer Lütfi Paxá atravessou o Danúbio e repeliu em Oltenița as forças russas com pesadas perdas. Ao deter o avanço russo logo no início da guerra, a vitória mostrou à Europa a força que o exército otomano ganhara com a instrução posterior ao Tanzimat. Este êxito preparou o terreno psicológico que facilitou a decisão da Inglaterra e da França de entrarem na guerra ao lado dos otomanos.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["O tratado de aliança com a Inglaterra e a França em Istambul", "04809278"], "d": ["O tratado de aliança assinado na Guerra da Crimeia entre o Estado Otomano, a Inglaterra e a França, contra a Rússia, estipulou que os três Estados conduzissem operações conjuntas e que os aliados não fizessem paz separada antes do fim da guerra. Assim, o Estado Otomano entrou pela primeira vez na sua história numa aliança militar com as grandes potências europeias como parte em pé de igualdade. Este tratado constituiu também a base jurídica da admissão formal do Império Otomano no sistema de Estados europeus, dois anos depois, em Paris.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["A criação da Şehremaneti de Istambul: a primeira organização municipal moderna", "be4af27f"], "d": ["A crise de infraestruturas provocada pelos soldados aliados que afluíram a Istambul durante a Guerra da Crimeia e pelo aumento da população revelou a insuficiência da administração urbana clássica centrada no cádi. Com a Şehremaneti, criada segundo modelos europeus, a limpeza, o controlo de preços, a fiscalização dos mercados e as obras de urbanização foram reunidos numa só mão; no ano seguinte foi constituída, como região-piloto, em Beyoğlu-Galata a Sexta Circunscrição Municipal. Este passo é considerado o início do municipalismo moderno no Império Otomano.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["O Tratado de Paris: o fim da Guerra da Crimeia e a admissão do Império Otomano no sistema de Estados europeus", "4aee0e2a"], "d": ["Pelo Tratado de Paris, que pôs fim à Guerra da Crimeia, o Estado Otomano foi declarado membro igual do direito dos Estados europeus e a sua integridade territorial ficou sob a garantia comum das grandes potências. O mar Negro foi neutralizado, a pretensão russa de proteção sobre os súbditos ortodoxos, que mantinha desde Küçük Kaynarca, foi invalidada, e o sul da Bessarábia (os distritos de Kili, Cahul, İsmail e Bolgrad) foi dado à Moldávia. Contudo, o mesmo tratado, ao converter o Édito de Reforma num compromisso internacional, entreabriu também a porta à ingerência nos assuntos internos.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["A abertura do Palácio de Dolmabahçe: a transferência do centro administrativo do Topkapı", "71ad26d0"], "d": ["O palácio que Abdülmecid encomendara em 1842 à família Balyan foi aberto após catorze anos de construção, e o centro administrativo do Estado passou do Topkapı, de quatro séculos, para a margem do Bósforo. Com o seu estilo europeizante, a escadaria de cristal e o Salão de Cerimónias, o palácio foi a expressão em pedra da pretensão ocidentalizante do Tanzimat. O seu custo enorme tornou-se uma das rubricas mais criticadas dos anos em que as finanças otomanas entraram na espiral do endividamento externo.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["A união da Valáquia e da Moldávia sob Cuza: o nascimento da Roménia", "baef4da5"], "d": ["Nas eleições organizadas depois do Tratado de Paris, os dois principados elegeram voivoda o coronel Alexandru Ioan Cuza, realizando a união de facto. Embora a Sublime Porta e a Áustria se tivessem oposto, tiveram de aceitar o facto consumado, apoiado pela França. Esta união, que no papel continuava dependente dos otomanos, tomaria em 1862 o nome de Roménia e em 1877 proclamaria unilateralmente a independência; é um ponto de viragem na dissolução do domínio otomano ao longo do Danúbio.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["O Incidente de Kuleli: a primeira tentativa de golpe contra Abdülmecid em Istambul", "e3653b21"], "d": ["Uma sociedade secreta de composição mista, militar e civil, que reagia à política do Tanzimat e à igualdade concedida pelo Édito de Reforma aos não muçulmanos, foi surpreendida em reunião na Mesquita de Kılıç Ali Paxá quando planeava depor o sultão. Como os acusados foram julgados no Quartel de Kuleli, o caso ficou conhecido por este nome; as penas de morte foram comutadas em exílio. É considerado a primeira tentativa de golpe de palácio empreendida, na história otomana, por uma organização constituída por motivos ideológicos.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["A guerra civil drusa-maronita no Monte Líbano e os acontecimentos de Damasco", "5595fdd6"], "d": ["Os confrontos que rebentaram em maio de 1860 com a morte de dois drusos perto de Sídon converteram-se na mais sangrenta guerra civil drusa-maronita da montanha e, propagando-se a Damasco em julho, resultaram na morte de milhares de cristãos. Com o desembarque de tropas da França, a Sublime Porta enviou à região Fuad Paxá com poderes extraordinários; foi conduzida uma dura ação de repressão. Os acontecimentos serviram de pretexto à intervenção europeia e foram a causa direta de o Líbano obter um estatuto especial.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["O início da publicação do Tercümân-ı Ahvâl: o primeiro jornal turco privado em Istambul", "24792957"], "d": ["O Tercümân-ı Ahvâl, publicado por Agâh Efendi e cuja redação foi assumida por Şinâsi, é o primeiro jornal turco editado sem apoio do Estado. No prefácio do primeiro número defendeu-se o direito do povo de se pronunciar sobre os seus próprios assuntos, e o jornal, ao publicar em folhetim O Casamento do Poeta de Şinâsi, entreabriu também a porta da moderna literatura turca. O nascimento do conceito de opinião pública e da imprensa de oposição no Império Otomano é reportado a esta data.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["O Regulamento do Monte Líbano: estatuto de mutasarrifato privilegiado para o Líbano", "bf375603"], "d": ["O regulamento, preparado sob pressão das grandes potências após os massacres de 1860, fez do Monte Líbano um mutasarrifato privilegiado, dependente diretamente da Sublime Porta e governado por um conselho administrativo constituído segundo o equilíbrio entre as confissões. Estipulou-se que o mutasarrıf fosse um cristão católico, súbdito otomano, e que a sua nomeação fosse submetida à aprovação das grandes potências; o primeiro mutasarrıf foi Dâvud Paxá. Esta ordem duraria até 1915 e formaria o núcleo do moderno Estado libanês.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["A morte de Abdülmecid e a entronização do sultão Abdülaziz", "27204d7c"], "d": ["Quando Abdülmecid, que no seu reinado de vinte e dois anos assinara os Éditos de Tanzimat e de Reforma, sucumbiu à tuberculose, subiu ao trono o irmão Abdülaziz. O novo sultão deu esperança nos primeiros anos com medidas de poupança e uma vida simples; fez da marinha uma das poucas potências do mundo. Mas no fim do seu reinado a pesada dívida externa, a bancarrota de 1875 e as revoltas dos Balcãs acumulavam-se, preparando o terreno para a deposição de 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Os principados unidos tomam o nome de Roménia", "d960e3fc"], "d": ["A Valáquia e a Moldávia, unidas de facto desde a dupla eleição de Cuza em 1859, reuniram em 1862 as suas assembleias e governos sob um só teto em Bucareste e tomaram oficialmente o nome de Roménia. Embora o Estado Otomano conservasse juridicamente a qualidade de suserano e o tributo anual, perdeu de facto o controlo sobre o principado. O fim da influência otomana de quatro séculos a norte do Danúbio é simbolizado por esta data.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["A ligação de Suakin, Maçuá e Dahlak ao Egito", "a0924860"], "d": ["Maçuá, que em 1846 fora dada pelo sultão Abdülmecid, juntamente com Suakin, ao quediva Mehmed Ali Paxá do Egito como sâlyâne (atribuição de rendimentos), foi incorporada, no tempo do quediva İsmâil Paxá, juntamente com Dahlak e Suakin, nos domínios do Egito e organizada com o estatuto de kaymakamlık. Assim, estes três portos da costa africana do mar Vermelho, embora juridicamente continuassem território otomano, passaram administrativamente da Sublime Porta diretamente para o Cairo — entrando no mesmo estrato de dependência que o seu vizinho Egito e o Sudão.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["O início da Revolta de Creta (1866-1869)", "3679b861"], "d": ["A insurreição de grande envergadura que rebentou na ilha com o apoio aberto da Grécia converteu pela primeira vez em questão internacional a reivindicação de enosis (união com a Grécia) dos gregos de Creta. A dura guerra de montanha de três anos infligiu pesadas perdas ao exército otomano e teve grande eco na opinião pública europeia. A revolta só se extinguiu em 1868, quando Âlî Paxá foi à ilha e pôs em vigor o regulamento que concedia amplos privilégios.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["A retirada das últimas guarnições otomanas das fortalezas de Belgrado e da Sérvia", "b34217db"], "d": ["Sob a pressão das grandes potências e a insistente exigência do príncipe Mihailo, a Sublime Porta aceitou evacuar as últimas bases militares que lhe restavam na Sérvia; a 18 de abril de 1867 foi arriado o estandarte otomano na fortaleza de Belgrado e as chaves foram entregues ao príncipe. Assim terminou a presença militar otomana de facto, que durava desde 1521, e foi removido o último grande obstáculo no caminho da Sérvia para a independência. A suserania do sultão ficou reduzida apenas a uma questão simbólica de bandeira e de tributo.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["A concessão do título de quediva aos governadores do Egito", "09e10c12"], "d": ["Em resultado do intenso lóbi de İsmâil Paxá, da terceira geração da dinastia de Cavala, e do dinheiro que fez correr para Istambul, foi concedido ao governador do Egito o título de quediva, que sublinha a sua superioridade sobre os outros governadores. Nos mesmos anos, a ordem de sucessão foi também alterada para passar de pai para filho, e foram reconhecidas ao Egito competências de natureza soberana, como contrair dívidas externas, conferir medalhas e manter consulados. Estes passos são o primeiro elo da cadeia que acelerou a separação jurídica do Egito do Império Otomano.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["O Regulamento de Creta: amplos privilégios administrativos para a ilha", "12052262"], "d": ["Para pôr fim à revolta de três anos, o grão-vizir Âlî Paxá foi pessoalmente à ilha e, pelo regulamento publicado com a aprovação do sultão, foram concedidos aos cretenses conselhos administrativos mistos, tribunais locais, o uso do grego nos atos oficiais e facilidades fiscais. Esta disposição manteve de pé o domínio otomano na ilha por mais trinta anos. Mas os privilégios concedidos à população cristã enfraqueceram a posição dos cretenses muçulmanos e lançaram as sementes da crise de 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["A abertura do Şûrâ-yı Devlet: a fundação do Conselho de Estado otomano", "70b16497"], "d": ["Pela ordem imperial de 5 de março de 1868, o Meclis-i Ahkâm-ı Adliyye foi dividido em dois, ficando os assuntos administrativo-legislativos para o Şûrâ-yı Devlet e os assuntos judiciais para o Dîvân-ı Ahkâm-ı Adliyye; a instituição foi inaugurada com cerimónia na Sublime Porta e Midhat Paxá foi colocado na sua primeira presidência. Foi encarregada de preparar projetos de lei, resolver litígios administrativos e conduzir o julgamento de funcionários. Com a sua composição mista de membros muçulmanos e não muçulmanos, é considerada a primeira aplicação institucional da ideia de separação de poderes no Império Otomano.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["A abertura do Canal do Suez: o encurtamento da rota da Índia pelo Egito", "377ccd04"], "d": ["A construção, iniciada em 1859, durou dez anos, e o canal de 163 quilómetros que liga o Mediterrâneo ao mar Vermelho entrou em serviço com uma cerimónia grandiosa. Quando a rota que liga a Europa à Índia encurtou milhares de milhas, o Egito tornou-se de repente ponto-chave do comércio mundial. Este valor geoestratégico seria a principal causa da ocupação do Egito pela Inglaterra treze anos após a abertura do canal; e a dívida que o canal impôs ao Egito levaria o quediva à bancarrota.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["A fundação do Exarcado Búlgaro: a separação da igreja búlgara do Fener", "33a8272c"], "d": ["Por firmão imperial foi criada uma igreja búlgara autónoma (exarcado), separada do Patriarcado Grego, e deixou-se a um plebiscito popular decidir que distritos (kazas) ficariam ligados ao exarcado. Embora a Sublime Porta tivesse dado este passo para quebrar a influência grega, o resultado foi o inverso: a igreja converteu-se no centro organizado da identidade nacional búlgara e da pretensão búlgara sobre a Macedónia. Assim se lançou o terreno institucional da rivalidade búlgaro-greco-sérvia nos Balcãs e das revoltas de 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["A colocação de Asir sob administração direta", "4559e099"], "d": ["Quando o valor estratégico do mar Vermelho aumentou com a abertura do Canal do Suez, viu-se que as montanhas de Asir, a meio da estrada terrestre para o Iémen, não podiam ficar sem controlo. As forças de Redif Paxá, que partiram em campanha para o Iémen, entraram em Abha e ligaram a região diretamente à administração otomana, e foi criado o sanjaco de Asir. Devido à geografia montanhosa e à influência dos Idrisidas, este domínio nunca se assentou por completo.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["A campanha de Midhat Paxá a Najd: o restabelecimento do domínio otomano em Lahsa", "7db51461"], "d": ["O governador de Bagdade, Midhat Paxá, aproveitando a luta pelo trono dentro da família saudita, enviou tropas à costa ocidental do golfo Pérsico e ligou a região de Lahsa à província de Bassorá com o nome de sanjaco de Najd. Abdullah b. Faysal foi nomeado mutasarrıf, estabelecendo-se no papel o domínio otomano. A campanha tinha por objetivo deter a expansão da influência inglesa no golfo e levou, no mesmo ano, a que também o Catar entrasse sob controlo otomano.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["A morte do grão-vizir Âlî Paxá: o fim do quadro do Tanzimat", "1cf0141c"], "d": ["Com a morte de Âlî Paxá, que depois do falecimento de Fuad Paxá em 1869 carregou sozinho a política do Tanzimat, esgotou-se a geração de mestres diplomatas que durante trinta anos dirigira a política externa do Estado. O governo pró-russo e arbitrário de Mahmud Nedim Paxá, que lhe sucedeu, consolidou a governação pessoal de Abdülaziz. Nos cinco anos seguintes à morte de Âlî Paxá, as finanças faliram, os Balcãs sublevaram-se e a mudança de sultão tornou-se inevitável.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["O estabelecimento do controlo otomano no Catar", "3b453165"], "d": ["A convite do xeique Kāsım b. Sânî, que estava sob pressão inglesa, forças otomanas desembarcaram na península do Catar e, no outono de 1871, foi assegurado na região o controlo otomano. O Catar foi organizado como um kaza dependente do sanjaco de Najd e o xeique foi nomeado kaymakam. Este lance foi o ganho mais concreto da política avançada que Midhat Paxá conduzia no golfo contra a Inglaterra; a bandeira otomana tremulou na península até 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["O firmão de sucessão para Tunes — o beylik para a família de Mehmed Sâdık Paxá", "1509ebb0"], "d": ["Pelo firmão que saiu por iniciativa de Hayreddin Paxá, enviado a Istambul pelo bei de Tunes Mehmed Sâdık Paxá, que aproveitara a derrota da França perante a Prússia, Tunes foi dada a Mehmed Sâdık Paxá e aos seus descendentes por via de sucessão, continuando dependente diretamente de Istambul. Não se fariam negociações de guerra e paz sem a licença do sultão, nenhum território do país seria dado a outrem e seria satisfeito o pedido otomano de soldados. A França não reconheceu o firmão; dez anos depois ocupou Tunes.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["A tomada de Sana: o restabelecimento da autoridade otomana no Iémen", "978e20a0"], "d": ["Quando o valor estratégico do mar Vermelho aumentou com a abertura do Canal do Suez, a Sublime Porta enviou ao Iémen o exército da fırka-i ihtiyâtiyye sob o comando de Ahmed Muhtar Paxá. Com a tomada de Sana, foi restabelecida a autoridade do Estado no Iémen interior, de facto perdido havia dois séculos, e a região foi convertida em província. Mas a luta contra os imames zaiditas nunca terminou; as revoltas de 1891, 1898 e 1904 constituíram a frente interna mais cara e mais longa dos otomanos. Outros lugares que passaram na mesma data: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["O início da Revolta da Herzegovina: o reacender da Questão do Oriente", "571b18ec"], "d": ["A revolta dos camponeses cristãos em redor de Nevesinje, devida aos impostos pesados e à pressão dos âyan, propagou-se depressa a toda a Herzegovina e foi alimentada por voluntários vindos da Sérvia e de Montenegro. A revolta, que levou a Áustria e a Rússia a impor reformas, desencadeou no ano seguinte as insurreições búlgaras e as declarações de guerra da Sérvia e de Montenegro. Assim se quebrou o primeiro elo da grande cadeia que conduziu à Guerra de 93 e à perda dos Balcãs pelo Tratado de Berlim.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["A bancarrota das finanças otomanas: a redução a metade dos pagamentos da dívida externa", "2cac2fa5"], "d": ["Os empréstimos contraídos sucessivamente desde 1854, as despesas da Guerra da Crimeia, as construções de palácios e a fome de 1873-74 na Anatólia transformaram o défice orçamental num abismo superior a cinco milhões de liras. O governo de Mahmud Nedim Paxá declarou de facto uma moratória, anunciando que os pagamentos de juros e de capital da dívida seriam reduzidos a metade por cinco anos. Esta decisão, que suscitou grande reação nas bolsas europeias, iniciou o processo que, seis anos depois, resultaria no Decreto de Muharrem e na criação da Administração da Dívida Pública.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["A deposição de Murad V e a entronização de Abdülhamid II", "cffb2271"], "d": ["Murad V, que subiu ao trono depois da deposição de Abdülaziz, tornou-se incapaz de exercer funções devido à sua saúde mental, abalada pela morte do tio e pelo Incidente de Çerkes Hasan; apenas em sete dias do seu reinado de noventa e três dias teve o juízo em ordem. Foi deposto por fetva do xeique do Islão (şeyhülislam) e em seu lugar foi posto o irmão Abdülhamid II. O novo sultão subiu ao trono depois de prometer a Midhat Paxá que proclamaria o regime constitucional; começava uma época que duraria trinta e três anos.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["A Conferência do Arsenal: a imposição das grandes potências sobre a reforma nos Balcãs", "b5006a2c"], "d": ["A conferência que as grandes potências reuniram em Istambul para resolver a crise dos Balcãs exigiu a divisão da Bulgária em duas províncias autónomas e a aplicação de reformas sob controlo internacional na Bósnia-Herzegovina. A Sublime Porta, no dia da abertura da conferência, anunciou com salvas de canhão a proclamação do Kanûn-ı Esâsî, procurando responder às imposições com uma reforma constitucional. Os delegados, considerando-o uma manobra dilatória, dispersaram-se a 20 de janeiro de 1877; quatro meses depois, a Rússia declarou guerra.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["A abertura da primeira Assembleia dos Deputados em Dolmabahçe", "429bb279"], "d": ["Os 115 deputados eleitos nos termos do Kanûn-ı Esâsî reuniram-se pela primeira vez a 19 de março de 1877, numa cerimónia no Salão de Cerimónias do Palácio de Dolmabahçe; assim começou, na história otomana, o período da assembleia representativa. Os deputados muçulmanos e não muçulmanos interrogaram o governo com dureza e discutiram a condução da guerra e a responsabilidade dos ministros. Esta oposição corajosa seria a principal causa do encurtamento da vida da assembleia.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["O início da defesa de Plevna: a resistência de Gazi Osman Paxá", "0e04a878"], "d": ["Osman Paxá, que marchou de Vidin a Plevna para cortar o caminho de Istambul ao exército russo que atravessara o Danúbio na Guerra de 93, fortificou a vila com redutos e trincheiras e iniciou uma lendária defesa de cinco meses. Três grandes ataques russo-romenos sucessivos foram repelidos com pesadas perdas, e o exército, dirigido pessoalmente pelo czar Alexandre II, foi obrigado a pôr cerco. Plevna ficou na história como o mais brilhante êxito defensivo do exército otomano no século XIX.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["A queda de Plevna: o colapso da frente do Danúbio", "185e7602"], "d": ["Osman Paxá, a quem se esgotaram os mantimentos no cerco de cinco meses, lançou uma operação de rutura pelo rio Vid; ao ser ferido e feito prisioneiro, a cidade rendeu-se. Os comandantes russos saudaram o paxá capturado devolvendo-lhe a espada, e a Osman Paxá foi dado o título de 'Gazi'. Com a queda de Plevna abriu-se o caminho ao exército russo; em dois meses caíram Sófia, Filipópolis e Edirne, e as vanguardas russas chegaram a Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["A ocupação de Sófia pelas forças russas", "ef369d22"], "d": ["O exército russo, que transpusera os Balcãs depois da queda de Plevna, entrou em Sófia, que ficara indefesa. A cidade não voltaria à administração otomana, e seria no fim de 1878 a capital do Principado autónomo da Bulgária, e de facto em 1879. No mapa, Sófia passa, a partir desta data, da administração direta otomana para a ocupação russa provisória e, em seguida, para o governo búlgaro autónomo.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["O Armistício de Edirne: o silêncio das armas na Guerra de 93", "1f899180"], "d": ["Com a queda sucessiva de Sófia, Filipópolis e Edirne e com o exército russo chegado às costas do Mármara, a Sublime Porta foi obrigada a pedir um armistício. O cessar-fogo assinado em Edirne fez os otomanos aceitar condições preliminares de paz como a autonomia da Bulgária, a independência de Montenegro, da Sérvia e da Roménia e uma pesada indemnização de guerra. Estas condições converter-se-iam, um mês depois, em texto de tratado em Santo Estêvão.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["A suspensão por tempo indeterminado da Assembleia dos Deputados por Abdülhamid II", "e770b540"], "d": ["Perante as duras críticas dos deputados, que responsabilizavam o governo e o palácio pelo desfecho catastrófico da guerra, Abdülhamid II, apoiando-se no poder que o Kanûn-ı Esâsî lhe conferia, suspendeu a assembleia por tempo indeterminado. O primeiro parlamento otomano, que funcionara cerca de onze meses, encerrou-se assim e começou a época de despotismo que duraria trinta anos. A assembleia só voltaria a reunir-se depois da Revolução de 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["O Tratado de Santo Estêvão: o projeto da Grande Bulgária", "2c7cc611"], "d": ["O Tratado de Santo Estêvão, que pôs fim à Guerra de 93, criava uma enorme Bulgária autónoma que se estendia até ao Egeu e englobava a Macedónia; reconhecia a independência da Sérvia, de Montenegro e da Roménia; cedia à Rússia Kars, Ardahan, Batum e Doğubayazıt, e impunha ainda uma indemnização de guerra impossível de pagar. Este texto, que fazia descer a Rússia ao Mediterrâneo, suscitou a violenta reação da Inglaterra e da Áustria. Foi reordenado, sem ter sido aplicado, em quatro meses, pelo Congresso de Berlim; ainda assim, ficou como o documento que proclamou o fim da Rumélia otomana.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan e Batum foram cedidas à Rússia — elviye-i selâse", "99bdfad2"], "d": ["Pelo Tratado de Berlim, o Estado Otomano cedeu Kars, Ardahan e Batum à Rússia em contrapartida de uma parte da indemnização de guerra; Doğubayazıt e o vale de Eleşkirt, dados à Rússia em Santo Estêvão, ficaram com os otomanos. Embora Batum tenha sido dada como porto franco, só conservou esse estatuto até 1886. Os russos fizeram de Kars uma província dependente do governo-geral da Transcaucásia, com centro em Tbilisi; da elviye-i selâse, uma população que chegava a 100.000 pessoas foi obrigada a emigrar para o lado de Erzurum.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["A ocupação da Bósnia-Herzegovina e de Novi Pazar pela Áustria-Hungria", "e5f901df"], "d": ["Apoiando-se na autorização dada pelo Tratado de Berlim, os exércitos austro-húngaros entraram na Bósnia; embora o governo otomano tivesse aceitado não resistir, a população local muçulmana e ortodoxa de Sarajevo e Mostar pegou em armas e ofereceu durante três meses uma resistência dura. A ocupação só pôde ser concluída a 20 de outubro de 1878. A soberania jurídica do sultão subsistiu no papel até 1908, mas a Bósnia otomana de quatro séculos perdeu-se de facto e começou uma grande vaga de emigração muçulmana. Outros povoamentos perdidos na mesma data: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["O Decreto de Muharrem e a fundação da Administração da Dívida Pública", "02b7cc03"], "d": ["As negociações conduzidas com os representantes dos Estados credores depois da bancarrota de 1875 resultaram no decreto de 28 de Muharrem de 1299 (20 de dezembro de 1881): o capital da dívida foi reduzido em mais de metade e, em contrapartida, as rubricas de receita mais produtivas, como as taxas do sal, do tabaco, da seda, do selo e do peixe, foram transferidas para a Administração da Dívida Pública, dirigida diretamente pelos credores. Esta administração, que empregava milhares de funcionários, converteu-se numa organização financeira separada dentro do Estado. É considerada a data em que terminou de facto a independência financeira otomana.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — o único porto que não caiu perante o Mahdi", "5a37b198"], "d": ["Enquanto, a partir de fevereiro de 1884, todas as regiões do Sudão oriental, exceto Suakin, passavam para o domínio de Muhammed Ahmed al-Mahdi, o porto manteve-se de pé com a proteção militar de uma força inglesa de três batalhões comandada pelo general Graham. Foi o início de um período em que se separaram a situação de facto e a de direito: embora a costa estivesse de facto sob controlo militar inglês, o seu vínculo administrativo seria retirado ao Egito em 1885 e ligado diretamente à província do Iémen, isto é, à Sublime Porta — essa ordem durou até 1888, quando terminou com a ocupação de Zeila pela França.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["A morte de Midhat Paxá na masmorra de Taif", "f4562261"], "d": ["Midhat Paxá, arquiteto do Kanûn-ı Esâsî e nome emblemático da Primeira Monarquia Constitucional, fora considerado culpado no Tribunal de Yıldız a propósito da morte de Abdülaziz e, comutada a pena de morte em exílio, fora enviado a Taif. Segundo o registo da TDV, na noite de 7 para 8 de maio de 1884 foi estrangulado na sua cela, e a causa oficial foi declarada como a doença 'şîrpençe'. A sua morte tornou-se, no tempo de Abdülhamid II, o símbolo da liquidação da oposição constitucional.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["A concessão da via-férrea Haydarpaşa-Ancara aos alemães", "5705b163"], "d": ["Por ordem do sultão, a concessão de construção e exploração da linha Haydarpaşa-Ancara foi dada ao banqueiro Alfred von Kaulla, representante do Deutsche Bank, e foi fundada a Companhia da Via-Férrea da Anatólia. Esta concessão foi o ponto de viragem que quebrou o monopólio anglo-francês nos transportes e na política externa otomanos e implantou a influência alemã. Juntamente com a concessão da linha de Bagdade, a atribuir à mesma companhia onze anos depois, nasceria o sonho 'Berlim-Bagdade', que se tornaria um dos principais eixos da rivalidade das grandes potências antes da Primeira Guerra Mundial.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["A fundação em Istambul da Sociedade de União Otomana", "b7187939"], "d": ["Quatro alunos da Escola Médica Militar fundaram, como organização secreta contra o governo despótico, a Sociedade de União Otomana; esta estrutura transformou-se em pouco tempo no Comité de União e Progresso, que reuniria sob o seu teto todos os elementos de oposição do movimento dos Jovens Turcos. A organização, baseada em células, juntou-se aos exilados na Europa e aos oficiais de Salónica. O quadro que faria proclamar a Segunda Monarquia Constitucional em 1908 e que governaria o Estado sozinho depois de 1913 saiu desta pequena célula de estudantes.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["O Assalto ao Banco Otomano: a ação dos militantes dashnaks em Galata", "08b3095f"], "d": ["Um grupo armado da organização arménia Dashnaktsutyun, com o fim de chamar a atenção da Europa para a questão arménia, assaltou a sede do Banco Otomano em Galata, tomou reféns e ameaçou fazer explodir o edifício. A crise terminou com a intervenção dos embaixadores, em troca de os militantes serem retirados do país num navio. Os sangrentos acontecimentos ocorridos em Istambul nos dias seguintes ao assalto foram decisivos para que a questão arménia se convertesse numa alavanca de intervenção internacional.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["O início da Guerra Otomano-Grega de 1897: a frente da Tessália", "33e490ab"], "d": ["Perante o desembarque de frota e tropas gregas em Creta e os ataques de bandos na fronteira da Rumélia, o Estado Otomano declarou guerra. O exército otomano, instruído pela missão de reforma alemã, avançou depressa na Tessália e em um mês tomou Yenişehir, Çatalca e Dömeke; o exército grego dispersou-se. Com a intervenção das grandes potências, os territórios conquistados foram devolvidos, mas a guerra ficou como a única vitória militar decisiva do tempo de Abdülhamid II e não impediu a perda de facto de Creta.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["A concessão da linha Konya-Bagdade aos alemães", "fd8b6cbd"], "d": ["Depois da visita do kaiser Guilherme II a Istambul e a Damasco em 1898, foi dada à Companhia da Via-Férrea da Anatólia a concessão preliminar da linha que se estenderia de Konya a Bagdade e a Bassorá. O projeto da Via-Férrea de Bagdade significava, para os otomanos, reforçar o controlo central sobre as províncias árabes e, para a Alemanha, chegar ao golfo Pérsico. Este projeto, a que a Inglaterra e a Rússia se opuseram com violência, tornou-se um dos dossiês mais controversos da rivalidade imperialista que conduziu à Primeira Guerra Mundial.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["O início da construção da Via-Férrea do Hejaz em Damasco", "62f58f68"], "d": ["A linha ordenada por Abdülhamid II por ordem imperial de 2 de maio de 1900 viu iniciar-se a construção a 1 de setembro de 1900, numa cerimónia oficial realizada em Damasco. O projeto, feito inteiramente com donativos recolhidos em todo o mundo islâmico e com o trabalho de engenheiros e soldados otomanos, reduziu de quarenta para cinco dias a viagem dos peregrinos entre Damasco e Medina. Era ao mesmo tempo uma obra de prestígio que consolidava a autoridade espiritual do califado e um investimento estratégico que reforçava o controlo militar sobre o Hejaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["O Programa de Mürzsteg: controlo internacional de reformas na Macedónia", "4c7464da"], "d": ["Depois da insurreição de Ilinden, os imperadores russo e austríaco encontraram-se em Mürzsteg e prepararam um novo pacote de reformas para a Macedónia. O programa previa a colocação de dois agentes civis estrangeiros junto do inspetor-geral otomano, a reorganização da gendarmaria por oficiais europeus e a alteração das fronteiras administrativas segundo o critério da nacionalidade. Embora a Sublime Porta tenha resistido, alegando lesão dos seus direitos de soberania, foi obrigada a aceitar perante a pressão conjunta; o programa foi um dos fatores fundamentais que aceleraram a organização unionista entre os jovens oficiais.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["A morte de Murad V", "396659a7"], "d": ["Murad V, que em 1876 ficou cerca de três meses no trono e foi deposto, depois das tentativas de o repor no trono viveu vinte e oito anos preso sob apertada vigilância e morreu de diabetes. Foi sepultado ao lado da mãe no Mausoléu de Cedîd Havâtîn, na Yenicami. Ficou na história como o sultão otomano que menos tempo esteve no trono.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["A perda de Sana para o imame Yahyâ", "e7f876cb"], "d": ["A insurreição iniciada em 1904 pelo imame zaidita Yahyâ Hamîdüddin resultou, em abril de 1905, na queda de Sana no fim de um cerco; a cidade saiu da administração otomana e, durante o cerco, surgiram a fome e a epidemia. A geografia montanhosa do Iémen, o comprimento das linhas de abastecimento e a legitimidade local do imamato zaidita tornavam frágil o domínio otomano ali desde a sua fundação. A cidade seria retomada cinco meses depois a custo de pesadas perdas, mas a questão do Iémen não se encerraria até 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["O Atentado de Yıldız: ataque à bomba contra Abdülhamid II", "1ee2e1a6"], "d": ["A organização Dashnaktsutyun perpetrou o atentado fazendo explodir uma caleche com bomba de relógio junto à carruagem do sultão, que saía da cerimónia de sexta-feira (selâmlık); o atraso de alguns minutos de Abdülhamid, que conversava com o xeique do Islão (şeyhülislam), salvou-lhe a vida. Na explosão morreram vinte e seis pessoas e mais de cinquenta ficaram feridas. O caso endureceu ainda mais a obsessão de segurança do sultão e o seu governo despótico, baseado na organização de espiões; foi também tema do poema 'Bir Lahza-i Taahhur' de Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["A reconquista de Sana: a repressão da revolta do imame Yahyâ", "dec3b8f9"], "d": ["A insurreição iniciada em 1904 sob a liderança do imame zaidita Yahyâ resultou, em abril de 1905, na queda de Sana, e na cidade surgiram a fome e a epidemia. Os exércitos de reforço comandados por Ali Rızâ Paxá e Ahmed Feyzi Paxá, numa operação conduzida entre 15 de julho e 1 de setembro de 1905 e apoiada também pelas forças de Taiz, retomaram a cidade a custo de pesadas perdas e a revolta foi reprimida. A campanha do Iémen trouxe ao exército otomano dezenas de milhares de baixas e um encargo financeiro enorme; entre os oficiais da Rumélia, o medo do 'exílio no Iémen' estava entre as queixas que alimentavam a organização unionista.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["A reunião da primeira Assembleia dos Deputados da Segunda Monarquia Constitucional", "e7fd2716"], "d": ["A assembleia formada pelas eleições em dois graus, realizadas após uma interrupção de trinta anos, foi aberta a 17 de dezembro de 1908 com o discurso do sultão, e para a sua presidência foi eleito Ahmed Rızâ Bey, líder do movimento dos Jovens Turcos. Composta por deputados turcos, árabes, albaneses, gregos, arménios e judeus, a assembleia foi a última grande tentativa do ideal otomanista. Mas a independência da Bulgária, a anexação da Bósnia e a proclamação da união de Creta à Grécia tinham ofuscado esse otimismo antes mesmo de a assembleia abrir.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["O Exército de Ação e a deposição de Abdülhamid II: a entronização de Mehmed V Reşad", "6a65a704"], "d": ["O Exército de Ação, que partiu de Salónica por causa do Incidente de 31 de Março, entrou em Istambul por quatro colunas na noite de 22 para 23 de abril e a 24 de abril o Palácio de Yıldız rendeu-se. A Assembleia Nacional Geral decidiu a 27 de abril a deposição de Abdülhamid II; o sultão foi enviado para Salónica e em seu lugar foi entronizado o irmão Mehmed V Reşad. O governo pessoal de trinta e três anos terminou assim, mas foi substituído por um novo período em que o sultão se tornara um símbolo e em que o Comité de União e Progresso governava com o apoio do exército.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["A Revolta da Albânia: resistência armada em Kosovo e Shkodër", "93ed30c6"], "d": ["A política fiscal centralista do governo unionista, a campanha de recolha de armas e a polémica sobre o alfabeto latino sublevaram as tribos albanesas, até então consideradas dos elementos mais fiéis ao Estado. Embora o exército comandado por Mahmud Şevket Paxá tenha reprimido a revolta com dureza, a agitação reacendeu-se em 1911 e 1912. Estas revoltas desgastaram o exército otomano às vésperas da Guerra dos Balcãs e aceleraram também o nascimento do movimento nacional albanês.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["O Tratado de Ouchy: a cedência de Trípoli de Barbaria e Benghazi à Itália", "4ffa1fd2"], "d": ["A Sublime Porta, que não podia arriscar um conflito em duas frentes perante os preparativos de guerra dos Estados balcânicos, assinou com a Itália uma paz secreta na localidade suíça de Ouchy e cedeu Trípoli de Barbaria e Benghazi. O Estado Otomano perdeu assim o seu último território em África; em contrapartida, foi prometida a devolução de Rodes e do Dodecaneso ocupados pela Itália, mas essa promessa nunca foi cumprida. Quando o tratado foi assinado, a Guerra dos Balcãs já tinha começado.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["A ocupação de Lemnos pela Grécia", "9555af1d"], "d": ["Na Primeira Guerra dos Balcãs, a frota grega ocupou Lemnos; o porto de Mudros da ilha tornou-se base para o bloqueio do estreito de Çanakkale. A ilha foi deixada à Grécia em Lausana (24 de julho de 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["A ocupação de Taso pela Grécia", "6c03c7f0"], "d": ["Na Primeira Guerra dos Balcãs, a Grécia ocupou Taso e Samotrácia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["A ocupação de Samotrácia pela Grécia", "911e82a3"], "d": ["Na Primeira Guerra dos Balcãs, a Grécia ocupou Samotrácia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["A ocupação de Lesbos pela Grécia", "6b2b07ba"], "d": ["A frota grega desembarcou em Lesbos; a ilha foi tomada pelo exército e pela frota gregos no fim da Primeira Guerra dos Balcãs. A Conferência de Londres (maio de 1913) confirmou a situação.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["O desembarque grego em Quios", "901c6539"], "d": ["Os gregos desembarcaram em Quios, bombardeada a 7 de abril de 1912 na Primeira Guerra dos Balcãs; a guarnição otomana rendeu-se a 3 de janeiro de 1913. A ilha foi deixada à Grécia pelo Tratado de Lausana (24 de julho de 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["O assassinato do grão-vizir Mahmud Şevket Paxá em Istambul", "68e60e63"], "d": ["Mahmud Şevket Paxá, nomeado grão-vizir depois do Assalto à Sublime Porta, foi morto a tiro disparado contra a sua carruagem junto a Çarşıkapı quando se dirigia ao Ministério da Guerra. O Comité de União e Progresso, imputando o atentado à oposição, desencadeou uma vasta vaga de detenções e execuções, e o Partido da Liberdade e Entente foi liquidado de facto. Com este caso, ficou definitivamente estabelecida a ditadura de partido único dos unionistas, assente no triunvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["O início da Segunda Guerra dos Balcãs: a disputa da partilha entre os aliados", "48d088a2"], "d": ["Os aliados balcânicos, que não conseguiram repartir os territórios tomados aos otomanos pelo Tratado de Londres, caíram uns contra os outros; a segunda guerra começou com o ataque da Bulgária às posições sérvias e gregas. Quando a Roménia e Montenegro entraram também na frente contra a Bulgária, o exército búlgaro ruiu. O Estado Otomano, aproveitando esta oportunidade, ultrapassou a linha Midye-Enez traçada pelo Tratado de Londres e recuperou a Trácia Oriental juntamente com Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["O Tratado de Istambul: paz com a Bulgária e o registo de Edirne", "c8c18b2d"], "d": ["O tratado assinado entre o Estado Otomano e a Bulgária depois da Segunda Guerra dos Balcãs, aceitando o rio Maritsa como fronteira, registou juridicamente que Edirne, Kırklareli, Dimotika e a Trácia Oriental ficavam com os otomanos. Dedeağaç ficou na Bulgária (Kavala, por sua vez, passara para a Grécia em julho de 1913, depois da ocupação búlgara do outono de 1912, e fora registada na Grécia pelo Tratado de Bucareste de 10 de agosto de 1913); regulou-se a troca recíproca de populações entre os dois países e os direitos dos muçulmanos na Bulgária. A garantia do único pedaço de território que pôde ser recuperado do desastre dos Balcãs é este texto. Outros lugares que passaram na mesma data: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["A recuperação de Tenedos e Imbros — Tratado de Atenas", "ec084d09"], "d": ["De entre as ilhas do Egeu Norte ocupadas pela Grécia na Guerra dos Balcãs, Tenedos e Imbros, que guardam a entrada do Estreito, foram consideradas indispensáveis à defesa de Çanakkale nas negociações do Tratado de Atenas e foram devolvidas aos otomanos. As outras ilhas ficaram com a Grécia. Estas duas ilhas foram os últimos territórios que o império conservou no Egeu e foram também deixadas à Turquia em Lausana.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["O Tratado de Atenas: paz com a Grécia e a cedência de Salónica e Ioannina", "8e94def7"], "d": ["O tratado assinado entre o Estado Otomano e a Grécia reconheceu oficialmente a passagem para a Grécia de Salónica, Ioannina e da Macedónia do Sul, perdidas na Guerra dos Balcãs, e renunciou-se aos direitos otomanos sobre Creta. Regularam-se em pormenor os direitos de religião e de propriedade dos muçulmanos que ficavam na Grécia, o estatuto dos vakıfs e a nomeação dos mufties. O estatuto das ilhas do Egeu, esse, foi deixado sem solução, permanecendo como fonte de tensão contínua entre os dois Estados.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["A assinatura em Istambul do tratado secreto de aliança otomano-alemão", "0472efb3"], "d": ["Logo que rebentou a guerra na Europa, foi assinado, na mansão do grão-vizir Said Halim Paxá, um tratado secreto de aliança entre o Estado Otomano e a Alemanha; o texto previa que, no caso de a Rússia entrar em guerra contra a Alemanha, os otomanos ficassem também ao lado da Alemanha. O tratado foi escondido até do gabinete, sendo conhecido apenas por quatro pessoas. Três meses depois, com o Assalto ao Mar Negro, o Estado Otomano seria de facto arrastado para a guerra, e o destino do império ficaria atado a este documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["A abolição unilateral das capitulações", "ec773d18"], "d": ["O governo otomano, num momento em que a Europa estava ocupada com a guerra, declarou que abolia unilateralmente, a partir de 1 de outubro de 1914, as capitulações, que concediam aos estrangeiros privilégios judiciais, financeiros e aduaneiros. O fim desta ordem de privilégios de quatro séculos foi recebido no país com grande entusiasmo de independência e fizeram-se celebrações em Istambul. Todos os Estados, incluindo a aliada Alemanha, protestaram contra a decisão; as capitulações só passariam definitivamente à história em Lausana, em 1923.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["O Assalto ao Mar Negro: o bombardeamento de portos russos pela marinha otomana", "8ad4ef61"], "d": ["O Goeben e o Breslau (Yavuz e Midilli), que tinham fugido da Alemanha e se juntaram à marinha otomana como se tivessem sido 'comprados', saíram para o mar Negro sob o comando do almirante Souchon, bombardearam portos russos e afundaram navios. Esta ordem, dada por Enver Paxá às escondidas do gabinete, pôs fim de facto à neutralidade. Em uma semana, a Rússia, a Inglaterra e a França declararam guerra, e o Estado Otomano entrou de modo irreversível na Primeira Guerra Mundial.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["A tomada de Fao pelas forças anglo-indianas — a abertura da frente do Iraque", "08663813"], "d": ["Na manhã seguinte ao dia em que as potências da Entente declararam guerra ao Estado Otomano, a brigada anglo-indiana que aguardava no Bahrein desembarcou em Fao, na foz do Shatt al-Arab. A pequena unidade otomana da arruinada fortaleza de Fao retirou-se sob o fogo dos navios de guerra e a estação da linha telegráfica da Índia caiu nas mãos dos ingleses. A frente do Iraque ficou assim aberta.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["A proclamação da Jihad Maior: a leitura da fetva de jihad na Mesquita de Fatih", "2a6174e8"], "d": ["As cinco fetvas dadas pelo xeique do Islão Ürgüplü Hayri Efendi foram lidas na Mesquita de Fatih em nome do califa-sultão, convocando todos os muçulmanos para a jihad contra as potências da Entente. Este lance, em que a Alemanha depositava grandes esperanças, visava sublevar os muçulmanos das colónias inglesas e francesas. A esperada insurreição geral não se produziu; pelo contrário, a revolta, dois anos depois, do emir de Meca, o xarife Hussein, com apoio inglês, mostrou de forma amarga os limites da influência política do califado.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["A rendição de Kürne aos ingleses", "621d36b0"], "d": ["As forças do governador de Bassorá, Subhi Bey, que se tinham retirado, após a queda de Bassorá, para Kürne, onde se juntam o Tigre e o Eufrates, renderam-se na manhã de 9 de dezembro de 1914, depois dos combates de 4 a 8 de dezembro.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["A colocação do Egito sob protetorado inglês e a proclamação do sultanato", "55d4e520"], "d": ["Com a entrada do Estado Otomano na guerra, a Inglaterra declarou que colocava oficialmente sob o seu protetorado o Egito, que mantinha de facto ocupado desde 1882; o quediva Abbas Hilmi Paxá, que continuava ligado aos otomanos, foi deposto e em seu lugar foi posto Hüseyin Kâmil com o título de 'sultão'. Assim, a soberania jurídica otomana, que durava desde 1517, foi posta termo unilateralmente. A Sublime Porta não reconheceu a decisão e dois meses depois tentou recuperar o Egito com a Operação do Canal.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["A Operação de Sarıkamış: catástrofe na frente do Cáucaso", "5cbde7f0"], "d": ["Enver Paxá, com o fim de recuperar Kars-Ardahan-Batum, perdidas em 1878, e de sublevar os turcos do Cáucaso, lançou o III Exército, em pleno inverno, por cima das montanhas de Allahuekber, numa manobra destinada a envolver as forças russas. Devido ao equipamento de inverno insuficiente, ao abastecimento esgotado e a tempestades de neve que chegaram a trinta graus negativos, o exército derreteu antes de entrar em combate; dezenas de milhares de soldados morreram de frio. A operação foi uma das mais pesadas catástrofes otomanas na guerra e deixou a frente oriental indefesa durante dois anos.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["A Primeira Operação do Canal: ataque ao Suez através do deserto do Sinai", "02dd72f5"], "d": ["Cemal Paxá, comandante do IV Exército, organizou uma ofensiva através do deserto do Sinai com o fim de libertar o Egito da ocupação inglesa e de encerrar à navegação o Canal do Suez. Embora as tropas otomanas tenham alcançado a margem oriental do canal e algumas conseguido atravessá-lo, recuaram perante a superioridade inglesa e por não se ter produzido a esperada insurreição popular egípcia. A operação não atingiu o seu objetivo, mas criou um efeito estratégico indireto ao obrigar a Inglaterra a manter uma grande força no Egito.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["A promulgação da Lei de Deslocação e Reassentamento (Tehcir)", "2f2bc22c"], "d": ["Após a revolta de Van e o avanço russo, o governo promulgou a lei temporária que permitia aos comandantes do exército transferir para outras regiões a população considerada perturbadora da segurança na retaguarda da frente, e o sultão sancionou-a a 27 de maio de 1915. Em resultado da aplicação, a maior parte da população arménia das províncias orientais e meridionais da Anatólia foi deslocada na direção da Síria e de Mossul; durante o transporte houve perdas de vidas muito grandes, devido a doenças, fome e ataques. A decisão continua a ser a questão mais pesada e, ainda hoje, mais controversa dos últimos anos do Império Otomano.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["As tropas otomanas retomaram Muş à ocupação russa", "fb1be113"], "d": ["Seis meses depois da primeira ocupação russa de Muş, o XVI Corpo otomano entrou na vila no contra-ataque de Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş passou de novo para as mãos russas", "43ad8a03"], "d": ["Com o contra-ataque russo, o destacamento otomano evacuou Muş; a vila voltou à ocupação russa entre 22 e 25 de agosto de 1916 e permaneceu em suas mãos até à primavera de 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş foi libertada definitivamente da ocupação russa", "f0e89703"], "d": ["Muş, que caíra sob ocupação russa na Primeira Guerra Mundial, foi definitivamente retomada pelas forças otomanas a 1 de maio de 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["A morte de Abdülhamid II no Palácio de Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, deposto em 1909 e levado primeiro para Salónica e, com a perda da cidade na Guerra dos Balcãs, para Istambul, onde era mantido em prisão domiciliária no Palácio de Beylerbeyi, faleceu. Durante o seu reinado de trinta e três anos procurara ganhar tempo mantendo o Estado afastado das guerras, mas ficara também associado ao governo despótico. O seu funeral, com grande multidão, foi sepultado no Mausoléu de Mahmud I, em Divanyolu; a sua morte coincidiu com um ano de guerra em que a ordem que fundara já fora há muito liquidada.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["O Tratado de Brest-Litovsk: a recuperação de Kars, Ardahan e Batum", "da82636f"], "d": ["O tratado assinado entre a Rússia, que se retirara da guerra após a revolução bolchevique, e as potências da Aliança, encerrou a frente oriental e devolveu ao Estado Otomano Kars, Ardahan e Batum (Elviye-i Selâse), que perdera pelo Tratado de Berlim de 1878. Foi o único ganho territorial obtido na história otomana depois de quarenta anos. Mas, depois do Armistício de Mudros, a região voltaria a perder-se, e a solução definitiva viria com o Tratado de Kars de 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["As tropas otomanas entraram em Artvin", "ca7d1778"], "d": ["As tropas otomanas, que a 25 de março transpuseram a fronteira de 1914, marcharam sobre o Elviye-i Selâse, cuja fronteira anterior a 1878 Brest-Litovsk restituíra, e entraram em Artvin a 28 de março de 1918. Artvin fora cedida à Rússia em 1878 como parte do sanjaco de Batum; o artigo Artvin da TDV escreve o regresso apenas como 'março de 1918', e o dia é dado por Sarı.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan caiu nas mãos do exército turco", "7fd9e3db"], "d": ["Na operação do Elviye-i Selâse, o exército otomano tomou Ardahan a 3 de abril de 1918, depois de Artvin; Ardahan caíra em 1877, na Guerra de Noventa e Três, e fora cedida à Rússia em 1878. Kars seria tomada um mês depois, a 25 de abril.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["A recuperação de Batum", "d37a1a0d"], "d": ["O exército otomano que avançou para leste depois da retirada da Rússia da guerra, pelo Tratado de Brest-Litovsk, recuperou quarenta anos depois o porto de Batum, perdido em 1878. Este porto, no extremo oriental do mar Negro, era a saída marítima do petróleo de Baku. O ganho durou apenas sete meses; depois do Armistício de Mudros, a região seria evacuada.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars entrou na administração otomana", "02cbf0b3"], "d": ["Em Brest-Litovsk fora decidida a devolução dos três sanjacos perdidos pelo Tratado de Berlim de 1878 — Kars, Ardahan e Batum; o exército otomano entrou em Ardahan a 3 de abril, em Batum a 14 de abril e em Kars a 25 de abril de 1918, e a administração foi estabelecida de facto. Estas terras, conhecidas pelo nome de 'Elviye-i Selâse', foram consideradas a compensação da perda que durava desde a Guerra de Noventa e Três. Seriam perdidas de novo depois do armistício e só ficariam definitivamente ligadas à Turquia pelo Tratado de Kars de 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır foi tomada — o avanço no vale do Aras", "87ebf4d3"], "d": ["No quadro da ofensiva iniciada em fevereiro de 1918, as tropas turcas derrotaram as unidades arménias em Sardarabad, a norte do Aras, e tomaram Iğdır a 20 de maio de 1918. Iğdır não estava incluída no Elviye-i Selâse, mas era o distrito de Sürmeli da província de Erevan; cerca de 180 anos depois, estabeleceu-se na região a primeira administração otomana.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["A morte de Mehmed V Reşad e a entronização de Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, cujo reinado de nove anos decorreu entre as guerras da Trípoli de Barbaria, dos Balcãs e Mundial, faleceu no período mais crítico da guerra e em seu lugar subiu ao trono o irmão Vahdeddin, com o nome de Mehmed VI. O novo sultão procurou libertar-se da tutela do quadro unionista; quatro meses depois, quando se assinou o armistício, teria de conduzir a liquidação do império. Foi o trigésimo sexto e último sultão da dinastia otomana.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["A chegada da frota da Entente diante de Istambul e a ocupação de facto da cidade", "d10cb14d"], "d": ["Depois do Armistício de Mudros, uma frota aliada de mais de sessenta unidades, composta por navios ingleses, franceses, italianos e gregos, fundeou diante de Dolmabahçe e Istambul passou de facto à ocupação. Quatrocentos e sessenta e cinco anos depois, a capital passava pela primeira vez ao controlo de soldados estrangeiros. A frase 'Assim como vieram, irão embora', que se diz ter sido pronunciada no mesmo dia por Mustafa Kemal Paxá ao desembarcar em Haydarpaşa e ver o panorama, seria uma das frases emblemáticas da Luta Nacional.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["A retirada na região do Aras: Iğdır foi evacuada", "57572ab4"], "d": ["Em conformidade com a disposição do Armistício de Mudros sobre a retirada para trás da fronteira de 1914, Yakup Şevki Paxá, por ordem de 21 de novembro, mandou recolher até 4 de dezembro as unidades que estavam fora da fronteira de Brest-Litovsk; Iğdır e os arredores foram por completo evacuados nesta data. Em seguida, o Governo Turco do Aras foi derrubado pelos arménios no final de dezembro de 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Os ingleses instalaram-se em Artvin", "e2cb3153"], "d": ["Como o Armistício de Mudros, de 30 de outubro de 1918, estipulava a retirada do exército otomano para trás da fronteira de 1914, Artvin foi evacuada e, a 17 de dezembro de 1918, ocupada pelos ingleses. Segundo o artigo Artvin da TDV, a ocupação inglesa durou até abril de 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["A administração britânica em Batum depois de Mudros", "9dd768fc"], "d": ["Em virtude do Armistício de Mudros de 30 de outubro de 1918, o Estado Otomano foi obrigado a retirar-se de Batum; a cidade foi ocupada por unidades britânicas a 24 de dezembro de 1918. Batum, feita em abril de 1918 centro de sanjaco autónomo, permaneceu desta data até julho de 1920 sob controlo inglês.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan passou ao domínio georgiano", "97cf47f6"], "d": ["Ardahan, evacuada após Mudros, foi ocupada pelas forças georgianas a 20 de abril de 1919, nos dias em que o Governo do Sudoeste do Cáucaso foi dissolvido pelos ingleses. O domínio georgiano duraria até 23 de fevereiro de 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston entregou a administração de Kars ao governador arménio", "efa81cb0"], "d": ["O comandante inglês Preston, que a 12-13 de abril de 1919 dissolvera o Governo do Sudoeste do Cáucaso, aboliu a 30 de abril de 1919 o governo provisório de conselho e entregou a administração da cidade ao arménio Karganof, feito governador de Kars; começou em Kars o período da administração arménia, que durou até à vitória de Kâzım Karabekir a 30 de outubro de 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["O Congresso de Erzurum: a decisão de resistência nacional das províncias orientais", "41ef0457"], "d": ["O congresso convocado pela Sociedade para a Defesa dos Direitos da Anatólia Oriental, depois de adiado por pressão inglesa, abriu com cinquenta e seis delegados e para a sua presidência foi eleito Mustafa Kemal Paxá, que se demitira do exército. O congresso proclamou que, dentro das fronteiras nacionais, a pátria é um todo, que mandato e protetorado são inaceitáveis e que, no caso de dissolução do governo, a nação tomaria nas mãos o seu próprio destino. Estas decisões formariam, seis meses depois, o núcleo do texto do Pacto Nacional.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["O Congresso de Sivas: a união da resistência nacional sob um só teto", "0e9ad36b"], "d": ["O congresso, que iniciou os trabalhos a 4 de setembro de 1919 na Sivas Sultânîsi, reuniu as sociedades de defesa de direitos de todos os cantos do país sob o nome de Sociedade para a Defesa dos Direitos da Anatólia e da Rumélia e elegeu uma Comissão Representativa. A proposta de mandato americano foi rejeitada depois de longas discussões. Com a declaração publicada a 11 de setembro, a Luta Nacional converteu-se num movimento político legítimo de centro único e começou uma luta de poder aberta com o governo de Istambul.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["O Protocolo de Amasya: as conversações entre o governo de Istambul e a Comissão Representativa", "40e6a6ab"], "d": ["Depois da queda de Damat Ferid e da formação do governo de Ali Rızâ Paxá, o ministro da Marinha Salih Paxá foi enviado a Amasya para conversar com a Comissão Representativa. Pelos protocolos alcançados, o governo de Istambul reconheceu de facto a existência do movimento da Anatólia; aceitaram-se a reunião da Assembleia dos Deputados, a realização livre das eleições e a preservação das fronteiras nacionais. Este foi o primeiro ganho político oficial obtido pela Luta Nacional diante de Istambul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["A aprovação do Pacto Nacional na última Assembleia Otomana", "6322865e"], "d": ["O texto do Pacto Nacional, assinado por 121 deputados na última Assembleia dos Deputados otomana, estipulava a integridade indivisível das terras que ficavam dentro da linha de Mudros e onde vivia uma maioria muçulmano-turca, o plebiscito nas províncias árabes e na Trácia Ocidental, a abolição das capitulações e a plena independência política e financeira. O texto foi aprovado por unanimidade a 17 de fevereiro de 1920 e proclamado ao mundo. Esta declaração foi tanto o programa político da Luta Nacional como o mapa das fronteiras que seriam defendidas em Lausana; foi a causa direta de as potências da Entente ocuparem oficialmente Istambul a 16 de março.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Quando os ingleses se retiraram, Artvin ficou na Geórgia", "6d086b06"], "d": ["Segundo o artigo Artvin da TDV, a ocupação inglesa durou até abril de 1920; ao retirarem-se, os ingleses deixaram a cidade à Geórgia. Artvin ficou nas mãos da Geórgia até ao ultimato da TBMM de 23 de fevereiro de 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum foi entregue à administração georgiana", "6523d095"], "d": ["A entrega oficial de Batum aos georgianos pelos ingleses realizou-se a 7 de julho de 1920 (o artigo Batum da TDV diz apenas 'julho de 1920'). O governo de Ancara protestou a 25 de julho contra a entrega, chamando-lhe 'ocupação'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["O Tratado de Gümrü: o primeiro tratado internacional do governo da Grande Assembleia Nacional da Turquia", "9232c690"], "d": ["Quando o exército da frente oriental comandado por Kâzım Karabekir retomou Sarıkamış e Kars, a Arménia pediu a paz e, pelo tratado assinado em Gümrü, aceitou que não reconhecia Sèvres e renunciou às reivindicações territoriais a leste. Este primeiro tratado assinado pelo governo de Ancara foi o primeiro documento internacional a rejeitar de facto Sèvres e abriu à TBMM o caminho do reconhecimento jurídico. Assim, a fronteira oriental ficou garantida e tornou-se possível deslocar forças para a frente ocidental.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["A Primeira Batalha de İnönü: a primeira vitória do exército regular", "4add3719"], "d": ["O exército regular recém-formado deteve nas posições de İnönü as forças gregas que avançavam na direção de Bursa e obrigou-as a recuar. Este êxito, de escala militar limitada, foi enorme nas suas consequências políticas: o governo de Ancara foi convidado à Conferência de Londres, abriu-se o caminho ao Tratado de Moscovo com a Rússia Soviética e foi aprovada a Lei da Organização Fundamental. A confiança da opinião pública interna no exército regular consolidou-se também com esta vitória.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["A Segunda Batalha de İnönü: a segunda rutura da ofensiva grega", "a974521c"], "d": ["O exército grego, que não obtivera resultados na Conferência de Londres, passou a uma nova ofensiva a partir de Bursa e de Uşak, mas foi de novo detido nas cristas de İnönü e obrigado a recuar. O telegrama de Mustafa Kemal Paxá a İsmet Paxá 'Vós aí não vencestes apenas o inimigo, mas também o infortúnio da nação' foi escrito depois desta vitória. A batalha elevou o prestígio internacional da Luta Nacional e acelerou o processo de retirada da Itália da Anatólia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["O Acordo de Ancara: paz com a França e o encerramento da frente sul", "35fc32db"], "d": ["Com o acordo assinado em Ancara com a França depois da vitória do Sakarya, terminou a guerra na frente sul; as forças francesas evacuaram Çukurova e o Sudeste, incluindo Adana, Antep, Maraş e Urfa, e recuaram para a fronteira da Síria. Uma das potências da Entente reconheceu assim de facto o governo de Ancara e abriu-se a primeira fenda na frente de Sèvres. As armas recebidas das regiões evacuadas e as unidades que ficaram livres tiveram um papel crítico na preparação da Grande Ofensiva.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["O Armistício de Mudanya: a cedência de Istambul e dos Estreitos sem guerra", "ac0d9baf"], "d": ["Quando, depois da Grande Ofensiva, o exército turco se viu frente a frente com as forças inglesas em Çanakkale e İzmit, a conferência reunida em Mudanya resultou, após onze dias de regateio duro, num armistício. Aceitou-se que a Trácia Oriental, até ao Maritsa, fosse evacuada pela Grécia em quinze dias e entregue à administração turca, e que Istambul e os Estreitos fossem entregues pelo tratado de paz. Assim, a fase armada da Luta Nacional terminou com uma vitória diplomática ganha sem se disparar um único tiro, e abriu-se a porta de Lausana.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["A partida de Mehmed VI Vahdeddin de Istambul e a eleição de Abdülmecid Efendi como califa", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, o último sultão, cuja posição se tornou discutível depois da abolição do sultanato, partiu de Istambul na manhã de sexta-feira, 17 de novembro de 1922, no couraçado inglês Malaya, e foi para Malta. A TBMM, dois dias depois, a 19 de novembro, elegeu Abdülmecid Efendi como califa sem poderes políticos. O reinado dinástico otomano de seiscentos e vinte e três anos terminou assim de facto; o califado continuaria, de forma simbólica, por mais quinze meses. Vahdeddin, que passou a Malta e depois a Itália, instalou-se na Villa Nobel em San Remo; sem obter resultado nos pedidos que fez para ser acolhido num país muçulmano, morreu ali a 16 de maio de 1926, reiterando que nunca renunciara aos direitos de sultanato e califado.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["A morte do último sultão Mehmed VI Vahdeddin em San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, último sultão otomano, que se instalara em San Remo, em Itália, depois de deixar Istambul, morreu a 16 de maio de 1926, sem ter recebido a notícia da reunião do congresso do califado (13 de maio de 1926), ao qual comunicara que nunca renunciara aos direitos de sultanato e califado. Estava em grande aperto de dinheiro; devia 60.000 liras aos comerciantes de San Remo e os credores, ao saberem da sua morte, mandaram penhorar os bens da sua casa.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["A conquista da região de Bolu por Konuralp — Mudurnu, Konurapa e Bolu", "e245cd27"], "d": ["Konuralp, um dos comandantes de Orhan Gazi, dirigiu-se à região montanhosa a leste do Sakarya e ligou à administração otomana a região de Mudurnu, Konurapa e Bolu; a localidade na planície de Düzce ficou conhecida pelo seu nome. A data exata da conquista não é conhecida; a narrativa assenta na tradição de Âşıkpaşazâde. A região era então uma zona fronteiriça que mudava de mãos entre os Candaroğulları e Bizâncio; a conquista aproximou pela primeira vez os otomanos da costa ocidental do mar Negro. Depois da Batalha de Ancara, a região passaria de novo aos Candaroğulları, mas seria definitivamente recuperada no tempo do Conquistador.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["A tomada das vilas bizantinas a sul do Mármara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Depois de tomadas Niceia e İzmit, as vilas que restavam a Bizâncio a oeste da planície de Bursa foram passando uma a uma para a administração otomana. Gölyazı, em torno do lago Uluabat, Kirmasti e Mihaliç, ao longo do rio Susurluk, completaram o corredor que liga a costa sul do Mármara às terras de Karesi. Estas vilas renderam-se, durante muito tempo sem sofrer cerco, quando o seu entorno foi cortado; a presença bizantina na região ficou assim comprimida no golfo de Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Corinto) passou ao Despotado da Moreia", "392495eb"], "d": ["Corinto, que desde 1358 era timar da família florentina Acciaiuoli dependente do principado de Acaia, passou em 1395 para as mãos de Teodoro, déspota bizantino da Moreia. A cidade permaneceu a partir daí sob a administração do despotado até à conquista otomana.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["A anexação do Beylik dos Hacıemîroğulları — Ordu e Ünye", "c064f07f"], "d": ["O beylik turcomano que Bayram Bey fundara em torno de Ordu e que o filho Hacı Emîr alargou na década de 1350, com centro na atual Eskipazar, era um pequeno mas estratégico Estado costeiro: era a única zona de domínio independente entre Samsun e Trebizonda. Emîr Süleyman manifestara a sua obediência em 1398 na operação de Bajazeto I em Canik, e depois da Batalha de Ancara o beylik voltara a ficar livre. No tempo de Murad II, nos mesmos anos da liquidação dos Tâceddinoğulları, as terras do beylik foram ligadas diretamente à administração otomana e a costa do mar Negro uniu-se numa só mão, de Samsun a Giresun.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["A conquista de Gördüs (Corinto)", "87a2bc59"], "d": ["Na campanha da Moreia do Conquistador, a fortaleza de Acrocorinto foi cercada durante três meses e foi finalmente recebida por via pacífica. O istmo de Corinto, considerado a porta da Moreia, passou assim aos otomanos.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["A ligação de Montenegro à administração otomana — Cetinje", "7fdb7cc8"], "d": ["Quando a dinastia Crnojević, que governava Zeta, abandonou o domínio em 1496, a região montanhosa de Montenegro, que era o quintal de Shkodër, foi posta sob administração otomana direta e organizada primeiro como sanjaco separado e, depois, como parte do sanjaco de Shkodër. O mosteiro de Cetinje foi deixado no lugar como centro religioso da região. Devido à aspereza da geografia, a administração aqui nunca funcionou tão apertada como nas planícies; dois séculos depois, o governo dos vladikas, nascido do mesmo mosteiro, seria o núcleo da independência de facto.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["A aceitação do domínio otomano pela fortaleza de Bayezid na Campanha dos Dois Iraques", "f29e2e17"], "d": ["Quando o grão-vizir Ibrahim Paxá chegou, na Campanha dos Dois Iraques, aos arredores de Bingöl, as fortalezas de Van, Toprakkale, Avnik e Bayezid, juntamente com muitas tribos curdas da região, concordaram em entrar no domínio otomano. Bayezid aderira aos otomanos em 1514, na campanha de Yavuz, mas, quando o exército voltou, os safávidas tinham retomado a região.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz voltou a passar para os safávidas — o regresso dos Dois Iraques", "80b8b761"], "d": ["Na Campanha dos Dois Iraques, o exército entrara em Tabriz, mas, como o verdadeiro objetivo era Bagdade, não se deixara na cidade uma guarnição permanente. Quando o exército, que passara o inverno em Bagdade, voltava para oeste, o xá Tahmasb entrou de novo no Azerbaijão, evacuado, e retomou Tabriz. Este foi o padrão repetido das guerras otomano-safávidas: Tabriz foi tomada cinco vezes e nas cinco não pôde ser conservada; a cidade só receberia uma guarnição otomana duradoura em 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["A queda de Van e Erciş nas mãos de Tahmasb (a posição otomana terminou em 1534-35)", "cb93d561"], "d": ["Na região que dera Van ao domínio otomano em 1534, Ulama Paxá resistiu no Castelo de Van ao cerco safávida; a fortaleza passou para as mãos dos safávidas, e as forças safávidas que cercavam Erciş tinham recuado com a ajuda otomana. Quando o Legislador chegou a Ahlat (23 de setembro de 1535), Van já estava nas mãos de Tahmasb. Van ficou safávida até 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["A passagem do sanjaco de Bayezid para o domínio safávida (Van e Erciş já eram safávidas em 1535)", "806a2cf1"], "d": ["O sanjaco de Bayezid, no meio da fronteira otomano-safávida, voltou a cair nas mãos do Irão (Kaya 2017 refere-o 'juntamente com Van e Erciş'; mas Van e Erciş, segundo Karataş 2025 e a TDV, tinham voltado aos safávidas a 22 de setembro de 1535 — ver o item anterior); nesta mudança de mãos, alguns lugares do sanjaco ficaram arruinados. O sanjaco mudou de mãos várias vezes entre os dois Estados até ao último quartel do século XVI.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["A passagem do sanjaco de Bayezid de novo para os otomanos durante a Campanha de Nakhichevan", "cf0171fa"], "d": ["Durante a terceira campanha da Pérsia (Nakhichevan) do Legislador, o sanjaco de Bayezid foi de novo posto sob administração otomana. Na campanha de 1554, Bayazıt foi uma base importante para o exército; o sanjaco entrou definitivamente na soberania otomana em 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["A perda de Erevan para o xá Abbas", "34413cf2"], "d": ["Quando a frente oriental ficou indefesa nos anos em que as revoltas celalis bloqueavam a Anatólia, o xá Abbas, que reorganizara o exército à europeia, passou à ofensiva. A fortaleza de Revan, que Ferhad Paxá mandara construir em 1583, rendeu-se depois de sete meses de cerco. O primeiro elo da linha do Cáucaso ganha pelo Tratado de Ferhad Paxá estava quebrado e, nos três anos seguintes, todo o Cáucaso Meridional se perderia.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["A perda de Tbilisi e Gence", "3fb51753"], "d": ["Depois da queda de Revan, o exército safávida avançou ao longo do vale do Kura; Gence, centro de Karabakh, e Tbilisi, capital da Geórgia, perderam-se uma após outra. O Estado Otomano conduzia ao mesmo tempo a longa guerra de treze anos na frente austríaca e lidava com os celalis na Anatólia; não havia forças para enviar para leste. Assim, a ordem das vastas províncias do Cáucaso, estabelecida pelo Tratado de Ferhad Paxá de 1590, terminou de facto.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["A perda de Şirvan — Şamahı, Baku e Derbent", "81beab11"], "d": ["A província de Şirvan, na costa do Cáspio, ganha pelas campanhas de 1578-1585 de Özdemiroğlu Osman Paxá, dera às finanças otomanas um rendimento importante como principal fonte do comércio da seda. A operação do xá Abbas para norte liquidou esta província tomando sucessivamente Şamahı, Baku e Derbent. A perda não foi apenas territorial: a rota da seda persa que afluía à Europa através dos otomanos saiu também do controlo, e o Estado safávida passou a comercializar a seda pelo oceano Índico.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["A perda de Taiz", "65f20d53"], "d": ["Os otomanos abandonaram em 1038 (1629) Taiz, juntamente com o domínio do Iémen deixado ao governo kāsımî de Sana — o primeiro grande passo do processo em que os imames zaiditas retomaram o Iémen interior.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["A perda do Iémen — o domínio dos imames Kāsımî", "49e83e3c"], "d": ["O Iémen era província otomana desde 1538; mas a resistência dos imames zaiditas nunca cessou. A insurreição iniciada pelo imame Kāsım espalhou-se a todo o país no tempo do seu filho al-Muayyad Muhammad, e as guarnições otomanas foram sendo cercadas sucessivamente. Nos anos em que Murad IV estava concentrado em Bagdade e Revan, não se puderam enviar reforços; Taiz perdera-se em 1629, e Moca fora evacuada a 22 de outubro de 1635, na última fase do mesmo colapso. Em 1635, as últimas unidades em Sana e Zabid evacuaram também o Iémen. Assim, a costa oriental do mar Vermelho ficou fora do império durante duzentos e trinta e sete anos e só pôde ser recuperada em 1872.", "7d62c00f"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["A evacuação de Moca", "c6b3061a"], "d": ["Mustafa Bey evacuou Moca a 10 de Cemâziyelevvel de 1045 (22 de outubro de 1635) com a força e as armas que restavam; em seguida, Hasan b. Kāsım, filho do imame Kāsım, nomeou os seus próprios homens para Zabid e Moca e estabeleceu também na costa de Tihâme o controlo Kāsımî.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["A perda de Lahsa para o Emirado de Banu Khalid", "a9b6131a"], "d": ["Lahsa era uma província criada em 1550 para fechar a Portugal a costa ocidental do golfo de Bassorá; mas estava muito longe de Istambul, na ponta de uma única rota do deserto. Nos anos em que o cerco de Creta esgotava os recursos, a tribo Banu Khalid da região, sob a liderança de Berrâk b. Gureyr, expulsou a guarnição otomana e fundou o seu próprio emirado. A costa ocidental do golfo ficou durante século e meio nos emirados tribais; passaria em 1795 aos sauditas e em 1871 de novo aos otomanos.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["A perda de Preveza e Vonitsa para Veneza — a abertura da costa do Epiro", "1201204c"], "d": ["Veneza, que aderira à Santa Aliança, antes de iniciar a campanha da Moreia tomou as duas fortalezas que guardam a entrada do golfo de Ambrácia: Preveza e, na margem oposta, Vonitsa. No mesmo verão caíra também Ayamavra (Lefkada). Estas três posições permitiram à frota penetrar com segurança do mar Jónico para o interior da Grécia e tornaram-se a base da operação da Moreia, que começaria no ano seguinte. Preveza e Vonitsa foram também deixadas a Veneza em Požarevac; só voltariam à administração otomana em 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["A perda de Szolnok — a dissolução da linha do Tisza", "51c2c8ef"], "d": ["Depois da queda de Uyvar em agosto, o exército habsburgo voltou-se para sul e tomou Szolnok, cabeça de ponte sobre o rio Tisza. A cidade era a única passagem segura entre Buda e a Transilvânia; a sua perda significava o corte entre si das fortalezas otomanas da metade oriental da Hungria. No cerco de Buda, no ano seguinte, o facto de se ter cortado a via de abastecimento foi decisivo.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["A perda de Modon para Veneza", "114c9cc0"], "d": ["Modon, no extremo sudoeste da península da Moreia, era o porto que Veneza perdera três séculos antes e a que chamava 'um dos dois olhos do Estado'. A fortaleza, cercada depois da queda de Koron, foi tomada batida ao mesmo tempo por terra e por mar. A operação da Moreia de Morosini apoderou-se assim de toda a costa ocidental da península e abriu-se o caminho para o interior.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["A perda de Peçuy", "99d54cf4"], "d": ["Depois da queda de Buda em setembro, as forças habsburgas desceram para sul a oeste do Danúbio e tomaram Peçuy, otomana desde o tempo do Legislador. A cidade, conhecida pela Mesquita de Gazi Kâsım Paxá, era um dos mais desenvolvidos centros de sanjaco da província de Buda. A sua perda significava a abertura do caminho que desce para a planície de Mohács; no ano seguinte, o Segundo Desastre de Mohács seria vivido precisamente ali.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["A perda de Szeged", "9fbee1b2"], "d": ["Szeged, no ponto onde se juntam os rios Tisza e Maros, era a porta sul da planície húngara e guardava o caminho para a província de Timișoara. A fortaleza, cercada depois de Buda e Peçuy terem caído no mesmo outono, rendeu-se em pouco tempo. A perda de três fortalezas numa só estação era o sinal de que a estrutura administrativa otomana na Hungria, estabelecida desde 1541, começava a ruir.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["A perda de Balyabadra (Patras) — a porta norte da Moreia", "b9cff63c"], "d": ["Balyabadra, na entrada do golfo de Corinto, era o porto que controlava a passagem entre a Moreia e a Rumélia. Depois de o exército veneziano tomar a cidade, caíram também uma após outra as fortalezas das duas margens do golfo e a península ficou totalmente isolada por terra. No fim desta operação, toda a Moreia passou a Veneza; a região seria governada até 1715 com o nome de 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["A cedência de Gördüs (Corinto) a Veneza", "9a25b6b9"], "d": ["Depois da queda de Balyabadra, Corinto foi deixada aos venezianos por via pacífica e a população muçulmana abandonou a cidade. Em agosto de 1687, o exército de Morosini reunia-se em Corinto para a campanha de Atenas.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["A perda de Eger", "983391aa"], "d": ["Eger fora tomada em 1596 pela campanha em que Mehmed III participou pessoalmente e tornara-se centro de uma província com o seu nome. Esta última grande fortaleza otomana da Hungria do Norte, depois do Segundo Desastre de Mohács, resistiu um ano completamente cercada e rendeu-se por fome. Com a sua perda, o flanco norte do Estado Otomano na Hungria foi totalmente liquidado.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["A perda de Székesfehérvár — a cidade da coroação dos reis húngaros", "c6147255"], "d": ["A cidade onde os reis húngaros foram coroados e sepultados durante séculos fora tomada em 1543 pelo Legislador e tornara-se um dos mais importantes centros de sanjaco da província de Buda. Cerca de dois anos depois da queda de Buda, a fortaleza, completamente cortada em redor, rendeu-se. Com esta perda, a presença otomana a oeste do Danúbio ficou comprimida em torno de Sirmia e Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["A perda de Szigetvár", "834910a7"], "d": ["Szigetvár era a fortaleza em que o sultão Solimão, o Legislador, morreu em 1566, durante o cerco, na sua décima terceira e última campanha; por isso tinha um lugar simbólico na memória otomana. Cento e vinte e três anos depois, quando caíram todas as fortalezas em seu redor, rendeu-se também a fortaleza protegida por pântanos. O mausoléu onde estavam sepultadas as entranhas do Legislador e a vila em seu redor foram destruídos depois de passarem para a administração habsburga.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["A perda de Várad", "6cce360d"], "d": ["Várad era a fortaleza-chave que se abre para a Transilvânia, tomada em 1660 por Köprülü Mehmed Paxá, que fez dela centro de uma província com o seu nome. A fortaleza, que ficou completamente só depois do desastre de Slankamen, rendeu-se por fome depois de um bloqueio de quase dois anos. Com a sua perda, a influência otomana sobre a Transilvânia terminou de facto e o domínio habsburgo estabeleceu-se a leste do Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["A perda de Yanova — o encerramento do caminho da Transilvânia", "4b5e30d8"], "d": ["Yanova era uma fortaleza tomada em 1658 que guardava a ligação entre Várad e Timișoara. Quando foi cortada em redor logo depois da queda de Várad, perdeu-se também. Assim, a província de Timișoara ficou totalmente isolada a norte e continuou a existir, até Karlowitz, como único território da Hungria que permanecia nas mãos dos otomanos.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["O estabelecimento do governo dos vladikas em Montenegro — a separação de facto de Cetinje", "a924b778"], "d": ["Nos anos em que a Guerra da Santa Aliança afrouxou o controlo otomano nos Balcãs, a metrópole à frente do mosteiro de Cetinje tornou-se um cargo que passava de pai para filho na família Petrović, e a região ganhou de facto uma administração separada. Graças à inacessibilidade das montanhas, este vladikado manteve-se durante dois séculos numa posição nem plenamente independente nem plenamente dependente; a sua independência jurídica só seria reconhecida pelo Tratado de Berlim de 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["A reconquista de Gördüs (Corinto)", "26f53e3a"], "d": ["A primeira grande paragem da campanha da Moreia de Damad Ali Paxá foi Corinto; os otomanos retomaram a cidade aos venezianos em junho de 1715 e daí avançaram para o resto da península.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["A ofensiva de Nâdir: a perda de Tabriz, Nakhichevan, Hemedan, Kirmanxá, Merâga e Kasr-ı Şîrîn", "d95efd59"], "d": ["As cidades do Irão Ocidental tomadas entre 1723 e 1727, aproveitando o colapso do Estado safávida, foram-se perdendo uma a uma com a ofensiva de Nâdir Han, que tomara de facto o poder no Irão. No Azerbaijão, Erdebil e Halhal caíram também nas mãos de Nâdir. A perda de Hemedan, Kirmanxá e Kasr-ı Şîrîn teve pesado eco em Istambul; o facto de o exército não ter saído em campanha, ficando à espera em Üsküdar, e de se ter procurado encobrir a perda foi uma das causas diretas da Revolta de Patrona Halil, que rebentaria seis semanas depois.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["O desastre de Baghavard (Arpaçay) — a perda do Cáucaso para Nâdir Han", "4262f54c"], "d": ["As províncias do Cáucaso tomadas em 1723-1725, aproveitando o colapso do Estado safávida, puderam ser conservadas durante dez anos. Nâdir Han, que tomara de facto o poder no Irão, infligiu ao exército otomano uma pesada derrota em Baghavard, perto de Revan; o serdar Abdullah Köprülü Paxá perdeu a vida no campo de batalha. Depois do desastre, Revan, Tbilisi, Gence e Şirvan foram evacuadas em meses. A fronteira oriental voltou à linha de Kasr-ı Şîrîn de 1639, que seria confirmada em 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["A perda de Bender para os russos", "0daca453"], "d": ["Depois do desastre da planície de Kartal, o exército otomano recuara para sul do Danúbio, e as fortalezas entre a Moldávia e Özi tinham ficado sozinhas. Bender, que guarda o ponto de passagem do rio Turla, foi tomada de assalto depois de um cerco de dois meses; a cidade foi saqueada. A perda da fortaleza quebrou o elo central da linha de defesa do mar Negro setentrional, e a seguir caíram também Akkirman e Kili. Em Küçük Kaynarca, Bender seria devolvida, mas voltaria a perder-se em 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["A entrada do emirado de Sabah no Kuwait sob proteção otomana", "3584dba0"], "d": ["Segundo o artigo Kuwait da TDV, o porto fora fundado no início do século XVIII pela tribo Utub vinda de Najd, e a família Sabah assumira a administração para o fim do século. Nos mesmos anos em que Lahsa passou para as mãos dos sauditas, o emirado, que perante a pressão wahhabita não tinha outra opção senão apoiar-se em Bassorá, entrou sob proteção otomana. O vínculo seria oficializado em 1871 pela organização de Bassorá de Midhat Paxá, e o Kuwait seria contado como um dos três kazas do sanjaco de Bassorá; a posterior reivindicação territorial do Iraque assenta também neste registo.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["A perda de Meca para os wahhabitas", "2da23acd"], "d": ["O movimento wahhabita, nascido em Najd, voltou-se para o Hejaz no tempo de Suûd b. Abdülazîz; depois de Taif e Medina, Meca foi recebida também pela segunda vez — o emir de Meca, o xarife Gālib, entregou a cidade aos wahhabitas com a condição de permanecer no emirado. Os mausoléus foram derrubados e cortou-se o caminho das caravanas de peregrinos vindas de Damasco e do Cairo; o surre que o sultão enviava todos os anos aos Haremeyn foi também interrompido nestes anos — a única exceção a esta dotação ininterrupta até 1915 é o período do domínio wahhabita. Como o título de protetor dos Haremeyn era um dos fundamentos da legitimidade do sultão, esta perda foi, além de uma perda de território, um pesado golpe político; a sua recuperação levaria sete anos e só seria possível com o exército de Mehmed Ali Paxá de Cavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["O fim da República de Ragusa — a ocupação francesa", "f8e27bf1"], "d": ["Os franceses, que se tinham instalado na costa da Dalmácia pelo Tratado de Campo Formio (1797), tomaram Dubrovnik a 27 de maio de 1806 e puseram fim à pequena república mercantil. Assim terminou o estatuto de súbdita de três séculos e meio de Dubrovnik, que desde 1458 pagava tributo aos otomanos e preservava a sua autonomia e os seus privilégios comerciais; a cidade e a ilha de Mljet da república passam no mapa para a administração francesa direta.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["A perda de Sukhumi para os russos — a abertura da costa oriental do mar Negro", "adc96bd4"], "d": ["Na guerra otomano-russa de 1806-1812, a frota russa dirigiu-se à costa oriental do mar Negro e tomou Sohumkale, em que se apoiava o domínio otomano na Abecásia. A fortaleza era o centro da ligação com as tribos do Cáucaso e do comércio costeiro. Com a sua perda, a Rússia instalou-se pela primeira vez de forma duradoura na costa oriental do mar Negro; a influência otomana no Cáucaso ficou comprimida em torno de Anapa e Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["A cedência de Parga à administração otomana", "66e0cc5d"], "d": ["Parga estava nas mãos de Veneza desde 1401 e nunca entrara na administração otomana; depois da queda de Veneza, passou sucessivamente à França e à Inglaterra. O artigo Tepedelenli Ali Paxá da TDV resume a situação assim: a cidade rendeu-se aos ingleses e só foi cedida à administração de Ali Paxá em 1819. A cedência resultou na emigração da maior parte da sua população para as ilhas Jónicas. Assim, o último do trio Preveza-Parga-Vonitsa, deixado a Veneza em Požarevac, foi também incorporado no império; Parga seria otomana durante noventa e quatro anos.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["A passagem de Gördüs (Corinto) para os insurretos gregos", "892dcdc6"], "d": ["Durante a guerra de independência grega, Acrocorinto passou para as mãos dos insurretos e o comandante da fortaleza, Kâmil Bey, foi feito prisioneiro.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["A perda de Anabolu (Náuplia) para os insurretos", "1a67fa50"], "d": ["Anabolu, o porto da Moreia com as fortificações mais fortes, rendeu-se por fome depois de um bloqueio de mais de um ano. A fortaleza era, desde o início da insurreição, o último grande apoio do controlo otomano na península; com a sua perda, toda a Moreia passou para as mãos dos insurretos. A cidade seria pouco depois a primeira capital do novo Estado grego.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["A passagem de Lepanto para a administração grega", "c9d19d4b"], "d": ["Lepanto, na costa norte do golfo de Corinto, que permanecera nas mãos dos otomanos até à insurreição grega, perdeu-se em abril de 1829 e entrou na administração grega; o nome da vila foi mudado para o da antiguidade, Naupactos. A população muçulmana e judaica da cidade desapareceu por completo e o lugar converteu-se numa pequena vila.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["A ocupação francesa de Argel — o fim da milícia (ocak) de trezentos anos", "0be8f568"], "d": ["Tomando por pretexto o incidente do leque, nascido de uma disputa de créditos, a França manteve a costa argelina sob bloqueio durante três anos e depois desembarcou tropas em Sidi Ferruch. No fim de uma operação de três semanas, Hüseyin Dei rendeu-se e a milícia otomana de Argel, que durava desde 1516, chegou ao fim. A ocupação não ficou limitada à capital; também Tlemcen, Cherchell e Medea, no interior, se perderam no mesmo verão. A passagem de toda a costa para o controlo francês ainda demoraria vinte e quatro anos.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["A entrega de Negroponte à Grécia — juntamente com a ilha (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, que foi palco de intensos combates durante a guerra de independência grega mas permaneceu nas mãos dos otomanos, foi entregue aos gregos em 1831, depois de entrado em vigor o tratado de paz. A população muçulmana da cidade, que era importante base naval desde 1470, vendeu todos os seus bens a preços baixíssimos e emigrou em massa para as terras otomanas; a cidade ficou vazia durante muito tempo e o viajante alemão Fallmerayer descreveu-a em 1842 como uma cidade fantasma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["A ocupação francesa de Orão", "a8415d66"], "d": ["Orão, que a Espanha cedera sem guerra em 1792, era o maior porto do oeste da Argélia. Seis meses depois da queda da capital, tropas francesas entraram na cidade. A operação a oeste, que daqui partiu, depressa se depararia com a resistência de quinze anos do emir Abdelkader.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["A ocupação de Annaba (Bône)", "21f37fb1"], "d": ["Annaba, porto da Argélia oriental junto à fronteira da Tunísia, foi tomada pelas forças francesas e transformada em base da marcha sobre Constantina. A cidade era ao mesmo tempo o porto africano mais próximo em frente à ilha da Sardenha.", "1ca5b213"]},
"OLAYLAR_EK6:1833-03-31:0":{"b": ["A cedência de Atenas ao novo Estado grego", "98af5572"], "d": ["Atenas, otomana desde 1456, mudara de mãos várias vezes durante a guerra de independência grega, e a guarnição da Acrópole passara de novo ao controlo otomano em 1827. Por ficar a norte da fronteira traçada pelo Protocolo de Londres, a cidade foi cedida ao novo reino e a guarnição evacuou a Acrópole. No ano seguinte, Atenas foi declarada capital da Grécia, em lugar de Anabolu.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["A ocupação de Bugia", "a8927e00"], "d": ["O porto de Bugia, onde as montanhas da Cabília se abrem para o mar, era o último elo independente da linha costeira entre Argel e Annaba. Foi tomado com o apoio da artilharia naval; mas o interior montanhoso atrás dele ainda demoraria trinta anos a entrar no controlo francês. Estas ocupações ao longo da costa constituem a erosão, ano após ano, da Argélia otomana no mapa.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["A ocupação de Sétif", "2073731a"], "d": ["Depois da queda de Constantina no ano anterior, as forças francesas subiram ao planalto e, tomando a antiga cidade romana de Sétif, estabeleceram aí uma guarnição permanente. Sétif era o ponto de cruzamento das rotas de caravanas entre a costa e o Saara; a sua ocupação mostrou que a França começava a controlar já não apenas os portos, mas também a rede comercial do interior.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["A ocupação de Biskra — a perda da porta do Saara", "d895cad0"], "d": ["Biskra era, no sopé sul das montanhas do Atlas, a porta que se abre para o Saara e o centro dos oásis de tamareiras. A sua tomada, nos anos em que a resistência do emir Abdelkader começava a quebrar-se, fez o controlo francês chegar pela primeira vez à costa norte do deserto. O que se seguiria seria já uma operação do deserto avançando oásis a oásis.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["A ocupação de Touggourt — a perda de toda a Argélia", "33c056e2"], "d": ["Com a tomada de Touggourt, cidade-oásis a norte do Saara, a ocupação iniciada em 1830 ficou completa na metade norte da atual Argélia. O Estado Otomano combatia nestes anos na Guerra da Crimeia ao lado da França; embora nunca tenha renunciado oficialmente à sua pretensão jurídica sobre a Argélia, não pôde dar de facto um único passo. O único território que lhe restava no Norte de África era Trípoli de Barbaria.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["A queda de El Obeid — a passagem do Cordofão para as forças do Mahdi", "58299f62"], "d": ["O movimento iniciado por Muhammed Ahmed, que se proclamara mahdi, propagou-se depressa contra a administração egípcia no Sudão. El Obeid, centro do Cordofão, caiu depois de um cerco de quatro meses e tornou-se capital da insurreição; o tesouro e os depósitos de armas da cidade permitiram ao movimento constituir-se em exército. O Sudão era juridicamente ainda território do quediva do Egito, dependente dos otomanos, pelo que a perda cai no mapa do corpo do império.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["A queda de Cartum — a perda de todo o Sudão", "d4b98464"], "d": ["Depois de um cerco de dez meses, as forças do Mahdi entraram em Cartum, no ponto de confluência do Nilo Azul e do Nilo Branco; o governador da cidade, Gordon, foi morto, e a coluna inglesa enviada em socorro chegou dois dias tarde. A partir desta data, todo o Sudão, incluindo Sennar, Dongola e o Cordofão, permaneceu durante catorze anos sob a administração do Estado Mahdista. A região só entraria em 1899 na administração conjunta anglo-egípcia, com o vínculo otomano totalmente cortado.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["A ocupação italiana de Maçuá — a perda da costa ocidental do mar Vermelho", "c333b95b"], "d": ["O porto de Maçuá, centro da província da Abissínia, foi ocupado pela Itália, que aproveitou a confusão em que a insurreição do Mahdi cobria o Sudão; isto formou o núcleo da Eritreia italiana. Suakin, a norte, e o arquipélago de Dahlak, ao largo, perderam-se no mesmo processo. Assim terminou o domínio otomano na costa ocidental do mar Vermelho, que durava desde o tempo do sultão Selim Yavuz, e o mar tornou-se uma água estrangeira em ambas as margens.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["A ocupação italiana de Rodes", "e08662c5"], "d": ["A Itália, que na Guerra de Trípoli de Barbaria queria levar o Estado Otomano à mesa de negociações, levando a guerra ao Mediterrâneo desembarcou tropas em Rodes. A ilha foi tomada em poucos dias. Rodes, que o Legislador tomara em 1522 depois de um longo cerco e que os otomanos mantiveram trezentos e noventa anos, deixou assim de ser a maior base insular do império no Mediterrâneo Oriental; embora no Tratado de Ouchy fosse considerada ocupação provisória, nunca mais foi recuperada.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["A ocupação italiana do Dodecaneso", "200aacf2"], "d": ["Na semana seguinte à tomada de Rodes, a frota italiana ocupou também as ilhas circundantes; a este arquipélago seria dado mais tarde o nome de 'Dodecaneso'. A maior parte das ilhas ficava a poucas milhas da costa da Anatólia e controlava a passagem sudeste do Egeu. A ocupação foi considerada provisória no Tratado de Ouchy em troca da cedência de Trípoli de Barbaria, mas a Itália nunca evacuou as ilhas; seriam cedidas à Grécia em 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["A ocupação de Cós", "ab246c62"], "d": ["Cós, último elo da operação do Dodecaneso, era uma ilha fértil e populosa, mesmo em frente à península de Bodrum. Com a ocupação, todas as ilhas do canto sudeste do Egeu entraram no controlo italiano e a costa sudoeste da Anatólia ficou cingida, de ponta a ponta, por uma cadeia de ilhas estrangeiras.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["A proclamação de independência de Nikarya", "c4452033"], "d": ["Na pequena ilha de Nikarya, entre Samos e Quios, o povo, no ambiente de incerteza criado pelas ocupações italianas, sublevou-se, expulsou da ilha a gendarmaria otomana e proclamou um 'Estado livre', com bandeira, selo e assembleia próprios, que durou cinco meses. Em novembro de 1912 a ilha aderiu à Grécia. Apesar da sua pequenez, este caso é uma demonstração clara de como se dissolvia a administração central no Egeu.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["A saída de Samos da administração otomana", "3a862f2b"], "d": ["Samos era, desde 1832, um principado autónomo que pagava imposto aos otomanos e era governado por um bei nomeado por Istambul. No vazio criado pela Guerra de Trípoli de Barbaria, o movimento unionista da ilha tomou a administração e a ordem do principado autónomo terminou de facto; a ilha declarou, no mesmo ano, a sua adesão à Grécia. Esta ilha, a dois quilómetros da costa da Anatólia, foi um dos primeiros territórios perdidos no Egeu.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["A queda de Ioannina — a perda do Epiro e de Parga", "d42fce18"], "d": ["Ioannina, cercada durante cinco meses na Guerra dos Balcãs, rendeu-se depois da queda das posições de Bizani; com a cidade, todo o Epiro passou à Grécia. Parga, dependente do sanjaco de Ioannina, perdeu-se também nesta data e a administração otomana de noventa e quatro anos terminou. A perda de Ioannina significava o encerramento da última janela do império que se abria para o Adriático.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["A queda de Edirne para os búlgaros", "459d2e56"], "d": ["Depois de um cerco de cinco meses e meio, Edirne, com as munições e os mantimentos esgotados, rendeu-se; Şükrü Paxá foi feito prisioneiro. A queda da cidade, otomana desde 1361 e capital durante noventa e dois anos, foi considerada o golpe mais pesado da Guerra dos Balcãs. Edirne seria retomada quatro meses depois, na Segunda Guerra dos Balcãs, aproveitando o colapso da Bulgária nas outras frentes.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["A perda de Yanbu para as forças do xarife Hussein", "e291c816"], "d": ["A insurreição que o xarife Hussein iniciara em junho propagou-se à costa do mar Vermelho; Yanbu, porto de Medina, passou para as mãos dos insurretos com o apoio da frota inglesa. O porto tornou-se a principal porta do afluxo de armas e dinheiro vindo de fora para a insurreição. Assim, a ligação marítima das forças de Fahreddin Paxá em Medina ficou cortada e a cidade ficou sozinha na ponta da via-férrea do Hejaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["A Terceira Batalha de Gaza — a perda de Gaza e Khan Yunis", "c142a069"], "d": ["Depois de duas tentativas falhadas, Allenby, na sua terceira ofensiva, rompeu a frente contornando Beersheba e a linha de Gaza, que se mantivera seis meses, ruiu. Gaza e Khan Yunis, a sul, foram evacuadas no mesmo dia. Esta rutura foi o início da desagregação da frente da Palestina; Jerusalém cairia cinco semanas depois.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["A ocupação de Gümülcine — a perda da Trácia Ocidental", "904d813c"], "d": ["A Trácia Ocidental, que depois de Mudros passou primeiro ao controlo das unidades da Entente, foi deixada à Grécia por decisão da conferência de San Remo e o exército grego entrou em Gümülcine. A região, retomada à Bulgária em 1913, foi o último território que o império perdeu na Rumélia. O estatuto da população turca da região seria regulado, três anos depois, em Lausana, por um regime de minorias.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["A dissolução do Estado Ilkhanida: a morte de Ebû Said Bahadır Han", "0f187469"], "d": ["Segundo o artigo İlhanlılar da Enciclopédia do Islão da TDV, a morte de Ebû Said sem deixar herdeiro levou à fragmentação do Estado İlhanlı, que dominava o Irão havia um século; os emires, aproveitando as lutas pelo trono, fundaram dinastias locais como os Jalayiridas, os Kara Koyunlu, os Muzafáridas, os Serbedárides do Khorasan e os Eretnaoğulları. Esta dissolução dividiu a região num mosaico de beyliks que duraria um século; por fim, seria de novo unificada pelas campanhas de Timur.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["A sujeição de grande parte do Irão por Timur", "1cee2b82"], "d": ["Segundo o artigo Timur da Enciclopédia do Islão da TDV, Timur, que desde o início da década de 1380 liquidou uma a uma as dinastias locais posteriores aos Ilcânidas, como os Serbedárides, os Kert e os Muzafáridas, submeteu de facto grande parte do Irão durante a 'campanha de três anos' de 1386-1388; o fim definitivo da dinastia dos Muzafáridas seria dado em 1393. A região foi assim de novo ligada a uma única autoridade central, depois de um século de fragmentação.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["A vitória do Aras: Kara Yûsuf derrotou o timúrida Ebû Bekir Mirza", "4b61a75a"], "d": ["Kara Yûsuf, bei dos Kara Koyunlu, que regressou do exílio depois da morte de Timur em 1405, tomou Avnik e recuperou as suas terras na Anatólia Oriental, e depois marchou contra Ebû Bekir Mirza, neto de Timur e considerado senhor do Azerbaijão e dos dois Iraques, derrotando-o na margem do Aras. Esta vitória não deu Tabriz aos Kara Koyunlu: a TDV `tebriz` escreve que a cidade estava em 1408 nas mãos de Ebû Bekir Mirza; a batalha que deu o Azerbaijão é a de Serdrûd, de 13 de abril de 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["A vitória de Serdrûd: Tabriz e o Azerbaijão passaram aos Kara Koyunlu", "1f0a429d"], "d": ["Kara Yûsuf derrotou o timúrida Ebû Bekir Mirza pela segunda vez depois do Aras, em Serdrûd, perto de Tabriz; esta vitória deu o Azerbaijão aos Kara Koyunlu. Kara Yûsuf encarregou em seguida Bistam Bey da conquista do Irâk-ı Acem;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["A epidemia de peste em Istambul e a transferência do palácio para Edirne", "70c7a163"], "d": ["Segundo o artigo Istambul da Enciclopédia do Islão da TDV, o povoamento rápido e denso da cidade preparou o terreno para a propagação, de tempos a tempos, de doenças epidémicas; durante a epidemia de peste do ano de 1466, o palácio e os dignitários do Estado retiraram-se provisoriamente para Edirne. A população da cidade sofreu perdas sérias em epidemias deste tipo.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["O fim do Estado Kara Koyunlu por Uzun Hasan", "ef68399e"], "d": ["Segundo o artigo Uzun Hasan da Enciclopédia do Islão da TDV, o soberano Ak Koyunlu Uzun Hasan derrotou e matou o soberano Kara Koyunlu Cihan Xá na região de Bingöl-Sancak a 12 de Rebîülâhir de 872 / 10 de novembro de 1467; o filho de Cihan Xá, Hasan Ali, foi derrotado em Merend em setembro de 1468 e morto diante de Hemedan em abril-maio de 1469, e o Estado Kara Koyunlu foi definitivamente extinto. As terras passaram ao domínio Ak Koyunlu; o Estado alargar-se-ia, na década seguinte, até ao interior do Irão.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["A abertura ao ensino das madraças de Sahn-ı Semân", "021f2a83"], "d": ["Segundo o artigo Sahn-ı Semân da Enciclopédia do Islão da TDV, estas oito madraças, fundadas no âmbito do Complexo de Fatih, foram concebidas como a instituição de ensino de mais alto nível da época e constituíram o topo da hierarquia científico-religiosa otomana. O cargo de professor e a graduação aqui foram considerados, nos séculos seguintes, o degrau mais prestigioso na carreira de cádi e de professor.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["A conclusão do Palácio de Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Segundo o artigo Palácio de Topkapı da Enciclopédia do Islão da TDV, as fontes da época divergem nas datas de início e de fim da construção; segundo a data de 883 (1478) da inscrição da Bâb-ı Hümâyun, a construção, iniciada provavelmente em 1465 por ordem do Conquistador, estava em grande parte concluída neste ano, e o palácio substituiu o centro do Estado no antigo palácio. Assim, o sultão mudou-se para a nova residência que seria, durante três séculos, o coração administrativo e cerimonial do Estado.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["A entronização de Bajazeto II em Istambul", "9b686d04"], "d": ["Segundo o artigo Bayezid II da Enciclopédia do Islão da TDV, o príncipe Bajazeto, sanjakbeyi de Amasya, ao receber a notícia da morte do pai veio depressa a Istambul e subiu ao trono; deixou para trás, com o apoio dos janízaros, a saída do irmão Cem de Konya. Durante a entronização foi distribuída aos janízaros a gratificação de entronização, que era costume. Esta mudança de trono acendeu também o pavio da luta entre os dois irmãos.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["O sultão Cem proclama-se sultão em Bursa", "b355168a"], "d": ["Segundo o artigo Cem Sultan da Enciclopédia do Islão da TDV, Cem, que chegou a Bursa por Karaman, tomou a cidade, proclamou-se sultão e mandou ler a hutbe. Este sultanato de curta duração terminou quando as forças enviadas pelo irmão mais velho, Bajazeto II, derrotaram Cem em Yenişehir. Com a derrota, Cem foi obrigado a fugir na direção do Egito.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["A execução de Gedik Ahmed Paxá", "6d75a58c"], "d": ["Segundo o artigo Gedik Ahmed Paxá da Enciclopédia do Islão da TDV, o paxá, conhecido pela campanha de Otranto e pelo grão-vizirado, foi executado em Edirne por ordem de Bajazeto II, devido à sua atitude na questão do sultão Cem e à preocupação com a sua influência. A morte de um dos mais experientes comandantes do tempo do Conquistador suscitou grande eco no palácio.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["A fundação da primeira tipografia em Istambul", "04475930"], "d": ["Segundo o artigo Tipografia da Enciclopédia do Islão da TDV, os irmãos David e Samuel ibn Nahmias, emigrantes judeus vindos da Espanha, fundaram em Istambul a primeira tipografia, que imprimia em caracteres hebraicos. Ficou registada como a primeira iniciativa tipográfica a funcionar em terras otomanas; a impressão em turco, em caracteres árabes, só seria possível muito mais tarde, no século XVIII.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["A tomada de Tabriz pelo xá Ismail: a fundação do Estado Safávida", "014d81e6"], "d": ["Segundo os artigos Safevîler e Akkoyunlular da Enciclopédia do Islão da TDV, İsmail, jovem xeique do tekke de Ardabil, com o exército que formou com os discípulos Kızılbaş da Anatólia infligiu uma pesada derrota ao sultão Ak Koyunlu Elvend na região de Nakhichevan; Elvend fugiu para Diyarbekir, İsmail entrou em Tabriz e sentou-se no trono e proclamou o xiismo dos doze imames como confissão oficial. Assim terminaram tanto o domínio Ak Koyunlu como o período dos beyliks posteriores aos Ilcânidas na região; foi fundado o Estado Safávida, que duraria três séculos.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["O sismo do 'Pequeno Juízo Final' em Istambul", "53e3b1d6"], "d": ["Segundo o artigo Istambul da Enciclopédia do Islão da TDV, o violento sismo que atingiu a cidade ficou conhecido entre o povo como o 'Pequeno Juízo Final'; houve graves danos nas muralhas, nas mesquitas e em muitos edifícios e numerosas perdas de vidas. Por ordem de Bajazeto II, foi iniciada na cidade uma vasta mobilização de reparação e de construção.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["O início da revolta de Şahkulu", "3d9a4a90"], "d": ["Segundo o artigo Şahkulu Baba Tekeli da Enciclopédia do Islão da TDV, Şahkulu, alimentado pela propaganda safávida, reuniu à sua volta uma vasta massa turcomana na região de Teke e iniciou uma grande revolta de caráter religioso e social. A revolta, uma das mais sérias crises de segurança interna da época, abalou profundamente a autoridade central do Estado.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["A morte de Bajazeto II no caminho de Dimotika", "c46e98c9"], "d": ["O antigo sultão, que depois de abdicar deixou Istambul para ir a Dimotika, a cidade onde nascera, avançava na sua liteira, que só lhe permitia percorrer 5-6 km por dia, quando se sentiu mal na aldeia de Abalar, perto de Çorlu, e faleceu a 25 de Rebîülevvel de 918 (10 de junho de 1512). A Enciclopédia do Islão da TDV considera a causa da morte muito suspeita; segundo algumas fontes nacionais e estrangeiras, insiste-se na possibilidade de ter sido envenenado. Depois de um reinado de trinta e um anos, perdeu assim a vida o oitavo sultão da linhagem de Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["A execução do príncipe Ahmed por ordem de Selim Yavuz", "65abb2f2"], "d": ["Segundo o artigo Selim I da Enciclopédia do Islão da TDV, o príncipe Ahmed, favorito do pai Bajazeto II e verdadeiro rival ao trono, foi derrotado na planície de Yenişehir na luta que travou depois da subida ao trono do irmão Selim e foi apanhado e morto ao fugir do campo de batalha. Com este caso, Selim pôs em grande parte termo à rivalidade pelo trono entre os seus irmãos e sobrinhos.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Paxá foi nomeado grão-vizir", "9c94c1e3"], "d": ["Segundo o artigo İbrâhîm Paşa, Makbul da Enciclopédia do Islão da TDV, İbrahim Paxá, elevado de chefe dos pajens a beylerbeyi da Rumélia e, no mesmo dia, a grão-vizir, tornou-se grão-vizir a 13 de Şâban de 929 (27 de junho de 1523). Foi uma nomeação sem precedentes, em que se passou do serviço do palácio diretamente ao grão-vizirado, e mostrava a extraordinária proximidade de İbrahim Paxá junto do Legislador.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbarossa Hayreddin Paxá foi nomeado kapudan paxá", "a0ff6bab"], "d": ["Segundo o artigo Barbaros Hayreddin Paşa da Enciclopédia do Islão da TDV, Hayreddin Paxá, conhecido pelos seus êxitos em Argel, foi chamado a Istambul a 6 de abril de 1534 e posto à frente do kapudan paxalato (kaptan-ı deryalık) e do beylerbeylik do Arquipélago (Cezâyir-i Bahr-i Sefîd). Esta nomeação é considerada o início da reestruturação da marinha otomana e da institucionalização do poder naval no Mediterrâneo.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Paxá tornou-se grão-vizir pela primeira vez", "ddfcc014"], "d": ["Segundo o artigo Rüstem Paşa da Enciclopédia do Islão da TDV, depois da destituição de Hadım Süleyman Paşa, por uma desavença com um vizir, Rüstem Paxá foi nomeado grão-vizir a 17 de Ramazan de 951 (2 de dezembro de 1544). Rüstem Paxá, cuja proximidade do palácio aumentara graças ao casamento com Mihrimah Sultan, tornou-se com este cargo um dos estadistas mais influentes do tempo do Legislador.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi tornou-se xeique do Islão", "11ed04f8"], "d": ["Segundo o artigo Ebüssuûd Efendi da Enciclopédia do Islão da TDV, Ebüssuûd Efendi, que durante oito anos fora cádi-askar da Rumélia, foi posto à frente do şeyhülislamlık em Şâban de 952 (outubro de 1545) e permaneceu neste cargo vinte e oito anos e onze meses. Conhecido pelas fetvas com que pôs em harmonia com o direito xariático os códigos (kanunnâme) do Legislador, Ebüssuûd Efendi teve um papel decisivo na formação das instituições jurídicas e de ensino da sua época.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Barbarossa Hayreddin Paxá morreu", "3378a0bf"], "d": ["Segundo o artigo Barbaros Hayreddin Paşa da Enciclopédia do Islão da TDV, depois de uma curta doença, faleceu em Istambul a 6 de Cemâziyelevvel de 953 (5 de julho de 1546). A morte de Barbarossa, sepultado no mausoléu contíguo à madraça que mandara construir em Beşiktaş, foi vista como o encerramento de uma época na supremacia mediterrânica que a marinha otomana estabelecera.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Começou a construção da Mesquita e do complexo de Süleymaniye", "101ec36f"], "d": ["Segundo o artigo Mesquita e Complexo de Süleymaniye da Enciclopédia do Islão da TDV, o complexo, cujos alicerces foram lançados em 1550 sob a direção do arquiteto-chefe Mimar Sinan, foi concebido como um grande complexo social composto, além da mesquita, por madraças, hospital, cozinha pública e biblioteca. A construção foi um dos maiores programas de edificação, simbolizando o poder do reinado do Legislador e o desenvolvimento urbano de Istambul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Começou uma nova vaga de peste em Istambul e arredores", "547d6bf6"], "d": ["Segundo o artigo Tâun da Enciclopédia do Islão da TDV, uma das epidemias do século XVI que afetaram o mundo islâmico decorreu entre 1552 e 1566 e fez-se sentir sobretudo em Istambul, na Anatólia, na Rumélia, no Egito e no Norte de África. A expansão das rotas comerciais e o aumento da mobilidade da população contam-se entre os fatores que facilitaram a propagação de doenças epidémicas no período de maior força do império.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Paxá foi nomeado grão-vizir", "a7d7748e"], "d": ["Segundo o artigo Kara Ahmed Paşa da Enciclopédia do Islão da TDV, Kara Ahmed Paxá, que servia como segundo vizir, foi elevado a grão-vizir a 27 de Şevval de 960 (5 de outubro de 1553), depois de o grão-vizir em funções ter sido de repente destituído. Esta mudança aponta para uma época em que os equilíbrios de poder dentro do palácio mudavam depressa de mãos, coincidindo com os dias da execução do príncipe Mustafa.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["O kapudan paxá Pîrî Reis foi executado", "3b2ad7a0"], "d": ["Segundo o artigo Pîrî Reis da Enciclopédia do Islão da TDV, quando chegaram ao Egito as acusações de que, ao levantar o cerco de Ormuz, saqueara em troca de suborno os bens dos muçulmanos e abandonara o seu exército no campo de batalha, o célebre navegador e cartógrafo foi executado no Cairo no fim do ano de 960 (fim de 1553). A morte de Pîrî Reis, cujos bens foram confiscados, é considerada consequência da rivalidade entre paxás na política naval de Bassorá e do oceano Índico da época.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Paxá foi executado, Rüstem Paxá voltou a ser grão-vizir", "9a85076a"], "d": ["Segundo os artigos Rüstem Paşa e Kara Ahmed Paşa da Enciclopédia do Islão da TDV, em lugar de Kara Ahmed Paxá, executado de repente durante a reunião do divã a 13 de Zilkade de 962 (29 de setembro de 1555), Rüstem Paxá foi posto no mesmo dia, pela segunda vez, no grão-vizirado, com o apoio das sultanas Hürrem e Mihrimah. Os bastidores do caso ficaram em aberto nas fontes, avaliando-se que foi consequência de intrigas dentro do palácio.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Hürrem Sultan morreu", "1ae998b5"], "d": ["Segundo o artigo Hürrem Sultan da Enciclopédia do Islão da TDV, Hürrem Sultan, que durante anos tivera grande influência dentro do palácio como haseki sultan do Legislador, faleceu em Istambul a 26 de Cemâziyelâhir de 965 (15 de abril de 1558) e foi sepultada no seu mausoléu no complexo da Mesquita de Süleymaniye. A morte de Hürrem Sultan, que consolidara a sua autoridade sobre o harém depois da morte da valide sultan Hafsa em 1534, eliminou também o efeito de equilíbrio que travava a rivalidade pelo trono entre os seus filhos Bajazeto e Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokullu Mehmed Paxá ascendeu ao grão-vizirado", "896391a2"], "d": ["Segundo o artigo Sokullu Mehmed Paşa da Enciclopédia do Islão da TDV, Sokullu Mehmed Paxá, que ascendeu ao grão-vizirado com a morte de Semiz Ali Paxá a 30 de Zilkade de 972 (29 de junho de 1565), foi o último grão-vizir do Legislador e continuou neste cargo depois dele, nos reinados de Selim II e Murad III, tornando-se um dos grão-vizires que por mais tempo serviram na história otomana.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II chegou a Istambul e foi entronizado", "0289ef97"], "d": ["Depois da morte de Solimão, o Legislador, em Szigetvár, a notícia foi mantida em segredo durante semanas por Sokullu Mehmed Paxá, para não perturbar a ordem. Segundo a Enciclopédia do Islão da TDV, Selânikî dá como data da chegada de Selim a Istambul 15 de Rebîülevvel de 974 (30 de setembro de 1566), ao passo que a maioria dos historiadores contemporâneos considera correto 9 de Rebîülevvel (24 de setembro). A morte do Legislador só foi oficialmente proclamada em Belgrado a 24-25 de outubro de 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["A frota refeita por Kılıç Ali Paxá fez-se ao mar", "d0fc9f48"], "d": ["Depois da pesada derrota de Lepanto (7 de outubro de 1571), construíram-se navios nos estaleiros durante todo o inverno. Segundo a Enciclopédia do Islão da TDV, a 1 de Safer de 980 (13 de junho de 1572), a nova frota, composta por 250 galés e cerca de 300 barcas de reises voluntários, foi lançada ao mar numa demonstração de força.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokullu Mehmed Paxá foi vítima de atentado e morto", "6ffa8dec"], "d": ["Sokullu Mehmed Paxá, que durante catorze anos foi grão-vizir em três reinados, foi apunhalado e morto a 20 de Şâban de 987 (12 de outubro de 1579) por um dervixe que se aproximou, como se fosse entregar uma petição, do divã da tarde na sua mansão. Segundo a Enciclopédia do Islão da TDV, discute-se se o atentado poderá ter relação com a vingança do xeique hamzavi executado, Hamza Bâlî.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["O primeiro ahidnâme comercial com a Inglaterra — foram dadas capitulações aos ingleses", "59c8e3ee"], "d": ["William Harborne, representante inglês enviado a Istambul em outubro de 1578, com o apoio de Sokullu Mehmed Paxá e de Hoca Sâdeddin Efendi, obteve de Murad III um ahidnâme de 1580. Com este ahidnâme, os comerciantes ingleses ganharam o direito de usufruir, no mesmo grau, dos privilégios comerciais (capitulações) antes concedidos aos franceses e aos venezianos. Entre a rainha Isabel I e Murad III trocaram-se cartas e estabeleceu-se também uma relação oficial entre os dois Estados. Logo a seguir a estes privilégios, em 1581 foi fundada em Londres a Levant Company; os ingleses conduziram o seu comércio na região por meio desta companhia até 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["O Observatório de Istambul foi demolido por hatt-ı hümâyun", "3bc0c78c"], "d": ["Sob a influência da fetva segundo a qual os observatórios trazem infortúnio aos países e da oposição dentro do palácio, o Observatório de Istambul foi demolido, com todos os seus instrumentos, por um hatt-ı hümâyun de 4 de Zilhicce de 987 (22 de janeiro de 1580). Segundo a Enciclopédia do Islão da TDV, foi o fim de curta vida da instituição fundada por Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Começou a festa de circuncisão do príncipe Mehmed no Atmeydanı", "c2926d5d"], "d": ["O príncipe Mehmed, filho de Murad III, foi circuncidado com magníficas cerimónias que começaram a 6 de Cemâziyelevvel de 990 (29 de maio de 1582) e duraram cinquenta e seis a cinquenta e sete dias. Segundo a Enciclopédia do Islão da TDV, as festas organizadas no Atmeydanı foram uma das mais esplêndidas celebrações de palácio da sua época.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["A valide sultan Nurbânû faleceu", "77d0a577"], "d": ["Nurbânû Sultan, mãe de Murad III, faleceu a 22 de Zilkade de 991 (7 de dezembro de 1583). Segundo a Enciclopédia do Islão da TDV, como valide sultan manteve correspondência com as cortes de Veneza e da França, e o senado veneziano aceitara nesse mesmo ano enviar-lhe, pelos seus serviços, um presente no valor de 2000 ducados de ouro venezianos.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Rebentou o Incidente de Beylerbeyi por causa do akçe adulterado", "db2f2e61"], "d": ["Quando o Estado passou a pagar reduzindo a proporção de prata do akçe, os sipahis e os janízaros cercaram o palácio e provocaram uma sangrenta revolta que ficou na história com o nome de Incidente de Beylerbeyi. Segundo o artigo Abdülkadir Şeyhî Efendi da Enciclopédia do Islão da TDV, o xeique do Islão foi destituído por causa deste caso.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III subiu ao trono, dezanove príncipes foram estrangulados", "2cd9a8c5"], "d": ["Mehmed III, com a morte do pai Murad III, chegou a Istambul na sexta-feira, 16 de Cemâziyelevvel de 1003 (27 de janeiro de 1595), e subiu ao trono. Segundo a Enciclopédia do Islão da TDV, na mesma noite foram estrangulados dezanove príncipes, dos quais quatro adultos (Mustafa, Bayezid, Osman e Abdullah); foi o fratricídio mais numeroso da história otomana.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan ganhou influência como valide sultan", "000bec21"], "d": ["Safiye Sultan, esposa de Murad III e mãe de Mehmed III, com a entronização do filho elevou-se, na qualidade de valide sultan, a uma posição determinante na política do palácio. Segundo a Enciclopédia do Islão da TDV, neste período a influência com origem no harém chegou à dimensão de intervenção direta nos assuntos do Estado.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III partiu em campanha pessoalmente, por pressão dos janízaros", "d3c50656"], "d": ["Apesar da oposição do grão-vizir Damad İbrahim Paxá, por pressão dos janízaros Mehmed III, como primeiro sultão a pôr-se pessoalmente à frente do exército depois de Solimão, o Legislador, partiu de Istambul em campanha a 20 de junho de 1596. Segundo a Enciclopédia do Islão da TDV, isto significava a reanimação da antiga tradição da gazâ.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["A epidemia de peste iniciada na década de 1570 continuava a afetar Istambul", "eb4ca37a"], "d": ["Segundo o artigo sobre a peste da Enciclopédia do Islão da TDV, a epidemia iniciada na década de 1570 manteve o seu efeito até ao início do século XVII e atingiu a Anatólia, os Balcãs, o Egito e o Norte de África, a começar por Istambul. Os períodos epidémicos constituíam uma ameaça crónica que interrompia com frequência a vida do palácio e da cidade.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim morreu, o movimento de revolta enfraqueceu", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, que se retirara ferido depois da pesada derrota sofrida a 12 de agosto de 1601 em Sepetli, perto de Elbistan, morreu no ano de 1010 (1602). Segundo a Enciclopédia do Islão da TDV, a notícia da morte chegou a Istambul no Ramadão do ano de 1010 (fevereiro-março de 1602); as fontes indicam que é discutido se a sua morte resultou do ferimento ou foi obra dos seus próprios homens.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["O fim de facto da tradição do fratricídio", "9046c607"], "d": ["Na sua entronização, Ahmed I, ao contrário dos sultões anteriores, não mandou matar o irmão, o príncipe Mustafa, e poupou-lhe a vida; esta decisão é considerada o início da adoção de facto, no sistema sucessório otomano, do princípio do mais velho e mais apto. O artigo \"Mustafa I\" da Enciclopédia do Islão da TDV refere que Mustafa, depois desta data, levou no palácio uma vida de reclusão. A prática pôs um fim de facto aos assassinatos de entronização que se repetiam havia séculos.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Foram lançados os alicerces da Mesquita do Sultão Ahmed", "1683262f"], "d": ["Por ordem de Ahmed I, foram lançados com cerimónia, no Atmeydanı, os alicerces da mesquita que seria construída pelo arquiteto Sedefkâr Mehmed Ağa. Segundo o artigo \"Sultan Ahmed Camii ve Külliyesi\" da Enciclopédia do Islão da TDV, o edifício foi também alvo das críticas da época por ser a primeira grande mesquita imperial construída diretamente com fundos do tesouro, sem uma vitória de conquista. O complexo foi concebido de modo a incluir, juntamente com a mesquita, uma madraça, uma cozinha pública e um mausoléu.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["O assassinato de Osman, o Jovem, pelos janízaros (Hâile-i Osmâniye)", "324f6582"], "d": ["Os janízaros e os sipahis, que se sublevaram com os rumores de que ele planeava sair de Istambul a pretexto da peregrinação e dissolver o corpo dos janízaros, depuseram Osman II e mandaram estrangulá-lo nas masmorras de Yedikule. Segundo o artigo \"Osman II\" da Enciclopédia do Islão da TDV, este caso é, na história otomana, o primeiro em que um sultão foi abertamente morto por uma revolta militar e criou uma rutura profunda na relação entre dinastia e exército. As suas últimas horas decorreram assim: como a tentativa de se refugiar na mansão do aga dos janízaros Ali Ağa não deu resultado, o sultão foi, nas palavras da TDV, 'de forma lamentável, de cabeça descoberta, em desalinho', montado num cavalo e conduzido, sob graves insultos, primeiro à Mesquita Orta, onde estava Mustafa I, e à tarde do mesmo dia a Yedikule; segundo alguns historiadores, para provar a sua morte cortaram-lhe a orelha e o nariz e mostraram-nos à mãe de Mustafa I. Depois do caso, Mustafa I foi entronizado pela segunda vez. O caso, conhecido por 'Hâile-i Osmâniye' (a tragédia de Osman), perturbou de modo duradouro o equilíbrio palácio-corpo e iniciou as polémicas sobre legitimidade que durariam um século.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["A segunda entronização de Mustafa I", "34a0b29a"], "d": ["Depois do assassinato de Osman, o Jovem, pelos janízaros, como não havia outro membro masculino adulto na dinastia, Mustafa I foi entronizado pela segunda vez. Segundo o artigo \"Mustafa I\" da Enciclopédia do Islão da TDV, também este segundo sultanato decorreu, tal como o anterior, sem que ele pudesse de facto conduzir os assuntos do Estado, e a governação ficou nas mãos dos vizires e da valide sultan. Este período, que durou catorze meses, terminou em 1623 com a entronização de Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["O Incêndio de Cibali", "3e42fb08"], "d": ["O incêndio que rebentou em Cibali e, com o efeito do vento, se propagou depressa reduziu a cinzas grande parte de Istambul; segundo o artigo \"İstanbul\" da Enciclopédia do Islão da TDV, as fontes da época referem que arderam milhares de casas. O facto de o incêndio ter sido associado ao tecido de casas de madeira e ao fumo do tabaco foi a justificação direta da dura proibição do tabaco e dos cafés que Murad IV proclamaria pouco depois. A catástrofe foi apenas um dos grandes incêndios repetidos da Istambul da época.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["A proibição do tabaco e dos cafés por Murad IV", "5dd71297"], "d": ["Depois do Incêndio de Cibali, por preocupação com o fogo e a ordem pública, Murad IV proibiu o fumo do tabaco e os cafés; aos infratores aplicaram-se penas graves, incluindo a pena de morte. Segundo o artigo \"Murad IV\" da Enciclopédia do Islão da TDV, o sultão seguiu uma política de disciplina interna tão rigorosa que percorria pessoalmente, disfarçado, as ruas da cidade para fiscalizar a proibição. Estas duras medidas são consideradas parte do esforço de Murad IV para restabelecer a autoridade central.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["A epidemia de peste em Istambul", "f33f58c5"], "d": ["No tempo de Murad IV, Istambul foi abalada por uma grave epidemia de peste que atingiu uma parte importante da população; o comércio urbano e a vida quotidiana foram perturbados durante meses. O artigo \"İstanbul\" da Enciclopédia do Islão da TDV regista que as epidemias repetidas no século XVII afetaram seriamente o equilíbrio demográfico da cidade. Durante a epidemia, o palácio e a elite mudaram-se por algum tempo para jardins e quiosques fora da cidade.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["O voo com asas de Hezarfen Ahmed Çelebi (tradição)", "df474c04"], "d": ["Segundo a tradição transmitida por Evliya Çelebi, Hezarfen Ahmed Çelebi conseguiu, com asas feitas por ele próprio, saltar da Torre de Gálata e planar até Üsküdar; embora a sua certeza histórica seja discutida, tornou-se símbolo da imaginação técnica. O sultão, que a princípio recompensara Hezarfen, desterrou-o depois para Argel, devido ao eco que o caso causou.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["A ascensão da influência de Cinci Hoca Hüseyin Efendi no palácio", "41d21572"], "d": ["Hüseyin Efendi, curandeiro chamado ao palácio para tratar as perturbações psíquicas do sultão Ibrahim, ganhou em pouco tempo a confiança do sultão e subiu até cádi-askar da Anatólia. Segundo o artigo \"Hüseyin Efendi, Cinci Hoca\" da Enciclopédia do Islão da TDV, usou esta influência para acumular fortuna e interferir nos acontecimentos políticos da época. Depois da morte de Ibrahim foi destituído de todos os cargos e executado em 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["A execução de Kemankeş Mustafa Paxá", "0ecc8030"], "d": ["Kemankeş Mustafa Paxá, grão-vizir desde o tempo de Murad IV e que, com as suas reformas financeiras, dera ao tesouro um excedente importante, foi estrangulado e executado depois de os seus rivais dentro do palácio terem influenciado Ibrahim e de ter sido acusado de provocar uma revolta de janízaros. Segundo o artigo \"Kemankeş Mustafa Paşa\" da Enciclopédia do Islão da TDV, a execução ocorreu a 21 de Zilkade de 1053 / 31 de janeiro de 1644: Kemankeş Kara Mustafa Paxá foi estrangulado no Bazar de Hocapaşa pelo carrasco Kara Ali e sepultado no seu próprio mausoléu em Çarşıkapı. A sua morte é recordada como exemplo impressionante da instabilidade do cargo de grão-vizir na época e pôs fim a um breve período de reforma rigorosa.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["A decisão da Campanha de Creta no divã e a partida da frota", "9076827e"], "d": ["A abertura de uma grande campanha contra a ilha de Creta, pertencente a Veneza, foi decidida no Divan-ı Hümayun, e a frota otomana, sob o comando do kapudan paxá, partiu de Istambul para Creta. Segundo o artigo \"Girit\" da Enciclopédia do Islão da TDV, esta decisão constituiu o início político de um longo período de cerco e guerra que duraria cerca de vinte e cinco anos. A abertura da campanha, como maior iniciativa de política externa do reinado de Ibrahim, suscitara amplas discussões entre os dignitários do Estado.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["A entronização de Mehmed IV aos sete anos", "a197a3bc"], "d": ["Logo a seguir à deposição de Ibrahim, o seu filho Mehmed, de apenas sete anos, foi elevado ao trono e tornou-se sultão com o título de Mehmed IV. Segundo o artigo \"Mehmed IV\" da Enciclopédia do Islão da TDV, a subida ao trono em tão tenra idade acirrou a luta de influência dentro do palácio entre a avó Kösem Sultan e a mãe Turhan Sultan. Esta luta pelo poder resultaria, em 1651, no assassinato de Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["A reforma do orçamento equilibrado de Tarhuncu Ahmed Paxá", "376fc7f2"], "d": ["O grão-vizir Tarhuncu Ahmed Paxá, para superar a crise financeira causada pelos longos anos de guerra, aplicou um duro programa de poupança que abrangia também as despesas do palácio e preparou o primeiro orçamento equilibrado conhecido da história otomana (o projeto de Tarhuncu, tarhuncu lâyihası). Segundo o artigo \"Tarhuncu Ahmed Paşa\" da Enciclopédia do Islão da TDV, esta reforma deu ao tesouro um excedente importante, mas criou um amplo descontentamento nos círculos do palácio e na alta burocracia. Este descontentamento resultaria, um ano depois, na sua execução.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["O Incidente do Plátano (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Segundo o artigo Çınar Vak'ası da Enciclopédia do Islão da TDV, os janízaros e sipahis que regressaram sem soldo da campanha de Creta sublevaram-se em Istambul e exigiram a execução de dignitários do Estado que acusavam de corrupção. A proposta de confisco e exílio do grão-vizir Zurnazen Mustafa Paxá não foi aceite; primeiro três funcionários e depois cerca de trinta dignitários foram executados e os seus cadáveres foram pendurados nos plátanos da Praça do Sultão Ahmed. Por isso, o caso ficou conhecido como Incidente do Plátano.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["A nomeação de Köprülü Mehmed Paxá como grão-vizir, com aceitação condicionada", "3a6b7f8f"], "d": ["Segundo o artigo Köprülü Mehmed Paşa da Enciclopédia do Islão da TDV, Köprülü Mehmed Paxá, de perto de oitenta anos, só recebeu o selo depois de fazer aceitar à valide Turhan Sultan e a Mehmed IV condições pesadas — que não se interferisse nas suas nomeações e que não se acreditasse no que se dissesse contra ele. Assumiu funções a 26 de Zilkade de 1066, em lugar de Boynueğri Mehmed Paxá, e empenhou-se em restabelecer com dureza a disciplina do Estado.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["A repressão do movimento dos Kadızadelis por Köprülü Mehmed Paxá", "5ec3ce84"], "d": ["Segundo o artigo Kadızâdeliler da Enciclopédia do Islão da TDV, logo que assumiu funções, Köprülü Mehmed Paxá tratou do conflito religioso entre o círculo de Kadızâde Mehmed Efendi e os adeptos das confrarias. Depois de consultar os ulemás, emitiu um firmão de execução para os dirigentes do movimento Üstüvânî Mehmed Efendi, Türk Ahmed e Divâne Mustafa, mas esta pena foi comutada em exílio e os três foram enviados para Chipre; assim terminou a segunda fase do movimento.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["O grande incêndio de Istambul: a destruição de Ağakapısı", "b9253b66"], "d": ["Segundo o artigo Ağakapısı da Enciclopédia do Islão da TDV, no grande incêndio que rebentou em julho de 1660, no tempo de Mehmed IV, a Ağakapısı, quartel-general oficial do aga dos janízaros, ardeu por completo e foi em seguida reconstruída. Este incêndio foi um dos grandes incêndios urbanos que atingiram repetidamente a Istambul da época.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["A nomeação de Köprülüzâde Fâzıl Ahmed Paxá como grão-vizir", "c1999b5c"], "d": ["Segundo o artigo Köprülüzâde Fâzıl Ahmed Paşa da Enciclopédia do Islão da TDV, com a morte do pai, Köprülü Mehmed Paxá, foi posto no grão-vizirado a 8 de Rebîülevvel de 1072 (1 de novembro de 1661). Ao contrário do pai, conhecido como de temperamento suave, devoto e protetor de sábios e artistas, Fâzıl Ahmed Paxá, durante o seu grão-vizirado de mais de quinze anos, mandou fundar bibliotecas e instituições de caridade em Istambul e nos territórios conquistados.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["A nomeação de Vânî Mehmed Efendi como pregador da Yeni Cami e preceptor do sultão", "7ea6aaae"], "d": ["Segundo o artigo Mehmed Efendi, Vânî da Enciclopédia do Islão da TDV, Vânî Mehmed Efendi, chamado a Istambul com a ascensão de Köprülüzâde Fâzıl Ahmed Paxá e apresentado a Mehmed IV, ganhou em pouco tempo o estreito interesse do sultão. Em 1665 foi posto como pregador da Yeni Cami e preceptor do sultão e tornou-se um dos homens de religião mais influentes do palácio.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["A nomeação de Merzifonlu Kara Mustafa Paxá como grão-vizir", "3d1e836c"], "d": ["Segundo o artigo Merzifonlu Kara Mustafa Paşa da Enciclopédia do Islão da TDV, com a morte de Fâzıl Ahmed Paxá foi posto no grão-vizirado a 28 de Şâban de 1087 (5 de novembro de 1676). Genro e discípulo da família Köprülü, com longa experiência na governação do Estado, Merzifonlu tornou-se um dos grão-vizires mais fortes e influentes de Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["A morte de Vânî Mehmed Efendi no exílio", "cda714aa"], "d": ["Segundo o artigo Mehmed Efendi, Vânî da Enciclopédia do Islão da TDV, Vânî Mehmed Efendi, considerado um dos principais nomes que fizeram o sultão aceitar a campanha de Viena, foi, depois de a campanha terminar em desastre, caído em desgraça por pressão da opinião pública e exilado para a vila de Kestel, em Bursa. Faleceu aí a 14 de Zilkade de 1096 (12 de outubro de 1685) e foi sepultado à entrada da mesquita que mandara construir.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["A nomeação de Köprülüzâde Fâzıl Mustafa Paxá como grão-vizir e as suas reformas financeiras", "b048570e"], "d": ["Segundo o artigo Köprülüzâde Fâzıl Mustafa Paşa da Enciclopédia do Islão da TDV, Fâzıl Mustafa Paxá, posto no grão-vizirado a 11 de Muharrem de 1101 (25 de outubro de 1689), reorganizou o processo de cobrança da cizye segundo princípios xariáticos, combateu a inflação do mangır e reforçou o tesouro transferindo recursos das instituições do palácio. Além disso, reforçou a administração provincial com funcionários de confiança e mandou criar conselhos locais semelhantes ao divã central.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["A entrada em vigor do sistema malikâne", "316b8426"], "d": ["Segundo o artigo Mâlikâne da Enciclopédia do Islão da TDV, no último quartel do século XVII o aumento das despesas de guerra e a diminuição das receitas por perdas de território lançaram o tesouro numa grave crise financeira. No sistema malikâne, que entrou em vigor no ano de 1106 (1695), concedeu-se aos arrendatários o direito vitalício a um imposto fixo, introduzindo-se um incentivo à preservação da produção em vez da exploração a curto prazo.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["A entronização de Mustafa II", "b53656c7"], "d": ["Segundo o artigo Mustafa II da Enciclopédia do Islão da TDV, Mustafa II, que subiu ao trono aos trinta e um anos, proclamou o seu sultanato sem esperar a aprovação do grão-vizir e do xeique do Islão (şeyhülislam); a cerimónia de cingir a espada realizou-se alguns dias depois na Eski Cami. O sultão, que subiu ao trono num período em que prosseguiam as guerras em várias frentes depois do desastre de Viena, foi o último sultão otomano a sair pessoalmente em campanha.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["A nomeação de Feyzullah Efendi, pela segunda vez, como xeique do Islão (şeyhülislam)", "1cf14cff"], "d": ["Segundo o artigo Feyzullah Efendi, Seyyid da Enciclopédia do Islão da TDV, depois da entronização de Mustafa II foi posto pela segunda vez no şeyhülislamlık a 11 de Şevval de 1106 (25 de maio de 1695). A sua influência sobre o sultão foi crescendo durante este período no cargo, que durou mais de oito anos.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["A colocação dos filhos de Feyzullah Efendi em altos cargos e a reação acumulada", "a6398280"], "d": ["Segundo o artigo Feyzullah Efendi, Seyyid da Enciclopédia do Islão da TDV, o xeique do Islão (şeyhülislam) obteve de Mustafa II um firmão sem precedentes segundo o qual o seu filho Fethullah Efendi seria xeique do Islão depois dele e colocou os seus parentes, em tenra idade, em altos cargos. Estas práticas criaram um amplo descontentamento entre a classe científico-religiosa, o exército e o povo de Istambul; juntando-se aos rumores de que a capital seria transferida para Edirne, prepararam o terreno ao Incidente de Edirne de 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["O início do Incidente de Edirne", "5a106458"], "d": ["Segundo o artigo \"Edirne Vak'ası\" da TDV, o movimento, iniciado com a revolta de soldados que não recebiam os soldos, converteu-se em pouco tempo numa vasta insurreição em que participaram janízaros, estudantes de madraça, artesãos e povo. O alvo principal da revolta era o xeique do Islão (şeyhülislam) Feyzullah Efendi, de quem se dizia que interferia excessivamente nos assuntos do Estado. Uma multidão de cerca de 60.000 pessoas marchou de Istambul para Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["O grão-vizirado de Nevşehirli Damad İbrahim Paxá", "8d627a6f"], "d": ["Segundo o artigo \"Damad İbrâhim Paşa, Nevşehirli\" da TDV, durante as negociações de paz em curso com a Áustria, foi posto no cargo de grão-vizir a 8 de Cemâziyelâhir de 1130 (9 de maio de 1718) e, logo que nomeado, orientou-se para as negociações que poriam fim à guerra; dois meses depois foi assinado o Tratado de Požarevac (21 de julho de 1718). Nas palavras da TDV, 'queria ocupar-se de questões sociais e financeiras, aspirava a um período de paz que fizesse esquecer as guerras que, havia muitos anos, terminavam em derrota'. Fez reformas nas finanças, reduziu os soldos dos soldados e formou um excedente importante no tesouro do Estado. O seu grão-vizirado, que duraria doze anos, constituiu o quadro político do período que leva o seu nome (Período das Tulipas, Lâle Devri).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["A fundação do Corpo dos Bombeiros", "f58b0d97"], "d": ["Segundo o artigo \"Tulumbacı\" da TDV, tendo Gerçek Dâvud, regressado da campanha da Moreia de 1715, mostrado êxito com a bomba nos incêndios de Istambul, o grão-vizir Nevşehirli Damad İbrahim Paxá encarregou-o de fundar um corpo oficial de bombeiros. O corpo, fundado no Quartel dos Acemi Oğlanları com seis oficiais e cinquenta soldados, chegou a 150 em 1724 e a 461 em 1755. Dâvud permaneceu à frente do corpo até à sua morte, em 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["A receção de Mehmed Efendi por Luís XV", "0ff5b174"], "d": ["Segundo o artigo \"Yirmisekiz Çelebi Mehmed Efendi\" da TDV, o embaixador foi recebido oficialmente no Palácio das Tulherias pelo rei de França Luís XV e apresentou os presentes e a carta de Ahmed III. Durante a visita, visitou os palácios de Versalhes, Trianon e Marly, hospitais, observatórios e manufaturas; registou o que viu em desenhos.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["O regresso de Mehmed Efendi a Istambul", "a09a8bba"], "d": ["Segundo o artigo \"Yirmisekiz Çelebi Mehmed Efendi\" da TDV, as observações do embaixador, de regresso da embaixada de um ano em Paris, influenciaram o gosto arquitetónico do Período das Tulipas. O facto de o filho ter trabalhado depois com İbrahim Müteferrika preparou o terreno à fundação da primeira tipografia turca, a herança mais duradoura da embaixada.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["A construção do Palácio de Sâdâbâd", "aec9c65e"], "d": ["Segundo o artigo \"Sâdâbâd\" da TDV, na margem do ribeiro de Kağıthane foi construído um vasto complexo de recreio e de passeio, formado por palácios, canais, fontes e quiosques inspirados na arquitetura palaciana francesa. Sâdâbâd, que se tornou o lugar de diversão mais apreciado da época, ficou imortalizado nos poemas do poeta Nedîm. O complexo foi em grande parte destruído durante a Revolta de Patrona Halil de 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["A tomada de Derbent pelas forças russas: a campanha do Cáspio de Pedro I", "c2b269f9"], "d": ["Quando o Estado Safávida foi arrastado para a confusão interna pela invasão afegã, o czar russo Pedro I partiu em campanha com o fim de tomar as terras persas da costa do Cáspio; a cidade costeira de Derbent rendeu-se às forças russas sem resistência digna de nota. Segundo o artigo Derbend da Enciclopédia do Islão da TDV, esta ocupação foi o início de um domínio russo provisório que duraria treze anos; o Estado Otomano, aproveitando a mesma confusão, voltou-se para a parte ocidental do Cáucaso. O exército desembarcara de Astracã, por via marítima, no golfo de Agrakhan e daí marchara por terra ao longo da costa, por Tarku; o şamhal de Tarku, depois de acolher Pedro, passou à sujeição russa.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["A abolição do şamhalado de Tarku: administração russa direta", "b0f029c6"], "d": ["O şamhal de Tarku Adil-Girey, que em 1722 acolhera Pedro e passara à sujeição russa, revoltou-se em 1725; Yeropkin destruiu Tarku no outono de 1725, o şamhal foi preso e exilado em meados de maio de 1726 e o şamhalado foi abolido. Tarku e os arredores permaneceram sob administração russa direta até ao Tratado de Gence de 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["A licença a İbrahim Müteferrika para fundar uma tipografia", "0659dd0a"], "d": ["Segundo o artigo \"İbrâhim Müteferrika\" da TDV, por firmão de Ahmed III e por fetva do xeique do Islão (şeyhülislam) Yenişehirli Abdullah Efendi, foi permitida a fundação da primeira tipografia turca. A tipografia entrou em funcionamento no bairro de Yavuzselim, em Istambul. Müteferrika imprimiu, até à sua morte em 1747, dezassete obras em vinte e três volumes.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["A conclusão do primeiro livro impresso, o Dicionário de Vankulu", "684700e8"], "d": ["Segundo o artigo \"İbrâhim Müteferrika\" da TDV, a tradução turca do Sıhâhu'l-Cevherî (Vankulu Lügati), primeira obra da tipografia, ficou concluída no início de 1729. Foi o primeiro livro impresso em caracteres árabes em terras otomanas e é considerado o início da história da tipografia turca.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["A execução de Nevşehirli Damad İbrahim Paxá", "50c64341"], "d": ["Segundo o artigo \"Damad İbrâhim Paşa, Nevşehirli\" da TDV, o cadáver do grão-vizir, morto no palácio durante a Revolta de Patrona Halil, foi arrastado pelas ruas de Istambul e abandonado junto à Fonte de Ahmed III, na Praça do Sultão Ahmed. O grão-vizirado de doze anos e o Período das Tulipas terminaram assim de forma sangrenta.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["A abdicação de Ahmed III, a entronização de Mahmud I", "a43f5d40"], "d": ["Segundo o artigo \"Mahmud I\" da TDV, perante a pressão dos insurretos, Ahmed III abdicou depois de obter garantias para si e para os filhos e foi ele próprio a elevar ao trono o sobrinho, o príncipe Mahmud. Mahmud I, que se sentou no trono com o conselho do tio \"toma nas tuas mãos os assuntos do Estado, não confies em ninguém\", procurou, como primeira medida, quebrar a influência do grupo de insurretos que o pusera no trono.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["A reforma do corpo de artilharia por Humbaracı Ahmed Paxá", "ea3a7c64"], "d": ["Segundo o artigo \"Humbaracı\" da TDV, o oficial de origem francesa Ahmed Paxá, convertido ao Islão, empenhou-se, no tempo do grão-vizir Hekimoğlu Ali Paxá, na reforma à europeia da organização assalariada dos bombardeiros. Criou uma nova estrutura de 601 pessoas, dependente diretamente do grão-vizir, com 300 assalariados e 301 timarlis. Mandou produzir, com a tecnologia da época, 100 morteiros e 50.000 balas.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["A fundação da Hendesehâne (o primeiro exemplo de escola de engenharia)", "a77ed1f3"], "d": ["Segundo o artigo \"Mahmud I\" da TDV, Humbaracı Ahmed Paxá, ao fundar em Üsküdar a Hendesehâne, também chamada Humbarahâne, deu uma instrução militar assente na matemática e na geometria aos alunos escolhidos entre os servidores do palácio e os bostancıs. Esta instituição é considerada o primeiro exemplo das escolas de engenharia que se desenvolveriam mais tarde.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["O Tratado de Gence: a devolução de Derbent e Baku ao Irão", "ff19d531"], "d": ["A Rússia, que buscava aliança com o Irão contra a ameaça otomana, devolveu, pelo Tratado de Gence, ao Irão comandado por Nadir Han (que ainda não tomara o título de xá) as cidades da costa do Cáspio que detinha havia treze anos. Segundo o artigo Derbend da Enciclopédia do Islão da TDV, esta retirada foi consequência de a Rússia não querer lutar em duas frentes ao mesmo tempo no sul (otomana e persa) e consolidou o prestígio militar de Nadir, que abriu o caminho à sua subida ao trono poucos anos depois. Tarki (Tarku), sob administração russa, voltou também com esta retirada para o lado persa (no mapa usa-se o dia de Gence).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["A subida de Nadir Xá ao trono na planície de Mugan: o fim de facto da dinastia safávida", "4f640979"], "d": ["Segundo o artigo Nadir Şah da Enciclopédia do Islão da TDV, o kurultai de cerca de vinte mil pessoas reunido na planície de Mugan pediu com insistência que ele se pusesse à frente do Irão; Nadir aceitou esta proposta com a condição de que se abandonasse a concepção xiita extremada que causara as guerras entre safávidas e otomanos e se adotasse a escola moderada jafarita, e subiu ao trono com o título de Nâdir Şah a 24 de Şevval de 1148 (8 de março de 1736). Isto significava o fim de facto da dinastia safávida de dois séculos e a fundação da dinastia dos Afsharidas.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["O início da epidemia de peste em Istambul", "9fa82b56"], "d": ["Segundo o artigo \"Tâun\" da TDV, a epidemia de peste que atuou na geografia islâmica entre 1739 e 1743 atingiu também Istambul nesta época. O artigo indica que as epidemias do século XVIII decorreram de forma relativamente mais leve do que as dos séculos anteriores. Entre os períodos epidémicos contam-se também os anos de 1713, 1719, 1728-1729 e 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["O incêndio de Hocapaşa", "321c7d0d"], "d": ["Segundo o artigo \"Fatma Sultan Camii\" da TDV, o incêndio de Hocapaşa, que rebentou de noite, devastou a Sublime Porta e os arredores; supõe-se que a Mesquita de Fatma Sultan, na região, sofreu também danos neste incêndio. Esta catástrofe, um dos grandes incêndios que atingiram Istambul no tempo de Osman III, causou graves destruições no centro comercial e administrativo da cidade.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["O grão-vizirado de Koca Ragıp Mehmed Paxá", "a1846910"], "d": ["Ragıp Paxá, conhecido como poeta e diplomata, foi posto por Osman III no cargo de grão-vizir (em outubro de 1757, com a morte de Osman III, continuou em funções e recebeu o novo selo de Mustafa III). Enquanto prosseguiam as Guerras dos Sete Anos, seguiu uma política externa equilibrada que manteve o Estado Otomano fora dos conflitos na Europa. Durante o seu grão-vizirado, que duraria seis anos, deu também importância a atividades culturais, como a fundação de bibliotecas.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["A morte de Ragıp Paxá", "6bc19323"], "d": ["Ragıp Paxá faleceu depois de um grão-vizirado de seis anos. Com a sua morte terminou o grão-vizirado mais duradouro e equilibrado do tempo de Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["O grande sismo de Istambul e a ruína da Mesquita de Fatih", "2475b4dc"], "d": ["Segundo o artigo \"Fâtih Camii ve Külliyesi\" da TDV, no grande sismo de 1766 a cúpula principal da mesquita ruiu por completo e as paredes sofreram danos que não podiam ser reparados. A reconstrução, iniciada em 1767 por ordem de Mustafa III sob a direção dos arquitetos Sarım İbrahim Efendi e İzzet Mehmed Bey, foi concluída em 1771, com um novo projeto diferente do antigo plano.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["A tentativa de escola de artilharia de curta vida sob a liderança do barão de Tott", "4192260c"], "d": ["Segundo o artigo \"Mühendishâne-i Bahrî-i Hümâyun\" da TDV, os fracassos da guerra otomano-russa de 1768 puseram em evidência a necessidade de instrução militar técnica; a escola de artilharia de curta vida, aberta com a contribuição do oficial francês barão de Tott, entrou em funcionamento em outubro de 1772, mas foi ineficaz. Esta tentativa é considerada precursora da Mühendishâne-i Bahrî-i Hümâyun, que seria fundada em 1775.", "1b031ce8"]}
});
